    'a_critical_action_you_will_confirm_your_password_first_879761cf' => 'Πρόκειται για κρίσιμη ενέργεια. Πρέπει πρώτα να επιβεβαιώσετε τον κωδικό πρόσβασής σας.',
    'a_directory_provisions_one_organization_s_people_7b70fa4a' => 'Ένας κατάλογος διαχειρίζεται την παροχή λογαριασμών για έναν οργανισμό.',
    'a_domain_is_claimed_by_one_organization_and_proved_with_85c4b058' => 'Ένας τομέας κατοχυρώνεται από έναν οργανισμό, ο οποίος επιβεβαιώνει την κυριότητά του με μια εγγραφή DNS. Μετά την επαλήθευση, όλοι οι χρήστες με διεύθυνση σε αυτόν τον τομέα μπορούν να οδηγούνται απευθείας στην ενιαία σύνδεση του οργανισμού.',
    'a_flag_lets_you_ship_a_feature_dark_and_turn_it_on_for_77bad22e' => 'Μια σημαία λειτουργίας σάς επιτρέπει να διαθέσετε μια λειτουργία απενεργοποιημένη και να την ενεργοποιήσετε για τους πρώτους επιλεγμένους χρήστες, χωρίς νέα ανάπτυξη.',
    'a_new_key_with_the_same_scopes_and_approval_policy_is_c_c8fff425' => 'Δημιουργείται ένα νέο κλειδί με τα ίδια πεδία πρόσβασης και την ίδια πολιτική έγκρισης και εμφανίζεται μόνο μία φορά. Το τρέχον κλειδί συνεχίζει να λειτουργεί για 24 ώρες, ώστε τα συστήματα που το χρησιμοποιούν να αλλάξουν κλειδί χωρίς διακοπή.',
    'a_publishable_key_lets_a_page_sign_people_in_without_a_f1562297' => 'Ένα δημοσιεύσιμο κλειδί επιτρέπει σε μια σελίδα να συνδέει χρήστες χωρίς δικό σας backend. Είναι σκόπιμα δημόσιο· η λίστα επιτρεπόμενων προελεύσεων εμποδίζει τη χρήση του από άλλους ιστοτόπους.',
    'a_rule_names_two_or_more_roles_that_must_never_sit_with_376dbd9e' => 'Ένας κανόνας ορίζει δύο ή περισσότερους ρόλους που δεν πρέπει ποτέ να έχει το ίδιο άτομο. Για παράδειγμα, όποιος δημιουργεί μια πληρωμή δεν πρέπει να την εγκρίνει κιόλας.',
    'a_scim_endpoint_we_push_your_people_to_joins_changes_an_629f70bd' => 'Ένα τελικό σημείο SCIM στο οποίο στέλνουμε τα στοιχεία των χρηστών σας. Οι προσθήκες, οι αλλαγές και οι αποχωρήσεις αποστέλλονται τη στιγμή που συμβαίνουν.',
