    'register_repoint_pause_resume_re_key_and_delete_webhook_59f2b3cf' => 'Καταχώριση endpoint webhook, αλλαγή προορισμού, παύση, συνέχιση, αλλαγή κλειδιών και διαγραφή. Ένα νέο ή αντικατασταθέν μυστικό υπογραφής εμφανίζεται μόνο μία φορά.',
    'register_pause_activate_and_remove_hooks_endpoints_that_17dc8c62' => 'Καταχώριση, παύση, ενεργοποίηση και αφαίρεση hook — endpoint που μπορούν να προσθέτουν claims σε διακριτικά ή να απορρίπτουν μια σύνδεση.',
    'create_disable_resume_and_delete_audit_log_streams_a_ge_d507a36c' => 'Δημιουργία, απενεργοποίηση, συνέχιση και διαγραφή ροών αρχείων ελέγχου. Το παραγόμενο κλειδί υπογραφής εμφανίζεται μόνο μία φορά.',
    'record_audit_events_your_app_s_users_cause_for_the_orga_a94adc1d' => 'Καταγραφή συμβάντων ελέγχου που προκαλούν οι χρήστες της εφαρμογής σας, για τους οργανισμούς όπου συμβαίνουν. Μόνο όσα χρειάζεται ένα backend που στέλνει συμβάντα.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Ανάγνωση των συμβάντων ελέγχου που έστειλε η εφαρμογή σας και των εξαγωγών τους, επαλήθευση της αλυσίδας ενός οργανισμού και προβολή των σχημάτων και των κανόνων διατήρησής τους.',
    'start_csv_exports_of_the_audit_events_your_app_sent_the_230b66c5' => 'Έναρξη εξαγωγών CSV των συμβάντων ελέγχου που έστειλε η εφαρμογή σας — των ίδιων συμβάντων που εμφανίζει το πεδίο δικαιωμάτων ανάγνωσης, σε ένα αρχείο.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Ορισμός, αντικατάσταση και διαγραφή των σχημάτων επικύρωσης συμβάντων ελέγχου και αλλαγή του χρόνου διατήρησης — η μείωσή του διαγράφει οριστικά τα παλαιότερα συμβάντα.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Ανάγνωση του σχήματος εξουσιοδότησης και των πλειάδων του, έλεγχοι πρόσβασης και ερωτήματα λίστας — «Μπορεί αυτός ο χρήστης να επεξεργαστεί αυτό το έγγραφο;», «Ποια έγγραφα μπορεί να δει;». Μόνο όσα χρειάζεται το backend μιας εφαρμογής για να εφαρμόζει τους κανόνες πρόσβασης.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Εγγραφή και διαγραφή πλειάδων σχέσεων — ποιος κατέχει, επεξεργάζεται ή βλέπει ποιους πόρους της εφαρμογής σας. Η εγγραφή παραχωρεί ή ανακαλεί αμέσως την πρόσβαση στην εφαρμογή.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Αντικατάσταση του σχήματος εξουσιοδότησης — των τύπων πόρων και του τρόπου αξιολόγησης κάθε σχέσης. Αλλάζει αμέσως την απάντηση σε κάθε έλεγχο αυτού του περιβάλλοντος.',
    'read_the_authentication_policy_the_social_login_provide_758352e3' => 'Ανάγνωση της πολιτικής ελέγχου ταυτότητας, των παρόχων σύνδεσης μέσω κοινωνικών δικτύων και της δήλωσης παλαιού τρόπου σύνδεσης — ποτέ το μυστικό ενός παρόχου.',
    'change_password_mfa_and_sso_rules_self_service_sign_up_66c7cb03' => 'Αλλαγή κανόνων κωδικών πρόσβασης, MFA και SSO, αυτοεγγραφής, παρόχων σύνδεσης μέσω κοινωνικών δικτύων και έγκρισης παλαιού τρόπου σύνδεσης.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Προβολή της λειτουργίας Radar, των ενσωματωμένων και προσαρμοσμένων κανόνων, των λιστών αποδοχής και αποκλεισμού και της εξερεύνησης αποφάσεων — γιατί μια σύνδεση ή εγγραφή επιτράπηκε, υποβλήθηκε σε πρόσθετη επαλήθευση ή αποκλείστηκε. Ποτέ IP ή άλλη διεύθυνση από μια απόφαση.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Δημιουργία, αναδιάταξη και διαγραφή κανόνων Radar, ρύθμιση των ενσωματωμένων κανόνων και προσθήκη ή αφαίρεση καταχωρίσεων από τις λίστες αποδοχής και αποκλεισμού.',
    'switch_radar_between_monitor_record_only_and_enforce_bl_c3ec2073' => 'Εναλλαγή του Radar μεταξύ παρακολούθησης (μόνο καταγραφή) και επιβολής (αποκλεισμός και πρόσθετη επαλήθευση) — ενεργοποίηση ή απενεργοποίηση της προστασίας σύνδεσης του περιβάλλοντος.',
