    'create_rename_re_permission_and_delete_roles_and_author_dca95601' => 'Δημιουργία, μετονομασία, αλλαγή δικαιωμάτων και διαγραφή ρόλων, καθώς και ορισμός των χειροκίνητων δικαιωμάτων που τους αποτελούν. Η εκχώρηση ρόλων σε άτομα απαιτεί `roles:write`.',
