    'list_the_downstream_scim_targets_this_environment_pushe_2753c203' => 'Προβολή των προορισμών SCIM στους οποίους αυτό το περιβάλλον στέλνει χρήστες και τυχόν αποτυχιών τους — ποτέ των διαπιστευτηρίων τους.',
