    'read_role_conflict_segregation_of_duties_rules_and_acce_8572d9a3' => 'Ανάγνωση κανόνων σύγκρουσης ρόλων (διαχωρισμού καθηκόντων) και ελέγχων πρόσβασης, μαζί με κάθε στοιχείο που ζητείται να επιβεβαιωθεί.',
    'define_switch_and_remove_role_conflict_rules_open_acces_34e40e6c' => 'Ορισμός, ενεργοποίηση, απενεργοποίηση και αφαίρεση κανόνων σύγκρουσης ρόλων· έναρξη ελέγχων πρόσβασης, καταγραφή αποφάσεων και ολοκλήρωσή τους — η ολοκλήρωση εφαρμόζει κάθε ανάκληση.',
    'list_the_downstream_credentials_stored_in_the_token_vau_15a080ce' => 'Προβολή των διαπιστευτηρίων εξωτερικών συστημάτων που αποθηκεύονται στο θησαυροφυλάκιο διακριτικών και των εφαρμογών που μπορούν να αποκτούν προσωρινή πρόσβαση σε καθένα — ποτέ των αποθηκευμένων τιμών.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Αποθήκευση, αντικατάσταση και ανάκληση διαπιστευτηρίων εξωτερικών συστημάτων, καθώς και παραχώρηση ή αφαίρεση του δικαιώματος προσωρινής πρόσβασης μιας εφαρμογής. Δεν είναι τα πεδία δικαιωμάτων vault.manage / vault.lease του διακριτικού της ίδιας της εφαρμογής.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Προβολή των σημαιών λειτουργιών και της στόχευσής τους, και αξιολόγηση κάθε σημαίας για έναν χρήστη σε έναν οργανισμό — αυτό που ζητά το backend μιας εφαρμογής όταν δεν διαθέτει διακριτικό.',
    'define_switch_retarget_and_delete_feature_flags_which_f_e64692af' => 'Ορισμός, ενεργοποίηση, απενεργοποίηση, αλλαγή στόχευσης και διαγραφή σημαιών λειτουργιών — ποιες λειτουργίες αποκτούν ποιοι χρήστες και οργανισμοί.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Προβολή των τρίτων παρόχων στους οποίους οι χρήστες μπορούν να συνδέσουν λογαριασμούς, των εφαρμογών που δικαιούνται προσωρινή πρόσβαση στα διακριτικά και των χρηστών που έχουν συνδεθεί — ποτέ μυστικά πελάτη ή διακριτικά.',
    'configure_change_and_remove_pipes_grant_or_withdraw_an_f69a04e9' => 'Ρύθμιση, αλλαγή και αφαίρεση pipes, παραχώρηση ή αφαίρεση του δικαιώματος μιας εφαρμογής για προσωρινή πρόσβαση στα διακριτικά συνδεδεμένων λογαριασμών και αποσύνδεση λογαριασμού χρήστη.',
    'list_an_organization_s_recent_admin_portal_links_what_e_f1c55153' => 'Προβολή των πρόσφατων συνδέσμων της Πύλης διαχείρισης ενός οργανισμού: τι ανοίγει ο καθένας, ποιος τον δημιούργησε, σε ποιον εστάλη και ποια είναι η κατάστασή του — ποτέ ο ίδιος ο σύνδεσμος.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Δημιουργία και ανάκληση συνδέσμου μίας χρήσης για την Πύλη διαχείρισης, που επιτρέπει στον διαχειριστή IT ενός οργανισμού να ρυθμίσει SSO, τομείς ή συγχρονισμό καταλόγων χωρίς λογαριασμό. Ο νέος σύνδεσμος εμφανίζεται μόνο μία φορά.',
    'list_the_pending_requests_from_agents_to_act_as_one_of_67e57ec8' => 'Προβολή των εκκρεμών αιτημάτων πρακτόρων για ενέργειες εκ μέρους ενός χρήστη αυτού του περιβάλλοντος (OIDC CIBA): ποια εφαρμογή, για ποιον και τι ζητά.',
