    'framework_7987d4a55127' => 'Το `:id` δεν είναι έγκυρο αναγνωριστικό: 1–128 εκτυπώσιμοι χαρακτήρες χωρίς κενά, `#` ή `@` (το `*` μόνο του είναι δεσμευμένο).',
    'framework_cb3532539c49' => 'Το `:field` υπερβαίνει τους 64 χαρακτήρες.',
    'framework_13b008a5afb9' => 'Το `:value1` δεν είναι έγκυρο όνομα τύπου: χρησιμοποιήστε πεζά γράμματα, ψηφία, `_` και `-`, ξεκινώντας με γράμμα.',
    'framework_8aacc62aa689' => 'Το `:value1` δεν είναι έγκυρο όνομα σχέσης: χρησιμοποιήστε πεζά γράμματα, ψηφία, `_` και `-`, ξεκινώντας με γράμμα.',
    'framework_eee8e9c331cf' => 'Αυτό το περιβάλλον δεν έχει ακόμη σχήμα εξουσιοδότησης. Ορίστε πρώτα ένα.',
    'framework_cfe56b92f811' => 'Το νέο σχήμα θα άφηνε υπάρχουσες πλειάδες χωρίς έγκυρους ορισμούς — διαγράψτε τες πρώτα: :messages.',
    'framework_6a37f71390b0' => 'Το νέο σχήμα θα άφηνε υπάρχουσες πλειάδες χωρίς έγκυρους ορισμούς — διαγράψτε τες πρώτα: :messages· και άλλες.',
    'framework_5736a70bf086' => 'Το :where αναφέρει το `:label`, αλλά το `:value3` δεν έχει σχέση `:value4`.',
    'framework_1fe22c4c4f19' => 'Το :where αναφέρεται στο `:value2`, το οποίο δεν ορίζει το `:value3`.',
    'framework_13577786fc0f' => 'Το :where έχει περισσότερες από μία λίστες `[...]` — συγχωνεύστε τες σε μία.',
    'framework_9f94df6350ae' => 'Το :where κληρονομεί από το `:value2`, το οποίο δεν ορίζει το `:value3`.',
    'framework_7f141d42c02f' => 'Το :where κληρονομεί μέσω του `:value2`, που πρέπει να είναι απλή λίστα τύπων όπως `[folder]` — όχι να υπολογίζεται από άλλες σχέσεις.',
    'framework_2b522c10efd9' => 'Το :where κληρονομεί μέσω του `:value2`, που περιλαμβάνει το σύνολο χρηστών `:value3`· μια σχέση μέσω της οποίας γίνεται κληρονόμηση μπορεί να περιλαμβάνει μόνο τύπους όπως `[folder]`.',
    'framework_0ead505bb5da' => 'Το :where κληρονομεί το `:value2` από το `:value3`, αλλά κανένας τύπος στον οποίο δείχνει το `:value4` δεν ορίζει το `:value5`.',
    'framework_aeb6433c3c63' => 'Το `:value1` στο `:value2` αφαιρεί το `:target`, που εξαρτάται από το ίδιο το `:self` — μια εξαίρεση δεν μπορεί να αναφέρεται πίσω στη σχέση που καθορίζει.',
    'framework_31332b5b9cca' => 'Μια σχέση γράφεται `relation name: definition`.',
