    'framework_cc7527e994e0' => 'Το api_key_prefix [:prefix] έχει ήδη δηλωθεί από άλλη εφαρμογή σε αυτό το περιβάλλον· εισαγάγετε με άλλο πρόθεμα ή χωρίς πρόθεμα',
    'framework_f674153d5ce9' => 'Το access_token_ttl πρέπει να είναι μεταξύ :value1 και :max δευτερολέπτων (ή null για την προεπιλογή της εγκατάστασης)· δόθηκε :ttl',
