    'framework_00110e2afc56' => 'Ο κωδικός πρόσβασης πρέπει να έχει τουλάχιστον :minLength χαρακτήρες.',
    'framework_bb93074b61a6' => 'Αυτός ο κωδικός πρόσβασης εμφανίστηκε σε δημόσια διαρροή δεδομένων — επιλέξτε άλλον.',
    'framework_5c809582f825' => 'Αυτός ο κωδικός πρόσβασης χρησιμοποιήθηκε πρόσφατα — δεν μπορεί να είναι ίδιος με κάποιον από τους τελευταίους :history κωδικούς.',
    'framework_a6b40085fbb4' => 'Αυτός ο οργανισμός συνδέεται μέσω του παρόχου ταυτότητάς του· η σύνδεση με κωδικό πρόσβασης είναι απενεργοποιημένη.',
    'framework_c444513cf88a' => 'Έχει ήδη καταχωριστεί API με αναγνωριστικό [:identifier] σε αυτό το περιβάλλον.',
    'framework_c10490950f73' => 'Δεν υπάρχει εφαρμογή με αναγνωριστικό πελάτη [:clientId] σε αυτό το περιβάλλον.',
    'framework_eefe9e56c023' => 'μη έγκυρο όνομα τομέα: :domain',
    'framework_5ffce0d11901' => 'αυτός ο τομέας διαχειρίζεται από την πλατφόρμα και δεν μπορεί να χρησιμοποιηθεί ως προσαρμοσμένος τομέας: :domain',
    'framework_2f8efd1170da' => 'αυτός ο τομέας χρησιμοποιείται ήδη από άλλο περιβάλλον: :domain',
    'framework_7ab7f2459414' => 'Άγνωστο πεδίο δικαιωμάτων κλειδιού διαχείρισης: :value1.',
    'framework_68e83d1171ec' => 'Δεν υπάρχει πάροχος pipe [:provider].',
    'framework_6ac6992d43ac' => 'Ένα pipe :provider έχει ήδη ρυθμιστεί σε αυτό το περιβάλλον.',
    'framework_77ba2bb35aea' => 'Η τιμή [:parameter] δεν είναι έγκυρη για το pipe :provider.',
    'framework_d5fdf17fe748' => 'Το πεδίο δικαιωμάτων [:scope] δεν είναι έγκυρο πεδίο OAuth.',
    'framework_33bb7d7b6461' => 'Ο πελάτης [:clientId] δεν έχει ενεργό μυστικό [:secretId].',
    'framework_5f503da3dc4f' => 'Ο εκκρεμής ορισμός ρόλου έχει αλλάξει ή δεν είναι πλέον διαθέσιμος. Ελέγξτε τον ξανά πριν τον ενεργοποιήσετε.',
    'framework_51b7e3361e5f' => 'Το αναγνωριστικό API [:identifier] πρέπει να είναι απόλυτο URI με host και χωρίς τμήμα (RFC 8707), έως 255 χαρακτήρες.',
    'framework_8038ba872fa4' => 'Το πεδίο [:key] δεν είναι έγκυρο αναγνωριστικό πεδίου δικαιωμάτων (RFC 6749 §3.3: εκτυπώσιμο ASCII, χωρίς κενά, εισαγωγικά ή ανάστροφες καθέτους, έως 128 χαρακτήρες).',
    'framework_918e4c13cded' => 'Το πεδίο δικαιωμάτων [:key] ορίζεται από τον ίδιο τον διακομιστή εξουσιοδότησης και δεν μπορεί να ανήκει σε API.',
    'framework_43fd205dea6a' => 'Το πεδίο δικαιωμάτων [:key] ανήκει ήδη σε άλλο API αυτού του περιβάλλοντος. Τα κλειδιά πεδίων είναι μοναδικά ανά περιβάλλον, επειδή ένα αίτημα διακριτικού αναγνωρίζει το πεδίο μόνο από το κλειδί του.',
    'framework_632573ec7b49' => 'Η εφαρμογή [:clientId] πρέπει να έχει τον ίδιο ιδιοκτήτη με το API του οποίου ελέγχει την πρόσβαση. Η σύνδεσή της θα έβαζε τους ρόλους και τα δικαιώματα ενός ιδιοκτήτη στα διακριτικά άλλου.',
    'framework_f94b33602fbd' => 'Το [:input] δεν είναι έγκυρη προέλευση. Δώστε σχήμα και host χωρίς διαδρομή — για παράδειγμα https://app.acme.com ή http://localhost:3000 κατά την ανάπτυξη.',
    'framework_a934fd6a0c26' => 'Το [:origin] χρησιμοποιεί http, οπότε το κλειδί και όλες οι ενέργειες της σελίδας που το χρησιμοποιούν θα μεταδίδονταν χωρίς κρυπτογράφηση. Χρησιμοποιήστε https ή, κατά την ανάπτυξη, host loopback όπως http://localhost:3000.',
    'framework_e23a74472a6b' => 'Το έργο [:projectId] έφτασε το όριο περιβαλλόντων του προγράμματός του: :limit.',
    'framework_1845262d35d9' => 'Τα ζητούμενα πεδία δικαιωμάτων ανήκουν σε περισσότερα από ένα API (:value1). Ορίστε το API για το οποίο προορίζεται το διακριτικό με την παράμετρο resource.',
    'framework_2b6e4e83d9a3' => 'Κανένα από τα ζητούμενα πεδία δικαιωμάτων δεν μπορεί να εκχωρηθεί σε αυτόν τον πελάτη για τον ζητούμενο αποδέκτη.',
    'framework_991e6a743ca7' => 'Η παράμετρος resource πρέπει να είναι απόλυτο URI με host και χωρίς τμήμα.',
    'framework_1d8203e2a4e1' => 'Μπορεί να ζητηθεί μόνο ένας πόρος ανά διακριτικό. Ζητήστε ξεχωριστό διακριτικό για κάθε διακομιστή πόρων.',
    'framework_a796a84fa8d9' => 'Ο πόρος [:resource] δεν εξυπηρετείται από αυτόν τον διακομιστή εξουσιοδότησης.',
    'framework_aa3328a251ad' => 'Ο πόρος [:resource] δεν δέχεται δυναμικά καταχωρισμένους πελάτες.',
    'framework_92a2cb6cba31' => 'Αυτό το διακριτικό ανανέωσης είναι δεσμευμένο σε διαφορετικό πόρο από τον ζητούμενο.',
    'framework_78e3d61edb93' => 'Ο πελάτης [:clientId] είναι δημόσιος: χρησιμοποιεί PKCE και δεν έχει μυστικό.',
    'framework_4a882cbbcad9' => 'Ο πελάτης [:clientId] επαληθεύεται με δικά του κλειδιά (private_key_jwt) και δεν έχει μυστικό. Αντικαταστήστε το κλειδί στο σύνολο JWK του.',
    'framework_fc1964a8e8c4' => 'Αυτό είναι το τελευταίο ενεργό μυστικό του πελάτη [:clientId]. Αντικαταστήστε το με νέο· η ανάκλησή του θα εμπόδιζε τον πελάτη να επαληθευτεί.',
    'framework_0ffaaa599a0c' => 'Η περίοδος χάριτος αντικατάστασης πρέπει να είναι μεταξύ 0 και :max δευτερολέπτων· δόθηκε :grace.',
    'framework_3cf574caed49' => 'Τα πεδία δικαιωμάτων :value1 ανήκουν σε καταχωρισμένο API του οποίου τα πεδία δεν μπορεί να έχει αυτός ο πελάτης. Πελάτης που ανήκει σε οργανισμό μπορεί να έχει πεδία των API του δικού του οργανισμού και τα πεδία των API του περιβάλλοντος που επιτρέπεται να ζητούν οι οργανισμοί.',
