    'every_session_that_was_opened_with_a_password_ends_incl_cf05d595' => 'Κάθε συνεδρία που ξεκίνησε με κωδικό πρόσβασης τερματίζεται — και η δική σας, αν συνδεθήκατε έτσι.',
    'every_verdict_is_recorded_and_none_is_acted_on_read_the_1b797986' => 'Κάθε απόφαση καταγράφεται, αλλά καμία δεν εφαρμόζεται. Ελέγξτε τις αποφάσεις πριν ενεργοποιήσετε την επιβολή.',
    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Ένας κωδικός μπορεί να κλαπεί με αντικατάσταση SIM ή μη εξουσιοδοτημένη μεταφορά αριθμού, να υποκλαπεί στο τηλεφωνικό δίκτυο ή να καταχωριστεί σε πειστική ψεύτικη σελίδα σύνδεσης. Παραμένει πολύ καλύτερος από έναν κωδικό πρόσβασης μόνο — ενεργοποιήστε τον για άτομα που δεν μπορούν να χρησιμοποιήσουν εφαρμογή ελέγχου ταυτότητας ή κλειδί πρόσβασης.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Ένα λογότυπο φορτωμένο από άλλον ιστότοπο ενημέρωνε εκείνον τον ιστότοπο για κάθε άτομο που άνοιγε τη σελίδα σύνδεσής σας. Γι’ αυτό οι φιλοξενούμενες σελίδες εμφανίζουν πλέον μόνο εικόνες που έχουν μεταφορτωθεί εδώ. Μεταφορτώστε το παρακάτω, στην ενότητα :part2, ή αφαιρέστε το για να σταματήσει αυτή η ειδοποίηση.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 μπορεί να συνδεθεί με κωδικούς πρόσβασης ή μέσω αυτής της σύνδεσης. Η απαίτηση ενιαίας σύνδεσης απορρίπτει κάθε άλλον τρόπο πρόσβασης, ώστε τίποτα που έχει ήδη εκδοθεί να μην παρακάμπτει τον πάροχο που μόλις ρυθμίσατε. Οι περισσότερες εταιρείες που συνδέουν IdP το επιθυμούν — αλλά διαβάστε πρώτα τις συνέπειες.',
