    'catalog_title' => 'Η κοινόχρηστη λίστα εφαρμογών σας',
    'catalog_description' => 'Ο κατάλογος είναι η λίστα που εμφανίζουν τα προϊόντα σας στον επιλογέα εφαρμογών. Δημοσιεύστε κάθε εφαρμογή με μια διεύθυνση εκκίνησης και ένα εικονίδιο και επιλέξτε ποιος μπορεί να τη βλέπει. Κάθε εφαρμογή εξακολουθεί να ελέγχει τη σύνδεση και την πρόσβαση.',
    'existing_environments_stay_live_but_no_new_o_0becaa18' => 'Τα υπάρχοντα περιβάλλοντα παραμένουν ενεργά, αλλά δεν μπορούν να προστεθούν νέα μέχρι την επανενεργοποίηση.',
    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 Ένας ρόλος είναι ετικέτα ενσωματωμένη στο token — όσοι δηλώνονται από εφαρμογή είναι εδώ μόνο για ανάγνωση, ενώ τους υπόλοιπους τους ορίζετε εσείς. :part2 :part3 :part4 — κάθε μέλος έχει επίσης ακριβώς έναν τέτοιο ρόλο (Ιδιοκτήτης, Διαχειριστής, Προγραμματιστής, Μέλος ή Θεατής), που καθορίζει τι μπορεί να διαχειρίζεται σε αυτή την κονσόλα.',
