    'https_or_http_on_localhost_leave_empty_and_t_6d61df22' => 'HTTPS ή HTTP στο localhost. Αφήστε το κενό και η εφαρμογή δεν θα ειδοποιείται.',
    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Μια σημαία λειτουργίας είναι ένας διακόπτης που οι εφαρμογές ελέγχουν για ένα άτομο σε έναν οργανισμό. Ενεργοποιήστε την για συγκεκριμένους χρήστες ή οργανισμούς ή για ένα ποσοστό των χρηστών. Όλες οι εφαρμογές λαμβάνουν την ίδια απάντηση, στο πεδίο `feature_flags` του token ή από το endpoint αξιολόγησης, χωρίς νέα ανάπτυξη. Ο κανόνας χρήστη υπερισχύει του κανόνα οργανισμού, αυτός της σταδιακής διάθεσης και αυτή της προεπιλογής.',
