    'catalog_changed_delete' => 'Η εφαρμογή άλλαξε. Φορτώστε την ξανά πριν από τη διαγραφή.',
    'catalog_choose_membership' => 'Επιλέξτε έναν ενεργό οργανισμό στον οποίο ανήκετε.',
