    'catalog_invalid_icon' => 'Χρησιμοποιήστε εικονίδιο έως 128 KiB και 512 × 512 pixel.',
    'international_format_works_anywhere_e_g_45_1_e06a0cd1' => 'Η διεθνής μορφή λειτουργεί παντού, π.χ. +45 12 34 56 78.',
    'it_gets_a_client_secret_shown_once_on_the_ne_356c8ac4' => 'Λαμβάνει μυστικό πελάτη, που εμφανίζεται μόνο μία φορά στην επόμενη οθόνη.',
    'it_is_called_again_at_the_hook_point_from_the_next_matc_a4d12b55' => 'Καλείται ξανά στο σημείο εκτέλεσης του hook από την επόμενη αντίστοιχη λειτουργία.',
    'it_stops_being_able_to_act_as_you_immediately_and_has_t_5c3d584b' => 'Δεν μπορεί πλέον να ενεργεί εκ μέρους σας και πρέπει να ζητήσει ξανά την έγκρισή σας.',
    'it_stops_being_called_at_the_hook_point_the_operation_i_72937229' => 'Παύει να καλείται στο σημείο εκτέλεσης του hook. Η λειτουργία στην οποία απαντούσε συνεχίζεται χωρίς αυτό.',
    'it_stops_working_immediately_anything_still_using_it_fa_4a9caff7' => 'Σταματά να λειτουργεί αμέσως. Οτιδήποτε το χρησιμοποιεί ακόμη δεν μπορεί να συνδεθεί.',
    'it_uses_pkce_and_gets_no_secret_nothing_to_l_f9fee647' => 'Χρησιμοποιεί PKCE και δεν λαμβάνει μυστικό — δεν υπάρχει κάτι που να μπορεί να διαρρεύσει από πρόγραμμα περιήγησης ή τηλέφωνο.',
    'its_events_are_accepted_unchecked_from_now_on_or_refuse_af37acad' => 'Τα συμβάντα του γίνονται πλέον δεκτά χωρίς έλεγχο — ή απορρίπτονται, αν είναι ενεργή η αυστηρή λειτουργία.',
    'its_members_can_sign_in_again_and_its_environments_resu_d369bd33' => 'Τα μέλη του μπορούν να συνδεθούν ξανά και τα περιβάλλοντά του συνεχίζουν να παρέχουν έλεγχο ταυτότητας.',
    'its_own_credentials_in_place_of_the_environment_s_for_t_bf11c9ef' => 'Τα δικά του διαπιστευτήρια αντί εκείνων του περιβάλλοντος για αυτόν τον πάροχο.',
    'key_created_paste_it_into_your_frontend_it_is_meant_to_0e59b7a5' => 'Το κλειδί δημιουργήθηκε. Επικολλήστε το στο frontend — προορίζεται να είναι δημόσιο.',
    'key_rotated_copy_the_new_one_now_the_old_key_keeps_work_aedb1c3d' => 'Το κλειδί αντικαταστάθηκε — αντιγράψτε τώρα το νέο. Το παλιό κλειδί συνεχίζει να λειτουργεί για 24 ώρες.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Προσφέρει κουμπιά Google, GitHub, Apple και άλλων παρόχων στη σελίδα σύνδεσης για όσους προτιμούν έναν υπάρχοντα λογαριασμό αντί για νέο κωδικό πρόσβασης. Ρυθμίστε κάθε πάροχο μία φορά για το περιβάλλον και θα είναι διαθέσιμος σε όλους τους οργανισμούς. Κάθε οργανισμός μπορεί να χρησιμοποιήσει δικά του διαπιστευτήρια ή να απενεργοποιήσει έναν πάροχο. Εσείς παρέχετε τα διαπιστευτήρια· τα υπόλοιπα συμπληρώνονται αυτόματα. Μια διεύθυνση που στέλνει ο πάροχος δεν αρκεί ποτέ από μόνη της για πρόσβαση σε υπάρχοντα λογαριασμό εδώ.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Τα κλειδιά με τα οποία ο κώδικάς σας συνδέεται στο Cbox ID, με ξεχωριστή καρτέλα ανά τύπο. Ένα μυστικό κλειδί, ή κλειδί διαχείρισης, επιτρέπει στο backend να διαχειρίζεται οργανισμούς, μέλη, προσκλήσεις, ρόλους και εφαρμογές ενός περιβάλλοντος. Ένα κλειδί οργανισμού καλεί το API του με ενσωματωμένο ρόλο. Ένα δημοσιεύσιμο κλειδί χρησιμοποιείται σε εφαρμογή φυλλομετρητή και λειτουργεί μόνο από τις επιτρεπόμενες προελεύσεις. Τα μυστικά κλειδιά και τα κλειδιά οργανισμού εμφανίζονται μόνο μία φορά. Αντιγράψτε τα κατά τη δημιουργία και ανακαλέστε τα αμέσως αν διαρρεύσουν.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Καταχωρίζει εφαρμογές που αποδέχονται αυτό το περιβάλλον ως πάροχο ταυτότητας SAML, ώστε οι χρήστες τους να συνδέονται με τους λογαριασμούς που έχουν ήδη εδώ. Συνδέστε κάθε εφαρμογή με τον οργανισμό της για να επιτρέπεται η είσοδος μόνο στα μέλη του. Χωρίς συσχετισμένο οργανισμό, η εφαρμογή είναι διαθέσιμη σε όλους τους χρήστες του περιβάλλοντος. Αυτή είναι η εξερχόμενη κατεύθυνση. Για σύνδεση με εταιρικό λογαριασμό από άλλο σύστημα, χρησιμοποιήστε το Εταιρικό SSO στην ενότητα Έλεγχος ταυτότητας.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Επιλέξτε το framework που χρησιμοποιείτε. Δημιουργείται εφαρμογή με ανακατεύθυνση στον τοπικό διακομιστή ανάπτυξης, ρυθμίσεις περιβάλλοντος για επικόλληση και κώδικα σύνδεσης χρήστη. Η σελίδα περιμένει μέχρι να πραγματοποιηθεί πραγματική σύνδεση. Παρακάτω εμφανίζονται τα βήματα προετοιμασίας του προϊόντος: εταιρική εμφάνιση, οργανισμοί, ενιαία σύνδεση, ένας πράκτορας, ένας συνεργάτης και παραγωγή. Η ολοκλήρωση σημειώνεται βάσει της πραγματικής κατάστασης του περιβάλλοντος, ποτέ χειροκίνητα.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Το Radar αξιολογεί κάθε σύνδεση και εγγραφή: δοκιμές κλεμμένων διαπιστευτηρίων, ταχύτητα χαρακτηριστική bot, αδύνατες μετακινήσεις, νέες συσκευές, δίκτυα ανωνυμοποίησης και προσωρινές διευθύνσεις, μαζί με τους δικούς σας κανόνες και λίστες επιτρεπόμενων και αποκλεισμένων. Καταγράφει κάθε απόφαση και, όταν ενεργοποιήσετε την επιβολή, αποκλείει την πρόσβαση ή ζητά δεύτερο παράγοντα. Ελέγξτε εδώ τις αποφάσεις πριν ενεργοποιήσετε την επιβολή και όταν κάποιος δεν μπορεί να συνδεθεί.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Διακόπτες λειτουργιών που οι εφαρμογές ελέγχουν για ένα άτομο σε έναν οργανισμό. Ενεργοποιήστε μια λειτουργία για συγκεκριμένους χρήστες, οργανισμούς ή ένα ποσοστό όλων των χρηστών. Κάθε εφαρμογή διαβάζει την ίδια απάντηση, από το token ή το API.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Λογισμικό που ενεργεί σε αυτό το περιβάλλον με κλειδί διαχείρισης: Claude Code, Cursor, ένα εσωτερικό bot ή το δικό σας backend. Κάθε ένα έχει μόνο τα πεδία πρόσβασης που του παραχωρήσατε και περιμένει την έγκρισή σας όπου την έχετε ορίσει ως απαραίτητη.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Ο παραλήπτης διατηρεί το ίδιο μυστικό. Ένα δεκαεξαδικό μυστικό 64 χαρακτήρων γίνεται whsec_ ακολουθούμενο από την κωδικοποίηση base64 αυτής της δεκαεξαδικής συμβολοσειράς — "whsec_" + base64(secret). Ένα μυστικό που αρχίζει ήδη με whsec_ χρησιμοποιείται ως έχει.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Οργανισμοί, χρήστες και ενεργές συνεδρίες από όλα τα περιβάλλοντα αυτής της εγκατάστασης, καθώς και οι οργανισμοί με τα περισσότερα μέλη. Αυτή η προβολή διαβάζει μόνο δεδομένα και δεν αλλάζει ποτέ το περιβάλλον που είναι επιλεγμένο στην κονσόλα.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Όλοι όσοι μπορούν να συνδεθούν σε αυτόν τον οργανισμό και οι προσκλήσεις που έχετε στείλει αλλά δεν έχουν ακόμη γίνει αποδεκτές. Προσκαλέστε άτομα μέσω email· ρυθμίζουν μόνα τους τη σύνδεσή τους, επομένως δεν χρειάζεται ποτέ να χειριστείτε τον κωδικό άλλου χρήστη.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Επιτρέψτε τη σύνδεση με υπάρχοντα λογαριασμό. Ρυθμίστε έναν πάροχο μία φορά για το περιβάλλον και θα είναι διαθέσιμος σε όλους τους οργανισμούς. Ένας οργανισμός μπορεί να χρησιμοποιήσει δικά του διαπιστευτήρια ή να απενεργοποιήσει έναν πάροχο.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Το Radar αξιολογεί κάθε σύνδεση και εγγραφή: δοκιμές με κλεμμένα διαπιστευτήρια, ταχύτητα που παραπέμπει σε bot, αδύνατες μετακινήσεις, νέες συσκευές, δίκτυα ανωνυμοποίησης, προσωρινές διευθύνσεις και τους δικούς σας κανόνες και λίστες. Καταγράφει επίσης τον λόγο της απόφασης.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Αυτός ο χρήστης δεν μπορεί πλέον να συνδεθεί σε καμία εφαρμογή αυτού του περιβάλλοντος και οι υπάρχουσες συνεδρίες του παύουν να λειτουργούν στο επόμενο αίτημα. Τα αρχεία του διατηρούνται και μπορείτε να τον ενεργοποιήσετε ξανά οποιαδήποτε στιγμή.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Η αξιολόγηση γίνεται με τη σειρά: λίστα αποκλεισμού, λίστα επιτρεπόμενων, δικοί σας κανόνες από πάνω προς τα κάτω (αποφασίζει ο πρώτος που αντιστοιχεί) και ενσωματωμένοι κανόνες (αποφασίζει ο αυστηρότερος από όσους ενεργοποιούνται). Αν δεν υπάρχει αντιστοιχία, η πρόσβαση επιτρέπεται.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Οι περισσότερες ενσωματώσεις χρειάζονται webhooks: εκτελούνται μετά το συμβάν και δεν μπορούν να το καθυστερήσουν. Χρησιμοποιήστε hook μόνο όταν το δικό σας σύστημα πρέπει να έχει λόγο κατά τη σύνδεση ή την έκδοση ενός token.',
    'keys_you_create_appear_here_with_when_each_was_last_use_8c3ff766' => 'Εδώ εμφανίζονται τα κλειδιά που δημιουργείτε και πότε χρησιμοποιήθηκε τελευταία φορά το καθένα.',
    'leave_empty_for_no_lockout_this_deployment_has_switched_d1f1a3e9' => 'Αφήστε κενό για να μην υπάρχει κλείδωμα — σε αυτή την εγκατάσταση το προεπιλεγμένο κλείδωμα είναι απενεργοποιημένο.',
    'let_people_sign_in_with_the_company_account_they_alread_b98aff03' => 'Επιτρέψτε στους χρήστες να συνδέονται με τον εταιρικό λογαριασμό που ήδη έχουν, αντί για ξεχωριστό κωδικό πρόσβασης εδώ.',
    'log_stream_saved_delivery_is_tried_again_on_the_next_ru_fb2e3c84' => 'Η ροή καταγραφής αποθηκεύτηκε. Η παράδοση θα δοκιμαστεί ξανά στην επόμενη εκτέλεση.',
    'management_key_created_copy_it_now_it_will_not_be_shown_9ec713ad' => 'Το κλειδί διαχείρισης δημιουργήθηκε — αντιγράψτε το τώρα, δεν θα εμφανιστεί ξανά.',
    'map_a_group_onto_the_roles_everyone_in_it_should_hold_m_1a407a38' => 'Αντιστοιχίστε μια ομάδα στους ρόλους που πρέπει να έχουν όλα τα μέλη της. Η συμμετοχή συγχρονίζεται και οι ρόλοι ακολουθούν.',
