    'the_scheduled_export_records_a_run_here_ever_6e615811' => 'Η προγραμματισμένη εξαγωγή καταγράφει εδώ μια εκτέλεση κάθε πέντε λεπτά, εφόσον εκτελείται το schedule:run και έχει ρυθμιστεί ένας προορισμός.',
