    'the_link_they_were_sent_stops_working_immediately_and_a_77389b6a' => 'Ο σύνδεσμος που στάλθηκε παύει αμέσως να λειτουργεί και οι ρόλοι που περιείχε ανακαλούνται. Μπορείτε να στείλετε νέα πρόσκληση στη συνέχεια.',
