    'this_transfers_ownership_of_the_shared_organization_rol_19e09a02' => 'Αυτό μεταβιβάζει την ιδιοκτησία του κοινόχρηστου οργανισμού. Οι ρόλοι σε κάθε εφαρμογή παραμένουν αμετάβλητοι· ενδέχεται να χάσετε την πρόσβαση στο Cbox ID.',
    'showing_the_first_part1_search_to_reach_the_rest_9e61b9cb' => 'Αρχικά αποτελέσματα που εμφανίζονται: :part1. Αναζητήστε τα υπόλοιπα.',
    '_copy_the_secret_now_only_a_hash_is_stored_so_it_won_t_94f8a33b' => ' Αντιγράψτε το μυστικό τώρα — αποθηκεύεται μόνο η τιμή κατακερματισμού του, οπότε δεν θα εμφανιστεί ξανά.',
    '_environment_default_part1_3f0792ae' => ' Προεπιλογή περιβάλλοντος: :part1.',
    '_owned_by_this_environment_not_by_this_organization_fir_33b76fa6' => '— ανήκει σε αυτό το περιβάλλον, όχι σε αυτόν τον οργανισμό. Οι εφαρμογές της πλατφόρμας εμφανίζονται στο μενού εφαρμογών κάθε οργανισμού.',
    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => 'Τα πεδία πρόσβασης :part1 ανήκουν σε API που αυτή η εφαρμογή δεν επιτρέπεται να χρησιμοποιεί. Εξαιρούνται από κάθε διακριτικό· αφαιρέστε τα από τα πεδία πρόσβασης που έχουν εισαχθεί χειροκίνητα.',
