    '_part1_every_name_it_uses_is_defined_and_nothing_subtra_9ef8bb73' => ':part1 Κάθε όνομα που χρησιμοποιείται έχει οριστεί και κανένα στοιχείο δεν αφαιρεί τον εαυτό του.',
    '_part1_has_its_own_rules_2979eb4e' => 'Το :part1 έχει δικούς του κανόνες.',
    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => 'Το :part1 δεν έχει ακόμη δικαιώματα, επομένως το :part2 :part3 είναι κενό. Το όνομα του ρόλου παραμένει διαθέσιμο για έλεγχο. :part4',
    '_part1_its_team_is_administered_under_organization_team_6abad4af' => ':part1 Η διαχείριση της ομάδας γίνεται από την ενότητα Οργανισμός › Ομάδα, από άτομο με ρόλο στον οργανισμό, και όχι από εδώ.',
    '_part1_only_d798c565' => 'Μόνο :part1',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Τίποτα εδώ δεν έχει ακόμη οριστεί από το :part3. Αν αλλάξετε κάποια ρύθμιση παρακάτω, γίνεται κανόνας αυτού του οργανισμού.',
    '_part1_part2_only_5ce234b9' => 'Μόνο :part1 :part2',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Το πεδίο :part2 έχει διαφορετική σημασία: δηλώνει τι επιτρεπόταν να ζητήσει η :part3 :part4, όχι τι επιτρέπεται να κάνει αυτό το :part5.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Επιλέξτε το πεδίο πρόσβασης :part2 :part3 κατά την καταχώριση της εφαρμογής. Το διακριτικό ταυτότητας θα περιέχει τα ίδια ονόματα ρόλων στο πεδίο :part4, το οποίο αναμένουν τα Kubernetes, Grafana και Vault. Δεν χρειάζεται να δημιουργήσετε κάτι άλλο.',
