    '_part1_write_76920eab' => ':part1 Εγγραφή',
    '_part1_write_a_permission_97ac7762' => ':part1 Δημιουργία δικαιώματος',
    '_the_platform_apps_below_belong_to_this_environment_rat_9f21136f' => ' Οι παρακάτω εφαρμογές της πλατφόρμας ανήκουν σε αυτό το περιβάλλον, όχι σε εσάς.',
