    'a_conflict_is_written_over_roles_so_there_is_nothing_to_1ee9ecc5' => 'Μια σύγκρουση ορίζεται μεταξύ ρόλων, αλλά δεν υπάρχουν ακόμη ρόλοι για να οριστεί. Ορίστε πρώτα τους ρόλους.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'Μια σελίδα στο :part1. Αφήστε το κενό για να ανοίξει η κονσόλα, με το :part2 να αναφέρεται στην πρόσκληση.',
    'a_part1_key_you_can_compose_into_roles_e_g_part2_part3_2714a35b' => 'Ένα κλειδί :part1 που μπορείτε να συμπεριλάβετε σε ρόλους, π.χ. :part2. :part3 :part4',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'Ένα δικαίωμα ορίζει τι επιτρέπεται να κάνει ένα :part1 μετά τη σύνδεση. Το τι επιτρέπεται να ζητήσει μια :part2 ορίζεται από το πεδίο πρόσβασης, κατά την καταχώρισή της στην ενότητα :part3 :part4.',
    'a_user_rule_beats_an_organization_rule_which_beats_the_74a29528' => 'Ο κανόνας χρήστη υπερισχύει του κανόνα οργανισμού, ο οποίος υπερισχύει της σταδιακής διάθεσης, η οποία υπερισχύει της προεπιλογής. Όταν ο διακόπτης λειτουργίας είναι απενεργοποιημένος, είναι απενεργοποιημένος για όλους.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Η πρόσβαση συσσωρεύεται: οι άνθρωποι αλλάζουν ομάδες αλλά κρατούν παλιά δικαιώματα, και κανείς δεν το προσέχει μέχρι να ρωτήσει ένας ελεγκτής. Ο έλεγχος πρόσβασης αποτυπώνει την τρέχουσα κατάσταση και απαιτεί επιβεβαίωση για κάθε ανάθεση ότι εξακολουθεί να χρειάζεται.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Τα διακριτικά πρόσβασης αυτής της εφαρμογής ορίζουν το :part1 ως αποδέκτη :part2. Το API πρέπει να δέχεται ένα διακριτικό μόνο όταν αυτό το κατονομάζει ως αποδέκτη.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Τα διακριτικά πρόσβασης αυτής της εφαρμογής ορίζουν ως αποδέκτη τον εκδότη του περιβάλλοντος, :part1 :part2. Αυτό αλλάζει όταν η εφαρμογή αποκτήσει πεδίο πρόσβασης από κάποιο καταχωρισμένο API σας.',
