    'already_sent_try_again_in_seconds_seconds_and_check_the_e294712c' => 'Έχει ήδη σταλεί. Χρόνος μέχρι την επόμενη προσπάθεια (δευτερόλεπτα): :seconds. Στο μεταξύ, ελέγξτε τον φάκελο ανεπιθύμητων του παραλήπτη.',
    'an_app_registered_here_can_sign_your_people_in_and_read_f35bdb6c' => 'Μια εφαρμογή που καταχωρίζεται εδώ μπορεί να συνδέει τους χρήστες σας και να διαβάζει τους ρόλους τους, ώστε να διαχειρίζεστε την πρόσβαση σε ένα σημείο αντί για κάθε προϊόν ξεχωριστά.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'Η εφαρμογή καταχωρίζει τον κατάλογό της μέσω του SDK. :part1 :part2 Μπορείτε να δημιουργήσετε τον ρόλο τώρα και να προσθέσετε δικαιώματα όταν γίνουν διαθέσιμοι οι ορισμοί τους.',
    'an_owner_or_admin_can_add_sms_only_next_to_a_stronger_f_07347449' => 'Ένας ιδιοκτήτης ή διαχειριστής μπορεί να προσθέσει SMS μόνο μαζί με ισχυρότερο παράγοντα. Αν διαθέτει μόνο SMS, του ζητείται να προσθέσει ισχυρότερο παράγοντα.',
    'and_part1_more_1468d675' => 'και ακόμη :part1',
    'anyone_can_create_an_account_in_part1_and_becomes_the_o_ff47cb27' => 'Οποιοσδήποτε μπορεί να δημιουργήσει λογαριασμό στο :part1 και γίνεται ιδιοκτήτης του δικού του οργανισμού.',
    'apps_registered_by_the_organizations_in_this_environmen_1fd60d9d' => 'Αυτό το πεδίο πρόσβασης μπορεί να δοθεί σε εφαρμογές που καταχωρίζονται από οργανισμούς αυτού του περιβάλλοντος. Αφήστε την επιλογή απενεργοποιημένη αν πρέπει να διατίθεται μόνο στις δικές σας εφαρμογές.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Οι εφαρμογές στέλνουν τους χρήστες για εγγραφή με :part1 και ζητούν από συνδεδεμένο χρήστη να δημιουργήσει οργανισμό με :part2. Και οι δύο επιλογές διατίθενται μόνο όσο αυτή η ρύθμιση είναι ενεργή.',
    'apps_that_hold_it_keep_it_as_a_typed_scope_which_no_lon_6498e819' => 'Οι εφαρμογές το διατηρούν ως χειροκίνητα καταχωρισμένο πεδίο πρόσβασης, το οποίο δεν δίνει πλέον πρόσβαση σε αυτό το API. Τα διακριτικά παύουν να το περιλαμβάνουν για αυτόν τον αποδέκτη.',
    'ask_a_sign_up_radar_flags_to_prove_it_is_a_person_cloud_5b5f2963' => 'Ζητήστε από τις εγγραφές που επισημαίνει το Radar να αποδείξουν ότι προέρχονται από άνθρωπο μέσω Cloudflare Turnstile. Αν είναι απενεργοποιημένο, ζητείται επιβεβαίωση του email.',
