    'built_in_role_for_part1_de8e2bb3' => 'Ενσωματωμένος ρόλος για :part1',
    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Επιβεβαιώστε όσα χρειάζονται ακόμη και ανακαλέστε όσα δεν χρειάζονται. Τίποτα δεν εφαρμόζεται μέχρι να κλείσει ο έλεγχος· τότε ένας ανακληθείς ρόλος διαχείρισης και υποστήριξης αφαιρείται από όλους τους οργανισμούς ταυτόχρονα.',
    'choose_one_of_roles_ownership_is_handed_over_with_trans_90a222bb' => 'Επιλέξτε έναν από τους ρόλους: :roles. Η ιδιοκτησία μεταβιβάζεται με την επιλογή «Μεταβίβαση ιδιοκτησίας», ποτέ με πρόσκληση.',
    'close_it_every_revoke_is_applied_for_real_and_anything_b4db8386' => 'Κλείστε την αναθεώρηση. Όλες οι ανακλήσεις εφαρμόζονται και οι καταχωρίσεις που δεν ελέγχθηκαν ακολουθούν την πολιτική της αναθεώρησης.',
    'comma_or_space_separated_a_scope_you_type_is_unowned_it_c5513416' => 'Διαχωρίστε με κόμματα ή κενά. Ένα πεδίο πρόσβασης που πληκτρολογείτε δεν έχει κάτοχο: φτάνει στα token της εφαρμογής ως έχει, αλλά δεν μπορεί ποτέ να τους προσθέσει το κοινό προορισμού ενός καταχωρισμένου API. Για αυτά χρησιμοποιήστε τις παραπάνω λίστες.',
    'comma_separated_only_for_keys_this_catalogue_5b436f7f' => 'Διαχωρισμένα με κόμματα. Μόνο για κλειδιά που δεν προσφέρει αυτός ο κατάλογος.',
