    'create_a_new_client_secret_choose_how_long_the_current_7788f8af' => 'Δημιουργήστε νέο μυστικό πελάτη. Επιλέξτε για πόσο θα λειτουργεί το τρέχον, ώστε όλες οι εγκαταστάσεις να προλάβουν να μεταβούν στο νέο.',
    'decided_by_this_deployment_s_cbox_id_signup_mode_which_5691d2c8' => 'Καθορίζεται από το CBOX_ID_SIGNUP_MODE της εγκατάστασης, με τιμή «:part1». Κατάσταση εγγραφής: :part2.',
