    'default_part1_a0a77763' => 'Προεπιλογή: :part1',
    'defined_for_the_whole_environment_every_organization_ca_8039a976' => 'Ρόλος που ορίζεται για ολόκληρο το περιβάλλον: μπορεί να χρησιμοποιηθεί από κάθε οργανισμό. Μόνο αυτός ο τύπος ρόλου μπορεί να εκχωρηθεί σε ένα άτομο σε όλους τους οργανισμούς ταυτόχρονα.',
    'each_new_account_creates_its_own_organization_and_owns_3528fda3' => 'Κάθε νέος λογαριασμός δημιουργεί τον δικό του οργανισμό και γίνεται ιδιοκτήτης του. Οι εφαρμογές μπορούν επίσης να ζητήσουν από συνδεδεμένο χρήστη να δημιουργήσει οργανισμό με :part1 :part2.',
