    'environment_default_part1_you_can_require_more_not_fewe_8d900b4b' => 'Προεπιλογή περιβάλλοντος: :part1. Μπορείτε να απαιτήσετε περισσότερα, όχι λιγότερα.',
    'every_api_key_the_people_in_this_organization_have_crea_b802c1e7' => 'Όλα τα κλειδιά API που έχουν δημιουργήσει τα άτομα αυτού του οργανισμού για τις εφαρμογές του. Ανακαλέστε όσα έχουν διαρρεύσει ή δεν χρησιμοποιούνται πλέον. Οι χρήστες δημιουργούν τα δικά τους κλειδιά στην ενότητα Ο λογαριασμός μου.',
    'every_logout_token_then_names_the_session_si_54d0a907' => 'Κάθε token αποσύνδεσης περιλαμβάνει τότε τη συνεδρία (sid) και το άτομο, ώστε η εφαρμογή να τερματίζει μόνο αυτή τη συνεδρία αντί για όλες τις συνεδρίες του.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Όλες οι ανακλήσεις που καταγράφηκαν σε αυτόν τον έλεγχο εφαρμόζονται τώρα στην πράξη. Όσα στοιχεία δεν έχουν ελεγχθεί ακολουθούν την πολιτική του ελέγχου, η οποία από προεπιλογή ανακαλεί την πρόσβαση. Αυτή η ενέργεια δεν αναιρείται.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Όλα τα μυστικά που πιστοποιούν αυτή τη στιγμή την εφαρμογή. Αποθηκεύεται μόνο το hash καθενός. Η λίστα δείχνει τους τελευταίους τέσσερις χαρακτήρες για να αναγνωρίζετε ποιο χρησιμοποιεί μια εγκατάσταση.',
    'every_text_costs_money_codes_go_only_to_the__171894a6' => 'Κάθε SMS έχει κόστος. Οι κωδικοί αποστέλλονται μόνο στις παρακάτω χώρες. Κάθε αριθμός, διεύθυνση δικτύου και αυτό το περιβάλλον έχουν ημερήσια όρια.',
    'everyone_in_this_organization_and_their_roles_one_built_35d8fefb' => 'Όλα τα άτομα αυτού του οργανισμού και οι ρόλοι τους: ένας ενσωματωμένος ρόλος για το καθένα και τυχόν ρόλοι εφαρμογών ή προσαρμοσμένοι ρόλοι',
    'everything_a_role_can_be_allowed_to_do_write_your_own_b_233ea6c4' => 'Όλες οι ενέργειες που μπορούν να επιτραπούν σε έναν ρόλο. Ορίστε τις δικές σας παρακάτω χωρίς κώδικα ή αφήστε τις εφαρμογές να τις καταχωρίζουν αυτόματα.',
    'face_id_touch_id_windows_hello_or_a_security_key_turnin_6e23006c' => 'Face ID, Touch ID, Windows Hello ή κλειδί ασφαλείας. Η απενεργοποίηση διατηρεί τα κλειδιά πρόσβασης που έχουν ήδη προστεθεί, ώστε να χρησιμοποιηθούν όταν ενεργοποιηθεί ξανά η επιλογή.',
    'filter_the_list_to_one_organization_to_scan_it_for_peop_6dbcc13b' => 'Περιορίστε τη λίστα σε έναν οργανισμό για να ελέγξετε ποια άτομα έχουν ήδη συγκρουόμενο ζεύγος ρόλων. Δεν έχει γίνει ακόμη έλεγχος.',
    'for_a_secret_that_has_leaked_anything_still_using_it_fa_7b1c0246' => 'Για μυστικό που έχει διαρρεύσει. Οτιδήποτε εξακολουθεί να το χρησιμοποιεί αποτυγχάνει αμέσως.',
    'for_development_refused_on_anything_but_the_origins_you_113f24ad' => 'Για ανάπτυξη. Απορρίπτεται από κάθε προέλευση που δεν έχετε δηλώσει, όπως και στην παραγωγή.',
    'give_your_app_the_feature_flags_scope_and_read_the_feat_a6908f11' => 'Δώστε στην εφαρμογή το πεδίο πρόσβασης feature_flags και διαβάστε το πεδίο feature_flags από το διακριτικό της.',
    'give_your_apps_those_scopes_on_their_scopes_tab_tokens_97d115cd' => 'Δώστε αυτά τα πεδία πρόσβασης στις εφαρμογές από την καρτέλα «Πεδία πρόσβασης». Τα διακριτικά τους ορίζουν το API ως αποδέκτη.',
    'grants_that_would_break_this_rule_are_blocked_from_now_1454bf59' => 'Από εδώ και πέρα αποκλείονται εκχωρήσεις που παραβιάζουν αυτόν τον κανόνα. Όσοι έχουν ήδη το ζεύγος το διατηρούν· ο παραπάνω έλεγχος σας βοηθά να τους εντοπίσετε.',
    'have_the_app_declare_the_roles_it_understands_so_you_ca_9074afe0' => 'Αφήστε την εφαρμογή να δηλώσει τους ρόλους που υποστηρίζει, ώστε να μπορείτε να τους εκχωρείτε εδώ.',
    'holds_conflicting_roles_part1_part2_23b385ca' => 'Έχει συγκρουόμενους ρόλους: :part1 :part2',
    'holds_part1_part2_6b1a0140' => 'Έχει: :part1 :part2',
    'how_an_app_connects_is_fixed_at_registration_changing_i_0372baec' => 'Ο τρόπος σύνδεσης της εφαρμογής ορίζεται κατά την καταχώριση. Η αλλαγή του αλλάζει τη σημασία των διαπιστευτηρίων, γι’ αυτό καταχωρίστε νέα εφαρμογή αντί να αλλάξετε τη χρήση αυτής.',
    'how_long_an_access_token_for_this_app_is_acc_22748384' => 'Για πόσο χρόνο γίνεται αποδεκτό ένα token πρόσβασης αυτής της εφαρμογής. Η μικρότερη διάρκεια περιορίζει τον χρόνο κατά τον οποίο μια εφαρμογή που επικυρώνει token offline μπορεί να δέχεται ένα ανακληθέν token. Οι εφαρμογές που χρησιμοποιούν introspection μπορούν να εντοπίζουν αμέσως την ανάκληση. Τα token ανανέωσης διατηρούν τους χρήστες συνδεδεμένους μεταξύ των ανανεώσεων των token πρόσβασης.',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Οι τρόποι σύνδεσης στο :part1. Ξεκινούν από τις προεπιλογές του περιβάλλοντος· οι αλλαγές εδώ μπορούν μόνο να τους κάνουν αυστηρότερους.',
    'inherited_46b2e93c' => 'κληρονομημένο',
    'its_rules_go_with_it_apps_asking_for_its_key_get_off_fr_aacd29e9' => 'Οι κανόνες αφαιρούνται μαζί του. Οι εφαρμογές που ζητούν το κλειδί του λαμβάνουν πλέον απενεργοποιημένη τιμή. Τα ήδη εκδοθέντα διακριτικά συνεχίζουν να το περιλαμβάνουν μέχρι να λήξουν.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Τα πεδία πρόσβασης αφαιρούνται μαζί του. Οι εφαρμογές τα διατηρούν ως χειροκίνητα καταχωρισμένες τιμές που δεν δίνουν πλέον πρόσβαση σε αυτό το API. Τα ήδη εκδοθέντα διακριτικά λειτουργούν μέχρι να λήξουν.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Κλειδιά για το API διαχείρισης ενός περιβάλλοντος: διαχειριστείτε οργανισμούς, μέλη, προσκλήσεις, ρόλους και εφαρμογές αυτού του περιβάλλοντος από το δικό σας backend. Κάθε κλειδί έχει ρητά καθορισμένα πεδία πρόσβασης.',
    'keys_your_browser_side_app_presents_to_the_frontend_api_ff8c1e2c' => 'Κλειδιά που η εφαρμογή του προγράμματος περιήγησης παρουσιάζει στο Frontend API. Περιλαμβάνονται στο πακέτο JavaScript· ο έλεγχος πρόσβασης είναι η λίστα επιτρεπόμενων προελεύσεων, όχι το ίδιο το κλειδί.',
    'leave_empty_for_this_deployment_s_default_of_part1_f391c886' => 'Αφήστε κενό για την προεπιλογή αυτής της εγκατάστασης: :part1.',
    'leave_empty_for_this_install_s_default_value_fda04f89' => 'Αφήστε κενό για την προεπιλογή της εγκατάστασης. Προεπιλογή (λεπτά): :value0. Ανώτατο όριο που όρισε ο διαχειριστής (λεπτά): :value1.',
    'let_your_apps_declare_the_roles_they_understand_those_a_719f1d4a' => 'Αφήστε τις εφαρμογές να δηλώνουν τους ρόλους που υποστηρίζουν. Θα εμφανίζονται εδώ αυτόματα.',
    'lets_the_people_who_use_this_app_create_api__6ef80e45' => 'Επιτρέπει στους χρήστες της εφαρμογής να δημιουργούν κλειδιά για το API της στην ενότητα Ο λογαριασμός μου › Κλειδιά API. Κάθε κλειδί συνδέεται με το άτομο, έναν οργανισμό και ένα υποσύνολο των δικαιωμάτων του στην εφαρμογή. Το API ελέγχει το κλειδί καλώντας το Cbox ID με τα διαπιστευτήρια της εφαρμογής. Το κλειδί χάνει ένα δικαίωμα μόλις το χάσει ο κάτοχός του.',
