    'refuse_passwords_found_in_known_data_breaches_checked_a_db4c6959' => 'Απορρίψτε κωδικούς που έχουν εμφανιστεί σε γνωστές διαρροές δεδομένων. Ελέγχονται μέσω του Have I Been Pwned χωρίς να αποστέλλεται ποτέ ο κωδικός. Αν η υπηρεσία δεν είναι προσβάσιμη, η εγγραφή επιτρέπεται αντί να μπλοκάρεται.',
    'register_an_app_so_it_can_sign_your_people_i_48568d69' => 'Καταχωρίστε μια εφαρμογή ώστε να μπορεί να συνδέει τους χρήστες σας, να ενεργεί εκ μέρους τους ή να καλεί το API για λογαριασμό της. Δηλώστε τον τύπο της και το Cbox ID επιλέγει την κατάλληλη ροή, τα διαπιστευτήρια και τα πεδία πρόσβασης.',
