    'scopes_sign_out_uris_token_settings_and_the_roles_manif_c736e69a' => 'Τα πεδία πρόσβασης, τα URI αποσύνδεσης, οι ρυθμίσεις token και το URL του αρχείου δήλωσης ρόλων αντιγράφονται ως έχουν. Τα μυστικά, τα κλειδιά και τα άτομα που χρησιμοποιούν την εφαρμογή δεν αντιγράφονται: ανήκουν στο περιβάλλον όπου δημιουργήθηκαν.',
