    'snapshots_every_admin_support_role_each_role_held_acros_351f6f6d' => 'Καταγράφει στιγμιότυπο όλων των ρόλων διαχείρισης και υποστήριξης που ισχύουν σε όλο το περιβάλλον, ως στοιχεία προς επιβεβαίωση ή ανάκληση. Η ανάκληση αφαιρεί τον ρόλο από όλους τους οργανισμούς ταυτόχρονα.',
    'snapshots_every_current_role_assignment_and_membership_f56eb372' => 'Καταγράφει όλες τις τρέχουσες εκχωρήσεις ρόλων και συμμετοχές σε έναν οργανισμό ως στοιχεία προς επιβεβαίωση ή ανάκληση.',
    'start_from_the_documents_in_folders_example_owners_edit_ca2a0af5' => 'Ξεκινήστε με το παράδειγμα εγγράφων σε φακέλους: κάτοχοι, συντάκτες και αναγνώστες, με την πρόσβαση του φακέλου να κληρονομείται από όλα τα περιεχόμενά του. Οι πλειάδες και οι έλεγχοι χρειάζονται πρώτα ένα σχήμα.',
    'synced_from_each_app_s_manifest_over_the_sdk_or_api_rea_4af9333b' => 'Συγχρονίζονται από το manifest κάθε εφαρμογής μέσω SDK ή API. Μόνο για ανάγνωση — η εφαρμογή είναι η έγκυρη πηγή τους.',
