    'that_person_has_not_accepted_their_invitation_yet_or_is_3c9ff95b' => 'Αυτό το άτομο δεν έχει ακόμη αποδεχτεί την πρόσκληση ή έχει τεθεί σε αναστολή. Μόνο ενεργό μέλος μπορεί να γίνει ιδιοκτήτης.',
    'the_address_tokens_for_this_api_name_as_their_audience_cdea85aa' => 'Η διεύθυνση που τα διακριτικά αυτού του API ορίζουν ως αποδέκτη και την οποία ελέγχει το API. Δεν μπορεί να αλλάξει αργότερα — κάθε ήδη εκδοθέν διακριτικό την περιέχει.',
