    'the_app_declares_these_cbox_id_pulls_them_from_its_mani_f63d9426' => 'Τα δηλώνει η εφαρμογή. Το Cbox ID τα ανακτά από το URL του manifest ή τα αποστέλλει η εφαρμογή. Μπορούν να εκχωρηθούν μόλις παραληφθούν.',
