    'the_audience_its_tokens_name_fixed_every_token_already_a3d06aee' => 'Ο αποδέκτης που ορίζουν τα διακριτικά. Είναι σταθερός — κάθε ήδη εκδοθέν διακριτικό τον περιέχει.',
