    'the_conflict_stops_being_enforced_grants_it_was_blockin_37391474' => 'Ο κανόνας σύγκρουσης παύει να εφαρμόζεται. Οι εκχωρήσεις που απέκλειε γίνονται ξανά δυνατές.',
    'the_conflict_stops_being_enforced_immediately_and_grant_88f978ef' => 'Ο κανόνας σύγκρουσης παύει αμέσως να εφαρμόζεται και οι εκχωρήσεις που απέκλειε γίνονται ξανά δυνατές. Αυτό δεν αναιρείται.',
    'the_current_client_secret_stops_working_immediately_and_030370f0' => 'Το τρέχον μυστικό πελάτη παύει αμέσως να λειτουργεί και δεν μπορεί να ανακτηθεί. Κάθε εγκατάσταση που το χρησιμοποιεί ακόμη θα αποτυγχάνει στην ταυτοποίηση.',
    'people_get_back_in_through_your_identity_provider_anyon_6fd7e521' => 'Οι χρήστες συνδέονται ξανά μέσω του παρόχου ταυτότητάς σας. Όποιος δεν έχει συνδεδεμένο πάροχο δεν μπορεί να συνδεθεί καθόλου.',
