    'the_facts_your_app_wrote_what_they_add_up_to_is_what_a_3240d92d' => 'Τα δεδομένα που έγραψε η εφαρμογή σας. Ο έλεγχος απαντά ποια δικαιώματα προκύπτουν από αυτά.',
