    'the_key_holds_the_built_in_role_you_choose_and_can_do_o_b7c48a4b' => 'Το κλειδί έχει τον ενσωματωμένο ρόλο που επιλέγετε και μπορεί να κάνει μόνο όσα επιτρέπει αυτός ο ρόλος.',
    'the_kill_switch_off_the_flag_is_off_for_everyone_whatev_90bda36f' => 'Ο κεντρικός διακόπτης. Όταν είναι ανενεργός, ο διακόπτης λειτουργίας είναι ανενεργός για όλους, ανεξάρτητα από τους παρακάτω κανόνες.',
    'the_organization_the_app_belongs_to_or_regis_d0bd8e48' => 'Ο οργανισμός στον οποίο ανήκει η εφαρμογή — ή καταχωρίστε την στο περιβάλλον παραπάνω.',
    'the_return_address_must_be_on_one_of_app_s_registered_r_20ea9b1f' => 'Η διεύθυνση επιστροφής πρέπει να ανήκει σε μία από τις καταχωρισμένες προελεύσεις URI ανακατεύθυνσης της εφαρμογής :app.',
    'the_rules_in_force_after_this_environment_s_baseline_is_278c536a' => 'Οι κανόνες που ισχύουν μετά την εφαρμογή των βασικών κανόνων του περιβάλλοντος. Η ρύθμιση ενός οργανισμού μπορεί μόνο να τους κάνει αυστηρότερους.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Οι υπηρεσίες σας που λαμβάνουν token πρόσβασης και τα πεδία πρόσβασης που ανήκουν στην καθεμία. Εσείς παραχωρείτε τα πεδία ενός καταχωρισμένου API· κανείς δεν μπορεί να αποκτήσει πρόσβαση στο API σας απλώς πληκτρολογώντας ένα πεδίο σε μια εφαρμογή.',
    'the_organization_s_own_keys_for_the_organization_api_li_86017b30' => 'Τα κλειδιά του ίδιου του οργανισμού για το API του: λίστα έργων και περιβαλλόντων, δημιουργία περιβαλλόντων, λίστα και πρόσκληση μελών της ομάδας. Κάθε κλειδί έχει έναν ενσωματωμένο ρόλο.',
