    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Το άτομο γίνεται ιδιοκτήτης του :part1 και εσείς διαχειριστής. Μόνο ο νέος ιδιοκτήτης μπορεί να σας επιστρέψει την ιδιοκτησία.',
    'they_become_this_organization_s_only_owner_whoever_owns_11374c6d' => 'Το άτομο γίνεται ο μοναδικός ιδιοκτήτης αυτού του οργανισμού. Ο σημερινός ιδιοκτήτης γίνεται διαχειριστής.',
