    'they_lose_every_role_and_application_this_organization_8c05da9e' => 'Χάνουν αμέσως όλους τους ρόλους και την πρόσβαση στις εφαρμογές που τους παρέχει αυτός ο οργανισμός.',
    'this_app_belongs_to_the_platform_and_is_available_to_ev_0c69cd5f' => 'Αυτή η εφαρμογή ανήκει στην πλατφόρμα και είναι διαθέσιμη σε κάθε οργανισμό αυτού του περιβάλλοντος. Τη διαχειρίζεται ο υπεύθυνος της πλατφόρμας σας.',
