    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Η εγκατάσταση δεν έχει κλειδιά Turnstile (CBOX_ID_TURNSTILE_SITE_KEY), οπότε δεν μπορεί να ενεργοποιηθεί η δοκιμασία επαλήθευσης. Οι επισημασμένες εγγραφές επιβεβαιώνουν αντί γι’ αυτό το email τους.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Η εγκατάσταση στέλνει SMS μόνο στις εξής χώρες: :part1. Οι αριθμοί των παρακάτω χωρών δεν μπορούν να λαμβάνουν κωδικούς μέχρι να προστεθούν οι χώρες στο CBOX_ID_SMS_ALLOWED_COUNTRIES: :part2.',
