    'this_role_belongs_to_the_environment_and_applies_across_0a2b2ed6' => 'Αυτός ο ρόλος ανήκει στο περιβάλλον και ισχύει σε όλους τους οργανισμούς του. Ισχύει εδώ, αλλά δεν μπορείτε να τον αλλάξετε.',
