    'this_role_is_declared_by_an_application_which_is_its_so_03e7843e' => 'Αυτός ο ρόλος δηλώνεται από εφαρμογή, η οποία είναι η έγκυρη πηγή του. Δεν μπορεί να τροποποιηθεί εδώ.',
