    'this_rule_binds_every_organization_in_the_environment_i_91928f48' => 'Αυτός ο κανόνας ισχύει για κάθε οργανισμό του περιβάλλοντος. Εμφανίζεται εδώ επειδή περιορίζει και τον δικό σας. Τον διαχειρίζεται ο υπεύθυνος της πλατφόρμας σας.',
