    'type_the_organization_s_name_exactly_as_shown_to_confir_f021127d' => 'Πληκτρολογήστε το όνομα του οργανισμού ακριβώς όπως εμφανίζεται για επιβεβαίωση.',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Τα πεδία πρόσβασης που εισάγονται χειροκίνητα (:part1) δεν έχουν ιδιοκτήτη. Μεταφέρονται αυτούσια και ποτέ με καταχωρισμένο API ως αποδέκτη.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Μέχρι να καταχωριστεί ένα API, το πεδίο πρόσβασης είναι απλώς κείμενο σε μια εφαρμογή και όποιος μπορεί να την επεξεργαστεί μπορεί να της δώσει οποιοδήποτε πεδίο. Καταχωρίστε τα API που καλούν οι εφαρμογές σας, ώστε τα πεδία τους να έχουν κάτοχο.',
