    'ux_scopes_summary' => 'Επιλεγμένα δικαιώματα: :count',
    'we_could_not_send_that_invitation_the_mail_server_refus_81a3f4df' => 'Δεν μπορέσαμε να στείλουμε την πρόσκληση — ο διακομιστής email την απέρριψε. Δεν δημιουργήθηκε τίποτα. Δοκιμάστε ξανά ή ελέγξτε τις ρυθμίσεις email της εγκατάστασης.',
    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Τι μπορεί να επιτραπεί σε μια εφαρμογή σε αυτό το API. Τα πεδία πρόσβασης μπορούν να εκχωρηθούν μόνο στις εφαρμογές με αυτόν τον ιδιοκτήτη: :part1.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Τι μπορεί να επιτραπεί σε μια εφαρμογή σε αυτό το API. Οι δικές σας εφαρμογές μπορούν να έχουν οποιοδήποτε πεδίο πρόσβασης· μια εφαρμογή που καταχωρίστηκε από οργανισμό μόνο όσα έχουν επισημανθεί για οργανισμούς.',
    'what_apps_ask_for_such_as_invoices_read_unique_in_this_2109e70c' => 'Τι ζητούν οι εφαρμογές, όπως invoices:read. Πρέπει να είναι μοναδικό σε αυτό το περιβάλλον.',
    'what_people_can_do_inside_your_apps_you_assign_roles_he_c31f1a20' => 'Τι μπορούν να κάνουν οι χρήστες μέσα στις εφαρμογές σας. Εσείς εκχωρείτε ρόλους εδώ· κάθε εφαρμογή καθορίζει τι επιτρέπουν οι δικοί της ρόλοι.',
    'what_this_role_is_allowed_to_do_tick_a_permission_to_gr_518298cc' => 'Τι επιτρέπεται να κάνει αυτός ο ρόλος. Επιλέξτε ένα δικαίωμα για να το παραχωρήσετε ή αποεπιλέξτε το για να το ανακαλέσετε.',
    'what_this_round_is_called_when_somebody_asks_which_revi_6e0713c0' => 'Το όνομα αυτού του κύκλου ελέγχου πρόσβασης, ώστε να εντοπίζεται από ποιον έλεγχο προήλθε μια απόφαση — για παράδειγμα τρίμηνο, έλεγχος ή ημερομηνία.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'Τι ζητά ο κώδικάς σας και τι περιέχει το πεδίο feature_flags. Πεζά γράμματα και ψηφία, με - _ ή . ανάμεσά τους. Δεν μπορεί να αλλάξει αργότερα.',
    'whatever_is_using_this_key_stops_working_immediately_th_8e55e6f5' => 'Οτιδήποτε χρησιμοποιεί αυτό το κλειδί σταματά αμέσως να λειτουργεί. Αυτό δεν αναιρείται.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_e14495d2' => 'Οτιδήποτε έχει συνδέσει ο κάτοχος με αυτό το κλειδί σταματά αμέσως να λειτουργεί. Ενημερώστε τον πρώτα, αν μπορείτε. Αυτό δεν αναιρείται.',
    'when_somebody_creates_an_api_key_for_one_of_your_apps_i_15c6370c' => 'Όταν κάποιος δημιουργήσει κλειδί API για εφαρμογή σας, εμφανίζεται εδώ μαζί με τον κάτοχό του και τις επιτρεπόμενες ενέργειες.',
    'when_somebody_signs_out_or_an_administrator__3520d247' => 'Όταν κάποιος αποσυνδεθεί ή ένας διαχειριστής τερματίσει τις συνεδρίες του, τον αφαιρέσει ή τον απενεργοποιήσει, το Cbox ID στέλνει υπογεγραμμένο token αποσύνδεσης σε αυτήν τη διεύθυνση, απευθείας μεταξύ διακομιστών, ώστε η εφαρμογή να τερματίσει και τη δική της συνεδρία.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Ο προορισμός στον οποίο το Cbox ID στέλνει τα άτομα μετά την αποσύνδεση από αυτήν την εφαρμογή. Το URI που ζητά η εφαρμογή πρέπει να αντιστοιχεί ακριβώς σε ένα URI εδώ, μαζί με την τελική κάθετο. Διαφορετικά, το Cbox ID κρατά το άτομο στη δική του σελίδα αποσύνδεσης. Αφήστε κενό αν η εφαρμογή δεν ανακατευθύνει μετά την αποσύνδεση.',
    'where_this_app_publishes_the_roles_it_unders_e6047562' => 'Πού δημοσιεύει η εφαρμογή τους ρόλους που υποστηρίζει, ώστε να μπορούν να εκχωρούνται εδώ.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Ποιους τρόπους σύνδεσης εκτός από κωδικό προσφέρει το :part1 και για πόσο ισχύει η σύνδεση. Είναι οι ίδιοι για όλους τους οργανισμούς του περιβάλλοντος.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Ποιος ανήκει σε αυτόν τον οργανισμό και τι επιτρέπεται να κάνει. Όποιος δεν έχει ακόμη λογαριασμό εδώ προσκαλείται μέσω email.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Για ποιους είναι ενεργός ο διακόπτης λειτουργίας όταν δεν τους κατονομάζει κανένας κανόνας. Αφήστε τον ανενεργό για να διαθέσετε τη λειτουργία πρώτα σε συγκεκριμένους οργανισμούς ή σε ποσοστό χρηστών.',
    'whose_role_it_is_or_tick_the_box_above_to_define_it_for_970fb7fe' => 'Σε ποιον οργανισμό ανήκει ο ρόλος, ή επιλέξτε το παραπάνω πλαίσιο για να τον ορίσετε για κάθε οργανισμό.',
    'whose_roles_and_memberships_the_review_snapshots_e7576353' => 'Ο οργανισμός του οποίου τους ρόλους και τις συμμετοχές καταγράφει ο έλεγχος πρόσβασης.',
    'whose_rule_it_is_or_tick_the_box_above_to_apply_it_to_e_82370728' => 'Σε ποιον οργανισμό ανήκει ο κανόνας, ή επιλέξτε το παραπάνω πλαίσιο για να ισχύει για κάθε οργανισμό.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Χωρίς ρόλους, όποιος μπορεί να συνδεθεί λαμβάνει την πρόσβαση που δίνει η εφαρμογή σε έναν απλό χρήστη. Με έναν ρόλο ορίζετε μία φορά ποιοι είναι συντάκτες και ποιοι ανήκουν στην υποστήριξη, ώστε κάθε συνδεδεμένη εφαρμογή να σέβεται αυτή την ανάθεση.',
    'work_through_the_list_certify_what_is_still_needed_revo_9bcc79ab' => 'Ελέγξτε τη λίστα: επιβεβαιώστε όσα δικαιώματα χρειάζονται και ανακαλέστε τα υπόλοιπα.',
    'write_one_above_or_from_your_app_s_backend_in_batches_o_9ca507a7' => 'Προσθέστε μια καταχώριση παραπάνω ή από το backend της εφαρμογής σε παρτίδες έως 100.',
    'writes_531995e8' => 'εγγραφή',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'Είστε ο μοναδικός ιδιοκτήτης. Μεταβιβάστε πρώτα την ιδιοκτησία σε άλλο άτομο ή διαγράψτε τον οργανισμό.',
    'you_can_also_part1_part2_part3_53f32513' => 'Μια ακόμη επιλογή: :part1 :part2. :part3',
    'you_can_set_this_back_to_prefer_sso_or_both__b84203a4' => 'Μπορείτε ανά πάσα στιγμή να επαναφέρετε τη ρύθμιση σε «Προτίμηση SSO» ή «Και οι δύο επιλογές διαθέσιμες». Οι συνεδρίες που τερματίστηκαν παραμένουν τερματισμένες.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Χάνετε αμέσως την πρόσβαση. Ως ιδιοκτήτης μπορείτε να αποχωρήσετε μόνο αφού αναλάβει την ιδιοκτησία κάποιος άλλος. Μεταβιβάστε την πρώτα ή διαγράψτε τον οργανισμό από τις Ρυθμίσεις.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Χάνετε αμέσως την πρόσβαση σε αυτόν τον οργανισμό και τις εφαρμογές του. Ένας διαχειριστής μπορεί να σας προσκαλέσει ξανά.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Το μοντέλο πρόσβασης της εφαρμογής σας: τύποι πόρων, οι σχέσεις κάθε τύπου και ο τρόπος κληρονόμησης. Η εφαρμογή γράφει πλειάδες που ορίζουν ποιος σχετίζεται με τι και ελέγχει την πρόσβαση σε κάθε αίτημα.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'Η πολιτική ταυτοποίησής σας εξακολουθεί να ισχύει: ισχύς κωδικού, έλεγχος διαρροών, επιβεβαίωση email, όρια αιτημάτων και έλεγχοι bot.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Το δικό σας API. Επιλέγετε ξεχωριστά ποια πεδία πρόσβασης μπορούν να ζητούν οι εφαρμογές που έχουν καταχωριστεί από οργανισμούς.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'Η σελίδα σύνδεσης αποκτά σύνδεσμο «Δημιουργία λογαριασμού» και οι εφαρμογές μπορούν να στέλνουν τους χρήστες απευθείας στην εγγραφή με :part1.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'Μπορείτε ανά πάσα στιγμή να επαναφέρετε τη ρύθμιση σε «Προτίμηση SSO» ή «Και οι δύο επιλογές διαθέσιμες». Οι συνεδρίες που τερματίστηκαν παραμένουν τερματισμένες.',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'Οι ρόλοι και τα δικαιώματα ενός διακριτικού αποτελούν στιγμιότυπο. Πριν από κάθε προστατευμένη ενέργεια, λάβετε μια τρέχουσα απόφαση πρόσβασης από το Cbox ID και ελέγξτε στην εφαρμογή σας την πρόσβαση στον συγκεκριμένο πόρο. Το περιεχόμενο του διακριτικού από μόνο του δεν αποτυπώνει μεταγενέστερες ανακλήσεις πρόσβασης:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Οι δικές σας μέθοδοι σύνδεσης και ενεργές συνεδρίες. Το κλειδί πρόσβασης είναι η πιο ασφαλής και γρήγορη επιλογή: η συσκευή το ξεκλειδώνει με δακτυλικό αποτύπωμα ή αναγνώριση προσώπου, χωρίς κωδικό που θα μπορούσε να υποκλαπεί με phishing.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Κάθε ενέργεια γίνεται αποδεκτή όπως την αποστέλλει η εφαρμογή. Προσθέστε ένα σχήμα σε μια ενέργεια για να ελέγχονται τα συμβάντα της κατά την παραλαβή. Η συνέπεια του αρχείου καταγραφής εξασφαλίζεται όταν γράφεται ένα συμβάν, όχι όταν κάποιος το διαβάζει.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Κάθε κλειδί API στο αρχείο ρυθμίσεων ή περιβάλλοντος μιας εφαρμογής είναι ένα κλειδί που δεν μπορείτε να αντικαταστήσετε κεντρικά ή να ανακαλέσετε γρήγορα. Εδώ αποθηκεύεται κρυπτογραφημένο, παραχωρείται ανά εφαρμογή και ανακαλείται με ένα κλικ.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Το κουμπί παύει να εμφανίζεται και τα διαπιστευτήρια διαγράφονται. Όσοι συνδέθηκαν μέσω αυτού του παρόχου διατηρούν τον λογαριασμό τους και μπορούν να συνεχίσουν να χρησιμοποιούν τον κωδικό τους. Για να κρατήσετε τα διαπιστευτήρια, απενεργοποιήστε τον πάροχο αντί να τον διαγράψετε.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Η αντίστροφη κατεύθυνση: το Cbox ID στέλνει τα άτομα της εταιρείας σας στα άλλα προϊόντα SaaS που χρησιμοποιεί, μέσω των τελικών σημείων SCIM τους. Ένα σημείο για παραχώρηση και αφαίρεση πρόσβασης, αντί για ξεχωριστό πίνακα διαχείρισης ανά προμηθευτή.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Δημιουργεί τον οργανισμό, τον κάτοχό του, το πρώτο προϊόν και το περιβάλλον παραγωγής αυτού του προϊόντος. Ο κάτοχος λαμβάνει μέσω email έναν σύνδεσμο για να ορίσει τον δικό του κωδικό· δεν τον επιλέγετε εσείς για εκείνον.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Σήμερα κάποιος προσθέτει και αφαιρεί άτομα εδώ χειροκίνητα. Συνδέστε τον κατάλογο που ήδη συντηρεί η εταιρεία σας και θα γίνονται αυτόματα και οι δύο εργασίες, μαζί με τις αφαιρέσεις που ξεχνιούνται πιο εύκολα.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Όλα τα token που εξέδωσε ανακαλούνται τώρα και δεν μπορεί να χρησιμοποιηθεί για νέα σύνδεση. Μια εφαρμογή που ελέγχει μόνη της τα token παύει να τα δέχεται όταν λήξουν, το αργότερο μέχρι τη λήξη της ίδιας της συνεδρίας.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Κατά τη μετάβαση από άλλο σύστημα, η εφαρμογή μπορεί να δηλώσει στο αρχείο δήλωσής της, δίπλα στους ρόλους, πού βρίσκεται η παλιά σύνδεση. Εμφανίζεται εδώ για έγκριση πριν εκτελέσει οποιαδήποτε ενέργεια.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Γράψτε έναν κανόνα για να επιτρέπετε, να ζητάτε πρόσθετη επαλήθευση ή να αποκλείετε βάσει όσων γνωρίζετε για τους χρήστες. Ζητήστε πρόσθετη επαλήθευση για συνδέσεις από χώρες όπου δεν δραστηριοποιείστε ή εξαιρέστε το δίκτυο του γραφείου από τους κανόνες συχνότητας.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Η επαλήθευση ενός domain που σας ανήκει, όπως το acme.com, επιτρέπει στο Cbox ID να αναγνωρίζει τα άτομά σας από το email τους και να τα στέλνει απευθείας στον πάροχό σας, χωρίς να πρέπει να επιλέξουν το σωστό κουμπί σύνδεσης.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Ένας πάροχος ταυτότητας που εισάγει μεταδεδομένα παρόχου υπηρεσίας χρησιμοποιεί αυτό το URL αντί να λαμβάνει χωριστά το αναγνωριστικό οντότητας και το URL ACS. Λειτουργεί πριν συμπληρωθεί το σκέλος των ρυθμίσεων του παρόχου ταυτότητας.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Αυτή η ενέργεια δεν αναιρείται. Τα διαπιστευτήρια, οι συμμετοχές και τα προσωπικά δεδομένα διαγράφονται και ο λογαριασμός ψευδωνυμοποιείται. Αν το άτομο είναι ο μοναδικός κάτοχος ενός οργανισμού, μεταβιβάστε πρώτα την κυριότητα.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Ενεργείτε ως αυτό το άτομο, στη συνεδρία του και με τα δικαιώματά του. Η πρόσβαση περιορίζεται σε 30 λεπτά και σε μόνο ανάγνωση όπου μπορεί να το επιβάλει η κονσόλα. Κάθε αίτημα καταγράφεται στο δικό σας όνομα.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Η αναστολή είναι η μόνη αλλαγή που κάνει αυτή η σελίδα και είναι αναστρέψιμη. Η επιλογή και το άνοιγμα ενός περιβάλλοντος αλλάζουν μόνο την προβολή της κονσόλας· δεν αλλάζουν τίποτα σε κανένα περιβάλλον.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Αυτή τη στιγμή οι χρήστες συνδέονται με διαπιστευτήρια που αποθηκεύονται εδώ. Συνδέστε τον πάροχό σας για να χρησιμοποιούν τον υπάρχοντα εταιρικό λογαριασμό τους και να χάνουν την πρόσβαση εδώ τη στιγμή που τον απενεργοποιείτε εκεί.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Δεν εκδίδεται νέο μυστικό. Από την επόμενη προσπάθεια, μαζί με τις επαναπροσπάθειες, οι παραδόσεις φέρουν τις κεφαλίδες του άλλου σχήματος. Ένας παραλήπτης που δεν έχει ενημερωθεί θα τις απορρίπτει όλες.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Στείλτε αυτόν τον σύνδεσμο μίας χρήσης στον διαχειριστή του παρόχου ταυτότητάς τους, αν δεν τον έχει λάβει με email. Λειτουργεί χωρίς λογαριασμό μέχρι να λήξει. Αντιγράψτε τον τώρα: εμφανίζεται μόνο μία φορά.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Το λογισμικό αυτού του περιβάλλοντος που περιμένει άδεια από άνθρωπο. Ένας agent του οποίου το κλειδί απαιτεί έγκριση σταματά και ρωτά το άτομο που δημιούργησε το κλειδί. Απαντήστε εδώ ή από το τηλέφωνό σας.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Ένας οργανισμός συγκεντρώνει χρήστες, μεθόδους σύνδεσης και ρόλους. Δημιουργήστε έναν παραπάνω ή αρχικοποιήστε το περιβάλλον με τον πρώτο οργανισμό και διαχειριστή του από την οθόνη Περιβάλλοντα.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Προσθέστε το άτομο σε έναν από τους παρακάτω οργανισμούς για να του δώσετε πρόσβαση εντός του. Αν οι εφαρμογές σας δεν έχουν δικό τους διαχωρισμό οργανισμών, παραχωρήστε του έναν ρόλο διαχείρισης και υποστήριξης που ισχύει σε όλο το περιβάλλον.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Ο ρόλος διαχείρισης και υποστήριξης παραχωρείται στο δικό σας προσωπικό για ολόκληρο το περιβάλλον. Ισχύει σε κάθε οργανισμό και κανένας διαχειριστής οργανισμού δεν μπορεί να τον δει ή να τον αλλάξει.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Τα αιτήματα εμφανίζονται αυτόματα εδώ όταν μια εφαρμογή ή ένας agent χρειάζεται την έγκρισή σας για να ενεργήσει εκ μέρους σας. Δεν χρειάζεται να κάνετε κάτι μέχρι τότε. Αν εμφανιστεί αίτημα που δεν ξεκινήσατε, απορρίψτε το.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'Τα SMS είναι ο πιο αδύναμος δεύτερος παράγοντας: όποιος πάρει τον έλεγχο του αριθμού σας λαμβάνει τους κωδικούς σας. Προτιμήστε μια εφαρμογή επαλήθευσης ή ένα κλειδί πρόσβασης και χρησιμοποιήστε SMS μόνο αν δεν μπορείτε να χρησιμοποιήσετε αυτά.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Η προεπιλεγμένη εταιρική ταυτότητα του περιβάλλοντος: η εμφάνιση, το λογότυπο και το favicon της φιλοξενούμενης σύνδεσης, καθώς και το όνομα και ο αποστολέας που βλέπουν οι χρήστες. Κάθε οργανισμός τα κληρονομεί, εκτός αν ορίσει δικά του.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Στοιχεία του οργανισμού στο περιβάλλον προορισμού: μέλη, SSO, domains, δικαιώματα και πρόσφατη δραστηριότητα. Το μόνο που αλλάζει από αυτή τη σελίδα είναι η κατάσταση του οργανισμού.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Όλοι οι οργανισμοί αυτής της εγκατάστασης. Ανοίξτε έναν για να δείτε τα προϊόντα και τα περιβάλλοντά του. Η αναστολή του αποσυνδέει τα μέλη και σταματά την παροχή ελέγχου ταυτότητας από όλα τα περιβάλλοντα που του ανήκουν.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Αυτά τα συμβάντα τα στέλνει η εφαρμογή σας: μία κλήση ανά παρτίδα, με κάθε συμβάν να αναφέρει τον οργανισμό όπου συνέβη. Εμφανίζονται εδώ και στους διαχειριστές αυτού του οργανισμού καθώς φτάνουν.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Είναι διαθέσιμος σε κάθε σελίδα σύνδεσης ολόκληρου του περιβάλλοντος. Επιλέξτε έναν οργανισμό για να ρυθμίσετε δικό του πάροχο, ο οποίος αντικαθιστά εκείνον του περιβάλλοντος στη σελίδα του οργανισμού.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Το Claude Code ανοίγει τον περιηγητή για σύνδεση εδώ και ρωτά τι θέλετε να επιτρέψετε. Δεν υπάρχει κλειδί που χρειάζεται να φυλάξετε. Κάθε πελάτης MCP που συνδέεται με OAuth λειτουργεί με τον ίδιο τρόπο με αυτό το URL.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Ένας οργανισμός αυτής της εγκατάστασης: η ομάδα, τα έργα και όλα τα περιβάλλοντα αυτών των έργων. Η αναστολή του αποσυνδέει τα μέλη και σταματά την παροχή ελέγχου ταυτότητας από όλα αυτά τα περιβάλλοντα.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Σε όλο το περιβάλλον: οποιοσδήποτε έχει λογαριασμό σε αυτό το περιβάλλον, σε οποιονδήποτε οργανισμό, μπορεί να συνδεθεί στην εφαρμογή. Ορίστε έναν οργανισμό, εκτός αν θέλετε αυτή την ευρεία πρόσβαση.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Η σύνδεση μέσω Entra ID, Okta ή Google Workspace διατίθεται στο πρόγραμμα Enterprise. Επικοινωνήστε με την ομάδα που διαχειρίζεται τον λογαριασμό σας για να την ενεργοποιήσει σε αυτόν τον οργανισμό.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Πού είστε συνδεδεμένοι, τι μπορεί να ενεργεί εκ μέρους σας και τι έχει συμβεί στον λογαριασμό σας. Αν δείτε κάτι που δεν αναγνωρίζετε, τερματίστε τη σχετική συνεδρία και αλλάξτε τον κωδικό σας.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Πόσα άτομα συνδέθηκαν και πόσο συχνά οι εφαρμογές κάλεσαν το API τις τελευταίες 30 ημέρες. Τα στοιχεία σάς βοηθούν να βλέπετε τον φόρτο και να εντοπίζετε ανωμαλίες· δεν αποτελούν τιμολόγιο.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Αυτός ο χρήστης κατέχει ή διαχειρίζεται έναν οργανισμό, επομένως δεν επιτρέπεται η σύνδεση ως αυτός. Η είσοδος σε έναν τέτοιο λογαριασμό θα μπορούσε να δώσει διαρκή έλεγχο του οργανισμού σε όποιον την έκανε.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Κλειδιά API που οι εφαρμογές και οι agents σας παρουσιάζουν σε άλλες υπηρεσίες. Κάθε τιμή αποθηκεύεται κρυπτογραφημένη, παραδίδεται μόνο στις εφαρμογές που εξουσιοδοτείτε και δεν εμφανίζεται ξανά μετά την αποθήκευση.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Εφαρμογές που ζητούν να ενεργήσουν εκ μέρους κάποιου χρήστη σας. Κάθε χρήστης εγκρίνει τα δικά του αιτήματα. Απορρίψτε ένα εδώ μόνο αν φαίνεται καταχρηστικό· η απόρριψη καταγράφεται στο αρχείο ελέγχου.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Πόσο συχνά να γίνεται ανάκτηση και ποια πεδία του συστήματος HR να αντιγράφονται σε κάθε άτομο, όπως κέντρο κόστους ή τοποθεσία. Η αλλαγή των πεδίων κάνει την επόμενη εκτέλεση πλήρη.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Σύνδεσμοι που δόθηκαν στον διαχειριστή IT αυτού του οργανισμού και εξακολουθούν να παρέχουν πρόσβαση. Η ανάκληση ενός συνδέσμου τον ακυρώνει αμέσως· όσα έχουν ήδη ρυθμιστεί μέσω αυτού παραμένουν.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Τα αιτήματα των agents για ενέργειες εκ μέρους ενός χρήστη εμφανίζονται εδώ καθώς φτάνουν. Κάθε χρήστης εγκρίνει τα δικά του· αυτή η σελίδα χρησιμεύει για την απόρριψη όσων φαίνονται καταχρηστικά.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Όταν ισχύουν ΟΛΕΣ οι συνθήκες, το Radar εκτελεί την ενέργεια αυτού του κανόνα και δεν εξετάζει επόμενους κανόνες. Οι κανόνες εξετάζονται μετά τις λίστες επιτρεπόμενων και αποκλεισμού και πριν από τους ενσωματωμένους κανόνες.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Τα συμβάντα ελέγχου που στέλνει η εφαρμογή για όλους τους οργανισμούς που εξυπηρετεί, με τα νεότερα πρώτα. Τα συμβάντα κάθε οργανισμού σχηματίζουν τη δική τους αλυσίδα hash.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Όσα έχει ρυθμίσει ο οργανισμός σας και όσα απομένουν. Η λίστα ρύθμισης παρακολουθεί την πραγματική κατάσταση: κάθε βήμα σημειώνεται αυτόματα ως ολοκληρωμένο μόλις ολοκληρωθεί πράγματι.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Ως διαχειριστής, προσθέστε και μια εφαρμογή επαλήθευσης ή ένα κλειδί πρόσβασης. Όποιος πάρει τον έλεγχο του αριθμού σας μπορεί να λαμβάνει τα SMS σας, επομένως δεν μπορούν να είναι ο μόνος δεύτερος παράγοντας.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Η διαγραφή αυτού του οργανισμού καταργεί όλα τα έργα και τα περιβάλλοντά του. Για την προστασία των ενεργών παρόχων ταυτότητας, αυτή η ενέργεια δεν είναι αυτοεξυπηρετούμενη. Επικοινωνήστε με την υποστήριξη για να συνεχίσετε.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Χάνει αμέσως την πρόσβαση σε κάθε σελίδα πλατφόρμας αυτής της εγκατάστασης και οι υπάρχουσες συνεδρίες παύουν να λειτουργούν στο επόμενο αίτημα. Μπορείτε να ενεργοποιήσετε ξανά τον χρήστη εδώ.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Τα επαληθευμένα domains κατευθύνουν τους χρήστες στον δικό σας πάροχο ταυτότητας, λειτουργία του προγράμματος Enterprise. Επικοινωνήστε με την ομάδα που διαχειρίζεται τον λογαριασμό σας για ενεργοποίηση σε αυτόν τον οργανισμό.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Ένα δικαίωμα ορίζει μία ενέργεια που επιτρέπεται σε έναν ρόλο, όπως δημιουργία τιμολογίων ή ανάγνωση αναφορών. Μπορείτε να δημιουργήσετε εδώ δικά σας δικαιώματα χωρίς κώδικα και να τα συνδυάσετε σε ρόλους. Οι εφαρμογές μπορούν επίσης να καταχωρίζουν αυτόματα τα δικά τους, ώστε η λίστα να αντιστοιχεί σε όσα επιβάλλουν πραγματικά. Τα δικαιώματα που δημιουργείτε σας ανήκουν. Όσα μοιράζεται το περιβάλλον μπορείτε να τα χρησιμοποιήσετε, αλλά όχι να τα αλλάξετε.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Οι κανόνες κωδικών πρόσβασης, κλειδώματος, υποχρεωτικού δεύτερου παράγοντα και ενιαίας σύνδεσης που ισχύουν σε κάθε σύνδεση. Για όλο το περιβάλλον ορίζονται επίσης η διαθεσιμότητα κλειδιών πρόσβασης και συνδέσμων σύνδεσης και η διάρκεια της συνεδρίας. Το περιβάλλον θέτει μια βάση που κληρονομούν όλοι οι οργανισμοί. Κάθε οργανισμός μπορεί να αυστηροποιήσει τους κανόνες κωδικών και δεύτερου παράγοντα, ποτέ όμως να τους χαλαρώσει.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Οι ενέργειες για τις οποίες οι πράκτορες αυτού του περιβάλλοντος περιμένουν ανθρώπινη έγκριση. Αν το κλειδί ενός πράκτορα απαιτεί έγκριση για μια ενέργεια, ο πράκτορας σταματά και ρωτά το άτομο που δημιούργησε το κλειδί. Εκείνο μπορεί να απαντήσει από το τηλέφωνο ή εδώ. Κάθε διαχειριστής του περιβάλλοντος μπορεί να απορρίψει ένα ύποπτο αίτημα. Παρακάτω βρίσκονται αιτήματα εφαρμογών να ενεργούν εκ μέρους χρηστών, τα οποία εγκρίνει προσωπικά κάθε χρήστης.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Οι συνεδρίες και τα token του ατόμου ανακαλούνται. Διαγράφονται τα κλειδιά πρόσβασης, οι δεύτεροι παράγοντες, οι συμμετοχές, οι αναθέσεις ρόλων, τα token API, τα μυστικά του θησαυροφυλακίου, οι συσκευές και όλα τα αποθηκευμένα αντίγραφα των στοιχείων του. Από τον λογαριασμό παραμένει μόνο μια ψευδωνυμοποιημένη, απενεργοποιημένη εγγραφή. Οι εφαρμογές που συγχρονίζουν άτομα από εδώ ενημερώνονται να το διαγράψουν. Το αρχείο ελέγχου διατηρεί το αδιαφανές αναγνωριστικό, όχι το όνομα ή τη διεύθυνση.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Όσα εγκρίνατε, συμπεριλαμβανομένων συσκευών ή εργαλείων γραμμής εντολών από τα οποία συνδεθήκατε.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Δεδομένα που τα συστήματά σας χρειάζεται να αποθηκεύουν για αυτόν τον οργανισμό. Οι γραμμές χωρίς κλειδί παραλείπονται.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'Αξιολογούνται μετά τους δικούς σας κανόνες. Κάθε κανόνας που ενεργοποιείται καταγράφεται· ο αυστηρότερος καθορίζει την απόφαση.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'Η αποστολή συνεχίζεται. Οι εγγραφές που δημιουργήθηκαν όσο ήταν απενεργοποιημένη παραμένουν σε αναμονή και θα σταλούν με την επόμενη παρτίδα.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'Η αποστολή σταματά αμέσως και το αποθηκευμένο διαπιστευτήριο καταστρέφεται. Το αρχείο ελέγχου παραμένει ανέπαφο.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Όλες οι συνδέσεις μεταξύ Cbox ID και άλλων συστημάτων σε ένα σημείο: ενιαία σύνδεση, σύνδεση με κοινωνικό λογαριασμό, συγχρονισμός καταλόγων και συστήματα HR, εξερχόμενη παροχή λογαριασμών, εφαρμογές SAML, webhooks, hooks, ροές αρχείων καταγραφής και αγωγοί δεδομένων. Ο κατάλογος ξεκινά τη ρύθμιση οποιουδήποτε τύπου· κάθε κάρτα ανοίγει την αντίστοιχη σελίδα. Η λίστα συνδέσεων εμφανίζει όλες τις υπάρχουσες συνδέσεις και την κατάστασή τους, πρώτα όσες παρουσιάζουν σφάλματα.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Όλοι οι τρόποι σύνδεσης εδώ — κωδικός πρόσβασης, κλειδιά πρόσβασης, σύνδεσμος σύνδεσης, κοινωνικός λογαριασμός, εταιρικό SSO και δεύτερος παράγοντας — με την κατάσταση ενεργοποίησης και το σημείο αλλαγής τους. Οι περισσότεροι ορίζονται από το περιβάλλον, ενώ οι συνδέσεις SSO ανήκουν σε κάθε οργανισμό. Αν η εγκατάσταση απενεργοποιεί ή περιορίζει μια μέθοδο, η σελίδα το αναφέρει και κατονομάζει τη σχετική ρύθμιση.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Πράκτορας είναι κάθε λογισμικό που ενεργεί σε αυτό το περιβάλλον με κλειδί διαχείρισης: ένας βοηθός AI όπως το Claude Code ή το Cursor, ένα εσωτερικό bot ή το δικό σας backend. Δώστε στον καθένα ξεχωριστό κλειδί μόνο με τα απαραίτητα πεδία πρόσβασης. Ορίστε ποιες ενέργειες χρειάζονται έγκριση και ανακαλέστε το κλειδί μόλις ολοκληρωθεί η εργασία ή κάτι φανεί ύποπτο.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Ένα API είναι μια υπηρεσία σας που λαμβάνει token πρόσβασης, όπως το https://api.example.com. Καταχωρίστε την με τα πεδία πρόσβασης που αναγνωρίζει, ώστε να μπορείτε να τα εκχωρείτε. Εσείς αποφασίζετε ποια μπορούν να ζητούν οι εφαρμογές που καταχωρίζουν οι οργανισμοί του περιβάλλοντος. Το token για το API περιέχει τη διεύθυνσή του ως κοινό προορισμού, την οποία ελέγχει η υπηρεσία σας.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Πώς εξάγεται το ίχνος ελέγχου από το Cbox ID: μια προγραμματισμένη εξαγωγή στέλνει νέες εγγραφές στο SIEM ή στο αρχείο κάθε πέντε λεπτά. Μια καθημερινή εργασία διατήρησης δημιουργεί σημείο ελέγχου χωρίς να διαγράφει δεδομένα. Εδώ μπορείτε να λάβετε το ιστορικό ελέγχου ενός ατόμου για αίτημα πρόσβασης βάσει ΓΚΠΔ ή, στην κονσόλα περιβάλλοντος, να ελέγξετε ότι εκτελούνται οι εξαγωγές.',
    'exactly_as_shown_part1_stays_disabled_until_it_matches_fa10ae07' => 'Πληκτρολογήστε ακριβώς όπως εμφανίζεται. Το κουμπί «:part1» παραμένει ανενεργό μέχρι να ταιριάζει το κείμενο.',
    'my_part1_app_40bca4ad' => 'Η εφαρμογή μου :part1',
    'one_long_running_process_php_artisan_queue_autoscale_st_9e4a3b67' => 'Μία διεργασία συνεχούς λειτουργίας, php artisan queue:autoscale, ξεκινά και σταματά τις διεργασίες που εκτελούν τις εργασίες στην ουρά.',
    'this_will_allow_part1_to_6ac64554' => 'Η εφαρμογή :part1 θα μπορεί να:',
