    'rename_value0_b709cc6f' => 'Μετονομασία :value0',
    'trial_98a66e97' => 'Δοκιμαστική περίοδος',
    'value0_not_included_in_this_organization_s_p_a6447bb1' => ':value0 Δεν περιλαμβάνεται στο πρόγραμμα αυτού του οργανισμού.',
    'create_one_on_platform_environments_and_its_counts_appe_2e1a2d8f' => 'Δημιουργήστε ένα στην ενότητα Πλατφόρμα › Περιβάλλοντα και οι μετρήσεις του θα εμφανιστούν εδώ.',
    'every_environment_on_this_install_and_how_much_of_the_e_1d09cf29' => 'Όλα τα περιβάλλοντα αυτής της εγκατάστασης και το μερίδιο του καθενός στο σύνολο',
    'every_queue_this_install_sends_background_work_through_562c4113' => 'Όλες οι ουρές εργασιών παρασκηνίου αυτής της εγκατάστασης και ο χρόνος αναμονής της παλαιότερης εργασίας σε καθεμία',
    'every_usage_counter_for_this_window_and_the_raw_metric_22633817' => 'Όλοι οι μετρητές χρήσης για αυτό το διάστημα και τα αρχικά κλειδιά των αντίστοιχων μετρικών',
    'find_an_organization_or_a_user_across_every_environment_e71f4ea0' => 'Βρείτε έναν οργανισμό ή χρήστη σε όλα τα περιβάλλοντα, όχι μόνο σε αυτό που είναι επιλεγμένο στην κονσόλα.',
    'no_claimed_domain_matches_that_try_part_of_the_domain_w_1212eb45' => 'Δεν βρέθηκε αντίστοιχος διεκδικημένος τομέας. Δοκιμάστε μέρος του τομέα, χωρίς το @.',
    'no_connections_match_that_name_try_a_different_search_t_6555c50e' => 'Δεν βρέθηκαν συνδέσεις με αυτό το όνομα. Δοκιμάστε άλλον όρο αναζήτησης.',
    'no_directory_matches_that_name_try_a_different_search_t_bfc6957c' => 'Δεν βρέθηκε κατάλογος με αυτό το όνομα. Δοκιμάστε άλλον όρο αναζήτησης.',
    'no_endpoint_url_matches_that_search_try_a_different_one_45378b36' => 'Δεν βρέθηκε URL τελικού σημείου που να αντιστοιχεί στην αναζήτηση. Δοκιμάστε άλλη αναζήτηση.',
    'no_entry_matches_those_filters_try_a_broader_term_or_cl_afd8d040' => 'Δεν βρέθηκε εγγραφή που να αντιστοιχεί στα φίλτρα. Δοκιμάστε γενικότερο όρο ή αφαιρέστε ένα φίλτρο.',
    'no_log_stream_matches_that_name_try_a_different_search_ac9bbc7c' => 'Δεν βρέθηκε ροή αρχείων καταγραφής με αυτό το όνομα. Δοκιμάστε άλλη αναζήτηση.',
    'no_outbound_connection_matches_that_name_try_a_differen_2fb976c3' => 'Δεν βρέθηκε εξερχόμενη σύνδεση με αυτό το όνομα. Δοκιμάστε άλλη αναζήτηση.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Όλα τα στοιχεία της εταιρικής σας ταυτότητας που βλέπουν οι χρήστες σε μία σελίδα: λογότυπο, favicon, χρώματα, γραμματοσειρά και γωνίες της φιλοξενούμενης σελίδας σύνδεσης με ζωντανή προεπισκόπηση, καθώς και όνομα προϊόντος, αποστολέας email και μήνυμα καλωσορίσματος. Ρυθμίστε τα μία φορά για όλο το περιβάλλον και θα τα κληρονομήσουν όλοι οι οργανισμοί ή δώστε σε έναν οργανισμό δική του εμφάνιση από την καρτέλα Εταιρική εμφάνιση.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Κάθε έργο στον οργανισμό έχει δικό του πρόγραμμα και όριο περιβαλλόντων. Εμφανίζονται εδώ μαζί με τη χρήση του μήνα: οργανισμοί, χρεώσιμες συνδέσεις ενιαίας σύνδεσης και συνδέσεις χρηστών. Η τιμολόγηση λαμβάνει υπόψη τους μηνιαίους ενεργούς χρήστες και τις εταιρικές συνδέσεις, όπως SSO και SCIM. Τα δοκιμαστικά περιβάλλοντα δεν έχουν χρέωση σύνδεσης.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Όλα τα κλειδιά API που δημιούργησαν τα άτομα αυτού του οργανισμού για τις εφαρμογές του: κάτοχος, εφαρμογή, δικαιώματα και τελευταία χρήση. Ένα κλειδί μπορεί να κάνει μόνο ό,τι μπορεί ο κάτοχός του και παύει να λειτουργεί όταν εκείνος αποχωρήσει. Ανακαλέστε όσα διέρρευσαν ή δεν χρησιμοποιούνται πια. Κάθε άτομο δημιουργεί τα δικά του κλειδιά στην ενότητα Ο λογαριασμός μου.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Κατά τη μετάβαση από άλλο σύστημα, μια εφαρμογή μπορεί να ζητά έλεγχο του email και του κωδικού ενός ατόμου που δεν υπάρχει ακόμη στο Cbox ID στο παλιό endpoint σύνδεσης. Δοκιμάστε το endpoint πριν το εγκρίνετε. Το άτομο που γίνεται δεκτό δημιουργείται εδώ και δεν αποστέλλεται ξανά στο παλιό σύστημα. Όσο όμως εκείνο το endpoint δεν λειτουργεί, όσοι δεν έχουν μεταφερθεί δεν μπορούν να συνδεθούν.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Τα συμβάντα ελέγχου που στέλνει η εφαρμογή σας για κάθε οργανισμό που εξυπηρετεί: ποιος έκανε τι μέσα στο προϊόν και πότε. Φυλάσσονται ανά οργανισμό σε αλυσίδα κατακερματισμού και εμφανίζονται στους διαχειριστές του. Χρησιμοποιήστε τα όταν ένας οργανισμός ζητήσει αρχείο ελέγχου του λογαριασμού του. Ορίστε σχήματα για συνεπή συμβάντα.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Καμία μελλοντική προσωρινή άδεια πρόσβασης δεν θα μπορεί να ανοίξει αυτό το μυστικό. Η ανάκληση είναι άμεση και οριστική.',
    'no_live_agents_revoked_and_expired_keys_stay_listed_for_8dd5437a' => 'Δεν υπάρχουν ενεργοί πράκτορες. Τα ανακληθέντα και ληγμένα κλειδιά παραμένουν στη λίστα για το αρχείο.',
    'no_permissions_it_identifies_its_holder_and_nothing_mor_80cf422c' => 'Χωρίς δικαιώματα — ταυτοποιεί μόνο τον κάτοχό του',
    'nothing_changes_for_anybody_until_this_is_on_test_a_sig_9eb3389b' => 'Δεν αλλάζει τίποτα για κανέναν μέχρι να ενεργοποιηθεί. Δοκιμάστε πρώτα μια σύνδεση.',
    'only_a_hash_is_stored_if_it_is_lost_revoke_it_and_creat_6e39a401' => 'Αποθηκεύεται μόνο το hash. Αν χάσετε το κλειδί, ανακαλέστε το και δημιουργήστε άλλο.',
    'only_the_apps_listed_here_can_lease_this_secret_everyth_3afb49f2' => 'Μόνο οι εφαρμογές που αναφέρονται εδώ μπορούν να αποκτήσουν προσωρινή πρόσβαση σε αυτό το μυστικό. Όλα τα άλλα αιτήματα απορρίπτονται.',
    'every_other_device_holding_a_session_as_you__a01280d4' => 'Οι συνεδρίες σας σε όλες τις άλλες συσκευές θα σταματήσουν να λειτουργούν στο επόμενο αίτημα. Σε αυτήν τη συσκευή θα παραμείνετε συνδεδεμένοι.',
    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'Ο οργανισμός δεν έχει ακόμη μέλη. Κανείς δεν μπορεί να συνδεθεί σε αυτόν μέχρι να προσκληθεί ή να προστεθεί μέσω παροχής λογαριασμών.',
    'no_password_is_set_here_they_get_a_sign_in_link_by_emai_5e488804' => 'Δεν ορίζεται κωδικός πρόσβασης εδώ. Το άτομο λαμβάνει σύνδεσμο σύνδεσης μέσω email και επιλέγει πώς θα συνδέεται.',
    'each_step_is_measured_from_live_state_so_the_guide_alwa_e7f5c55e' => 'Κάθε βήμα αξιολογείται με βάση την τρέχουσα κατάσταση, ώστε ο οδηγός να δείχνει πάντα την πραγματική πρόοδο αυτού του οργανισμού.',
    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Αντιγράψτε τώρα το κλειδί και δώστε το στον πράκτορα. Διατηρείται μόνο το hash, οπότε αυτή είναι η μοναδική φορά που εμφανίζεται.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Οι τομείς email του οργανισμού, καθένας επαληθευμένος με εγγραφή DNS TXT. Μετά την επαλήθευση μπορείτε να επιβάλετε ανακατεύθυνση στο SSO: όλοι όσοι έχουν διεύθυνση σε αυτόν τον τομέα χρησιμοποιούν την εταιρική σύνδεση SSO αντί για κωδικό πρόσβασης. Επαληθεύστε όλους τους τομείς των χρηστών πριν βασιστείτε στην ενιαία σύνδεση.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Το μοντέλο πρόσβασης της εφαρμογής σας: τύποι πόρων, όπως έγγραφα και φάκελοι, σχέσεις, όπως ιδιοκτήτης, συντάκτης και αναγνώστης, και η κληρονομικότητά τους. Οι αναγνώστες ενός φακέλου μπορούν, για παράδειγμα, να διαβάσουν κάθε έγγραφό του. Η εφαρμογή καταγράφει ποιος συνδέεται με ποιον πόρο και σε κάθε αίτημα ρωτά αν ο χρήστης μπορεί να επεξεργαστεί το έγγραφο. Το σχήμα καθορίζει την απάντηση.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Αυτό το περιβάλλον διαθέτει διακομιστή MCP, τον τυπικό τρόπο με τον οποίο οι βοηθοί AI καλούν εργαλεία, δίπλα στο REST API. Επικολλήστε τη διεύθυνση και ένα κλειδί διαχείρισης στο Claude Code, στο Cursor ή σε άλλο πελάτη MCP. Ο πράκτορας μπορεί να κάνει ακριβώς όσα επιτρέπουν τα πεδία πρόσβασης του κλειδιού, με τους ίδιους ελέγχους και το ίδιο αρχείο ελέγχου με την κονσόλα.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Ένα κλειδί επιτρέπει στα script και στις ενσωματώσεις σας να καλούν το API μιας εφαρμογής εκ μέρους σας, χωρίς σύνδεση. Μπορεί να κάνει μόνο ό,τι μπορείτε εσείς στην εφαρμογή: αν περιοριστεί η πρόσβασή σας, περιορίζεται και του κλειδιού. Το κλειδί εμφανίζεται μόνο μία φορά. Αντιγράψτε το κατά τη δημιουργία και ανακαλέστε το αμέσως αν διαρρεύσει ή πάψει να χρησιμοποιείται.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'Η παροχή λογαριασμών σταματά και οι αντιστοιχίσεις ομάδων αφαιρούνται. Τα άτομα που δημιουργήθηκαν παραμένουν.',
    'provisioning_stops_immediately_and_every_group_mapping_7a323b54' => 'Η παροχή λογαριασμών σταματά αμέσως και αφαιρούνται όλες οι αντιστοιχίσεις ομάδων. Η ενέργεια δεν μπορεί να αναιρεθεί.',
    'provisioning_to_the_downstream_app_stops_immediately_th_6d193c25' => 'Η παροχή λογαριασμών στην εφαρμογή προορισμού σταματά αμέσως. Η ενέργεια δεν μπορεί να αναιρεθεί.',
    'provisioning_to_the_downstream_app_stops_immediately_th_948dd5a5' => 'Η παροχή λογαριασμών στην εφαρμογή προορισμού σταματά αμέσως. Τα άτομα που έχουν ήδη δημιουργηθεί εκεί παραμένουν.',
    'phone_number_removed_their_other_factors_and_recovery_c_a792580f' => 'Ο αριθμός τηλεφώνου αφαιρέθηκε. Οι υπόλοιποι παράγοντες ταυτοποίησης και οι κωδικοί ανάκτησης του ατόμου παραμένουν αμετάβλητοι.',
    'people_already_connected_keep_the_scopes_they_agreed_to_f979f289' => 'Τα άτομα που έχουν ήδη συνδεθεί διατηρούν τα πεδία πρόσβασης που ενέκριναν μέχρι να συνδεθούν ξανά.',
    'origins_updated_the_change_is_live_on_the_next_request_6bb5bfb0' => 'Οι προελεύσεις ενημερώθηκαν. Η αλλαγή ισχύει από το επόμενο αίτημα.',
    'other_systems_may_be_using_this_changing_it_changes_the_41e0f485' => 'Άλλα συστήματα μπορεί να το χρησιμοποιούν. Η αλλαγή του αλλάζει τα URL που έχουν αποθηκεύσει.',
    'people_who_rely_on_this_provider_lose_their_way_in_this_10f27c15' => 'Τα άτομα που βασίζονται σε αυτόν τον πάροχο χάνουν αυτόν τον τρόπο σύνδεσης. Η ενέργεια δεν μπορεί να αναιρεθεί.',
    'project_suspended_its_environments_stay_live_but_no_new_be6ca1ef' => 'Το έργο ανεστάλη. Τα περιβάλλοντά του παραμένουν ενεργά, αλλά δεν μπορούν να προστεθούν νέα μέχρι να ενεργοποιηθεί ξανά το έργο.',
    'role_definition_activated_existing_holders_now_use_thes_381596d2' => 'Ο ορισμός ρόλου ενεργοποιήθηκε. Οι υπάρχοντες κάτοχοι χρησιμοποιούν πλέον αυτά τα δικαιώματα.',
    'rule_activated_grants_that_would_break_it_are_blocked_f_fb4adf4c' => 'Ο κανόνας ενεργοποιήθηκε. Από εδώ και πέρα αποκλείονται οι εκχωρήσεις πρόσβασης που θα τον παραβίαζαν.',
    'schema_saved_events_of_this_action_are_checked_against_8215a899' => 'Το σχήμα αποθηκεύτηκε. Από εδώ και πέρα τα συμβάντα αυτής της ενέργειας ελέγχονται βάσει αυτού.',
    'schema_saved_every_check_is_decided_by_it_from_now_on_e54cf8c0' => 'Το σχήμα αποθηκεύτηκε. Από εδώ και πέρα καθορίζει το αποτέλεσμα κάθε ελέγχου.',
    'refuse_events_whose_action_has_no_schema_turn_on_once_e_c5af42c9' => 'Απόρριψη συμβάντων των οποίων η ενέργεια δεν έχει σχήμα. Ενεργοποιήστε το όταν κάθε ενέργεια που στέλνει η εφαρμογή σας έχει σχήμα.',
    'objects_are_written_to_prefix_yyyy_mm_dd_hh_batch_ndjso_5c6035ae' => 'Τα αντικείμενα γράφονται στο prefix/yyyy/mm/dd/hh/batch.ndjson.gz, με ένα συμβάν ανά γραμμή.',
    'only_for_an_s3_compatible_store_such_as_minio_or_cloudf_266ca7ae' => 'Μόνο για χώρο αποθήκευσης συμβατό με S3, όπως MinIO ή Cloudflare R2. Αν μείνει κενό, χρησιμοποιείται το τελικό σημείο AWS της περιοχής.',
    'register_this_as_an_allowed_redirect_uri_at_the_provide_b537b90c' => 'Καταχωρίστε το στον πάροχο ως επιτρεπόμενο URI ανακατεύθυνσης, ακριβώς όπως εμφανίζεται.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Τα webhooks, οι ειδοποιήσεις αποσύνδεσης προς συνδεδεμένες εφαρμογές, οι ενημερώσεις ρόλων που λαμβάνονται από αυτές και τα email στην ουρά επεξεργάζονται στο παρασκήνιο από διεργασίες ουράς, χωρίς να περιμένει ο χρήστης. Αν δεν εκτελείται καμία διεργασία, τίποτα δεν αποστέλλεται, παρότι η υπόλοιπη κονσόλα φαίνεται κανονική. Εδώ εντοπίζετε το πρόβλημα.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Ένας έλεγχος κατά τον οποίο εξετάζετε ποιος έχει κάθε ρόλο και επιβεβαιώνετε ότι τον χρειάζεται ακόμη. Η πρόσβαση συσσωρεύεται αθόρυβα: οι άνθρωποι αλλάζουν ομάδες αλλά κρατούν παλιά δικαιώματα. Ο έλεγχος επιτρέπει την αφαίρεσή τους. Οι ανακλήσεις εφαρμόζονται όταν κλείσετε τον έλεγχο και όλη η διαδικασία καταγράφεται για τον ελεγκτή σας.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Αν η εφαρμογή δηλώσει αργότερα διαφορετικό URL, η έγκριση ακυρώνεται και θα ζητηθεί ξανά. Η αλλαγή του προορισμού των κωδικών πρόσβασης απαιτεί νέα έγκριση. Η ανατεθειμένη σύνδεση είναι μεταβατική λύση: όταν απομείνουν λίγα άτομα στο παλιό σύστημα, απενεργοποιήστε την και στείλτε τους επαναφορά κωδικού πρόσβασης.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Επιτρέπει τη σύνδεση με τον υπάρχοντα εταιρικό λογαριασμό, όπως Microsoft Entra ID, Okta ή Google Workspace, αντί για ξεχωριστό κωδικό εδώ. Συνδέστε μία φορά τον πάροχο ταυτότητας και επαληθεύστε τους τομείς email σας. Όλοι οι χρήστες αυτών των τομέων θα οδηγούνται στον πάροχο για σύνδεση.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Κάθε άτομο με ταυτότητα σε αυτό το περιβάλλον, ανεξάρτητα από τους οργανισμούς στους οποίους ανήκει. Ανοίξτε ένα άτομο για επαναφορά κωδικού ή δεύτερου παράγοντα, τερματισμό συνεδριών, απενεργοποίηση λογαριασμού, αλλαγή οργανισμών και ρόλων ή οριστική διαγραφή μετά από αίτημα άσκησης του δικαιώματος διαγραφής.',
    'paste_the_provider_s_metadata_xml_or_its_metadata_url_a_70d6c8b8' => 'Επικολλήστε το XML μεταδεδομένων του παρόχου ή το URL τους και τα παρακάτω πεδία θα συμπληρωθούν αυτόματα.',
    'paste_this_into_your_identity_provider_with_the_bearer_6f366a6e' => 'Επικολλήστε το στον πάροχο ταυτότητάς σας μαζί με το bearer token του καταλόγου που συνδέετε.',
    'point_your_oidc_client_at_these_discovery_exposes_every_81f0fa9a' => 'Ρυθμίστε τον πελάτη OIDC με αυτές τις διευθύνσεις. Ο μηχανισμός εντοπισμού παρέχει αυτόματα όλα τα τελικά σημεία.',
    'register_an_application_that_uses_this_environment_as_i_8eee8cef' => 'Καταχωρίστε μια εφαρμογή που χρησιμοποιεί αυτό το περιβάλλον ως πάροχο ταυτότητας SAML.',
    'register_one_to_let_an_application_sign_its_users_in_wi_e20e6b01' => 'Καταχωρίστε μία ώστε μια εφαρμογή να μπορεί να συνδέει τους χρήστες της με τους λογαριασμούς που έχουν ήδη σε αυτό το περιβάλλον.',
    'only_the_apps_listed_here_get_a_token_everything_else_i_3d600e70' => 'Μόνο οι εφαρμογές που αναφέρονται εδώ λαμβάνουν διακριτικό. Όλα τα άλλα αιτήματα απορρίπτονται.',
    'no_entitlements_set_for_this_organization_it_runs_on_th_76313cb5' => 'Δεν έχουν οριστεί δικαιώματα χρήσης για αυτόν τον οργανισμό. Ισχύουν οι προεπιλογές της εγκατάστασης.',
    'organizations_in_the_targeted_environment_as_the_manage_2f2361fb' => 'Οι οργανισμοί του επιλεγμένου περιβάλλοντος, ως δέντρο διαχείρισης.',
    'owned_by_this_environment_rather_than_by_an_organizatio_60be3a32' => 'Ανήκει σε αυτό το περιβάλλον και όχι σε οργανισμό',
    'platform_operators_administer_environments_across_the_w_e0a9f173' => 'Οι διαχειριστές της πλατφόρμας διαχειρίζονται τα περιβάλλοντα σε ολόκληρη την εγκατάσταση.',
    'platform_wide_usage_across_every_environment_not_only_t_0e12a08a' => 'Χρήση σε ολόκληρη την πλατφόρμα και όλα τα περιβάλλοντα, όχι μόνο σε αυτό που είναι επιλεγμένο στην κονσόλα.',
    'how_organization_owners_and_operators_sign_in_to_cbox_i_444d5c8b' => 'Ο τρόπος σύνδεσης των ιδιοκτητών και διαχειριστών οργανισμών στο Cbox ID ορίζεται στην κονσόλα του περιβάλλοντος της πλατφόρμας.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Αυτά τα σημεία επέκτασης εκτελούνται κατά τη διάρκεια μιας λειτουργίας, όχι μετά, και η απάντησή τους αλλάζει το αποτέλεσμα: το endpoint σας μπορεί να προσθέσει πληροφορίες σε ένα token ή να αρνηθεί τη σύνδεση. Παρεμβαίνουν άμεσα στην εκτέλεση της λειτουργίας — ένα αργό ή μη λειτουργικό endpoint επηρεάζει το άτομο που προσπαθεί να συνδεθεί.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Ο πάροχος ταυτότητας δημιουργεί, ενημερώνει και απενεργοποιεί αυτόματα άτομα εδώ μέσω του προτύπου SCIM. Μια πρόσληψη ή αποχώρηση που καταγράφεται στο σύστημα ανθρώπινου δυναμικού φτάνει στις εφαρμογές σε δευτερόλεπτα, χωρίς αιτήματα υποστήριξης ή ξεχασμένους λογαριασμούς — κάτι ιδιαίτερα σημαντικό στις αποχωρήσεις.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Το πλήθος οργανισμών, χρηστών, συνδέσεων ενιαίας σύνδεσης, εφαρμογών και συγχρονισμών χρηστών αυτού του περιβάλλοντος, με συνδέσμους προς τις αντίστοιχες σελίδες. Οι παρακάτω συντομεύσεις ξεκινούν τις συνηθέστερες δημιουργίες: οργανισμό, χρήστη, σύνδεση ενιαίας σύνδεσης ή εφαρμογή.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Ο ρόλος είναι μια ευθύνη που κατανοούν οι εφαρμογές σας, όπως «Συντάκτης» ή «Εκπρόσωπος υποστήριξης». Εδώ αποφασίζετε ποιος έχει κάθε ρόλο, ενώ κάθε εφαρμογή ορίζει τι επιτρέπει ο ρόλος της. Οι ρόλοι ακολουθούν το άτομο σε όλες τις συνδεδεμένες εφαρμογές, ώστε να παραχωρείτε και να ανακαλείτε πρόσβαση από ένα σημείο.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Αντιγράφει κάθε εγγραφή του αρχείου καταγραφής ελέγχου στα εργαλεία της ομάδας ασφάλειας, όπως ένα SIEM, τη στιγμή που γράφεται. Ρυθμίστε έναν προορισμό ώστε οι έρευνες να ξεκινούν στα εργαλεία που ήδη χρησιμοποιείτε, χωρίς αίτημα εξαγωγής. Η παράδοση γίνεται τουλάχιστον μία φορά, οπότε μπορεί να εμφανίζονται διπλότυπα.',
    'an_organization_appears_here_the_moment_somebody_signs__d46ff7af' => 'Ένας οργανισμός εμφανίζεται εδώ μόλις κάποιος εγγραφεί. Μπορείτε επίσης να δημιουργήσετε έναν με την επιλογή Νέος οργανισμός παραπάνω.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Προσθέστε τον τομέα των διευθύνσεων email των ατόμων αυτού του οργανισμού, δημοσιεύστε την εγγραφή TXT και επαληθεύστε τον τομέα.',
