    'it_replaces_the_sealed_value_on_rotate_and_is_never_sho_cec701f1' => 'Κατά την εναλλαγή αντικαθιστά την κρυπτογραφημένη τιμή και δεν εμφανίζεται ξανά. Κρατήστε δικό σας αντίγραφο αν το χρειάζεστε.',
