    'sealed_the_moment_you_save_it_and_never_shown_again_kee_db995569' => 'Κρυπτογραφείται μόλις το αποθηκεύσετε και δεν εμφανίζεται ξανά. Κρατήστε δικό σας αντίγραφο αν το χρειάζεστε.',
    'stored_sealed_and_never_shown_again_leave_it_empty_to_k_72338e4f' => 'Αποθηκεύεται κρυπτογραφημένο και δεν εμφανίζεται ξανά. Αφήστε το κενό για να διατηρηθεί η τρέχουσα τιμή.',
    'secret_rotated_and_the_previous_one_has_stopped_working_14aacb17' => 'Το μυστικό αντικαταστάθηκε και το προηγούμενο έπαψε να λειτουργεί. Αντιγράψτε τώρα το νέο· δεν θα εμφανιστεί ξανά.',
    'revoking_is_immediate_and_permanent_no_future_lease_can_27e17e18' => 'Η ανάκληση είναι άμεση και οριστική. Καμία μελλοντική προσωρινή άδεια πρόσβασης δεν θα μπορεί να ανοίξει αυτό το μυστικό.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Τα σχήματα μεταδεδομένων είναι υποσύνολο του JSON Schema: ένα αντικείμενο με ιδιότητες συμβολοσειρών, αριθμών, ακεραίων, λογικών τιμών ή null, με απαριθμήσεις και περιορισμούς μήκους, εύρους, μοτίβου και μορφής. Η αποθήκευση αλλαγής δημιουργεί νέα έκδοση· τα ήδη καταγεγραμμένα συμβάντα διατηρούν την έκδοση με την οποία ελέγχθηκαν.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Κάθε σύνδεση επιτρέπει στα άτομα να συνδέσουν τον δικό τους λογαριασμό σε μια υπηρεσία όπως GitHub, Google ή Slack. Τα token τους αποθηκεύονται κρυπτογραφημένα και ανανεώνονται εδώ. Οι εξουσιοδοτημένες εφαρμογές ζητούν έγκυρο token κάθε φορά που καλούν την υπηρεσία εκ μέρους του ατόμου, χωρίς να το αποθηκεύουν οι ίδιες.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Ένας ρόλος διαχείρισης και υποστήριξης δίνεται στο δικό σας προσωπικό, όπως στις ομάδες υποστήριξης ή λειτουργίας, για ολόκληρο το περιβάλλον. Ισχύει σε κάθε οργανισμό και οι διαχειριστές των οργανισμών δεν μπορούν να τον δουν, να τον παραχωρήσουν ή να τον αφαιρέσουν. Ένας ρόλος συγκεκριμένης εφαρμογής που δίνεται έτσι ισχύει μόνο σε αυτήν.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Ένα περιβάλλον είναι μια πλήρως απομονωμένη υπηρεσία ταυτότητας με δικούς της χρήστες, κλειδιά, σύνδεση και εκδότη. Εδώ παρατίθενται όλα τα περιβάλλοντα αυτής της εγκατάστασης μαζί με τον οργανισμό στον οποίο ανήκουν. Δημιουργήστε ένα, επιλέξτε το στην κονσόλα και προσθέστε τον πρώτο οργανισμό και διαχειριστή.',
    'a_chain_is_one_organization_s_send_organization_id_f35ed1e5' => 'Κάθε αλυσίδα ανήκει σε έναν οργανισμό: στείλτε organization_id.',
