    'self_service_sign_up_is_on_people_can_create_an_account_af9f74f0' => 'Η αυτοεξυπηρετούμενη εγγραφή είναι ενεργή. Οι χρήστες μπορούν να δημιουργούν λογαριασμό και δικό τους οργανισμό.',
    'start_from_a_preset_then_adjust_each_scope_is_marked_wi_60006824' => 'Ξεκινήστε από μια προρύθμιση και προσαρμόστε την. Κάθε πεδίο πρόσβασης επισημαίνεται με την πιο επιβλαβή ενέργεια που επιτρέπει.',
    'the_application_can_no_longer_sign_users_in_through_thi_72052d67' => 'Η εφαρμογή δεν θα μπορεί πλέον να συνδέει χρήστες μέσω αυτού του περιβάλλοντος. Η ενέργεια δεν μπορεί να αναιρεθεί.',
