    'the_hostname_attribute_defaults_to_this_platform_s_host_03e46070' => 'Το χαρακτηριστικό ονόματος κεντρικού υπολογιστή. Από προεπιλογή χρησιμοποιείται ο κεντρικός υπολογιστής αυτής της πλατφόρμας.',
    'the_hr_system_s_own_field_names_one_per_line_a77675b4' => 'Τα ονόματα πεδίων του συστήματος HR, ένα ανά γραμμή.',
    'the_hr_system_s_own_field_names_to_copy_onto_each_perso_2c74edb8' => 'Τα ονόματα πεδίων του συστήματος HR που θα αντιγράφονται σε κάθε άτομο, ένα ανά γραμμή — για παράδειγμα, κέντρο κόστους ή τοποθεσία.',
    'the_identifier_the_application_calls_itself_in_its_auth_afe05ddf' => 'Το αναγνωριστικό με το οποίο η εφαρμογή προσδιορίζει τον εαυτό της στα AuthnRequests.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Ένα τηλέφωνο με εγκατεστημένη την εφαρμογή ελέγχου ταυτότητας απαντά σε αιτήματα έγκρισης και σας ειδοποιεί όταν κάποιος συνδέεται στον λογαριασμό σας. Καταχωρίστε το μία φορά σαρώνοντας τον κωδικό. Αν χάσετε τη συσκευή, αφαιρέστε τη αμέσως εδώ, ώστε να μην μπορεί πλέον να εγκρίνει τίποτα.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Ο οργανισμός είναι η περιοχή μιας εγγεγραμμένης εταιρείας σε αυτήν την εγκατάσταση και περιέχει τα έργα, τα περιβάλλοντα και την ομάδα της. Ανοίξτε τον για να δείτε προϊόντα και περιβάλλοντα ή αναστείλετέ τον: έτσι αποσυνδέονται τα μέλη του και σταματούν οι συνδέσεις σε όλα τα περιβάλλοντά του.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Όταν μια εφαρμογή ή ένας πράκτορας AI χρειάζεται την άδειά σας για να ενεργήσει εκ μέρους σας, δεν μπορεί πάντα να τη ζητήσει στην οθόνη μπροστά σας — γι’ αυτό τη ζητά εδώ. Εγκρίνετε μόνο αιτήματα που ξεκινήσατε εσείς και ελέγξτε ότι ο κωδικός ταιριάζει με αυτόν στη συσκευή που έστειλε το αίτημα.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Ένα έργο είναι ένα από τα προϊόντα σας, με δικό του πρόγραμμα, σύνδεση και περιβάλλοντα, όπως παραγωγή και προπαραγωγή. Ανοίξτε ένα περιβάλλον από εδώ για να το διαχειριστείτε. Δημιουργήστε νέο έργο όταν ξεκινάτε προϊόν που πρέπει να χρεώνεται και να λειτουργεί ανεξάρτητα.',
    'send_this_endpoint_every_organization_s_events_in_this_ea696387' => 'Στείλτε σε αυτό το τελικό σημείο τα συμβάντα όλων των οργανισμών σε αυτό το περιβάλλον, όχι μόνο ενός.',
    'signature_scheme_changed_deliveries_are_signed_the_new_9a0fb26a' => 'Το σχήμα υπογραφής άλλαξε. Από την επόμενη προσπάθεια οι αποστολές υπογράφονται με τον νέο τρόπο.',
    'the_hook_stops_being_called_and_its_signing_secret_is_d_ad833a77' => 'Το hook δεν θα καλείται πλέον και το μυστικό υπογραφής του θα καταστραφεί. Η ενέργεια δεν μπορεί να αναιρεθεί.',
    'the_bucket_in_the_path_rather_than_the_host_name_a_cust_070b78d0' => 'Ο κάδος βρίσκεται στη διαδρομή αντί για το όνομα κεντρικού υπολογιστή. Ένα προσαρμοσμένο τελικό σημείο χρησιμοποιεί ήδη αυτή τη μορφή.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Κάθε εφαρμογή που συνδέει άτομα μέσω του Cbox ID ή καλεί το API του καταχωρίζεται εδώ και αποκτά δικά της διαπιστευτήρια. Κάντε ξεχωριστή καταχώριση ανά εφαρμογή και περιβάλλον. Μην μοιράζεστε διαπιστευτήρια, ώστε να μπορείτε να ανακαλέσετε τα διαπιστευτήρια μιας εφαρμογής χωρίς να σταματήσουν οι άλλες.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Αναζητά οργανισμό με βάση το όνομα ή το αναγνωριστικό, ή χρήστη με βάση το όνομα ή το email, σε όλα τα περιβάλλοντα αυτής της εγκατάστασης, όχι μόνο στο επιλεγμένο στην κονσόλα. Χρησιμοποιήστε το όταν κάποιος ζητά βοήθεια και δεν ξέρετε σε ποιο περιβάλλον βρίσκεται.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Δείτε μια εφαρμογή ακριβώς όπως ένας χρήστης της: συνδέεστε εκ μέρους του, με δηλωμένο λόγο, για έως μία ώρα. Η εφαρμογή ενημερώνεται ποιος την χρησιμοποιεί πραγματικά και δεν λαμβάνει δυνατότητα διατήρησης της συνεδρίας. Το αρχείο καταγραφής ελέγχου του οργανισμού καταγράφει ποιος το έκανε και γιατί.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'Ένα έργο είναι ένα προϊόν IdP που ανήκει σε αυτόν τον οργανισμό και περιλαμβάνει τα περιβάλλοντά του. Μέχρι ο οργανισμός να δημιουργήσει έργο από τη δική του κονσόλα, δεν υπάρχει εδώ περιβάλλον για επιλογή ή άνοιγμα. Αυτή η οθόνη δεν επιτρέπει τη δημιουργία έργου εκ μέρους του οργανισμού.',
