    'sign_in_with_face_id_touch_id_windows_hello__97a33786' => 'Συνδεθείτε με Face ID, Touch ID, Windows Hello ή κλειδί ασφαλείας, χωρίς κωδικό πρόσβασης.',
    'sign_ins_and_changes_to_your_password_passkeys_and_two_9e7da5c8' => 'Εδώ εμφανίζονται οι συνδέσεις και οι αλλαγές στον κωδικό πρόσβασης, στα κλειδιά πρόσβασης και στις ρυθμίσεις ελέγχου ταυτότητας δύο παραγόντων.',
    'text_message_codes_are_no_longer_offered_her_1a9ddf89' => 'Οι κωδικοί μέσω SMS δεν είναι πλέον διαθέσιμοι εδώ. Χρησιμοποιήστε εφαρμογή ελέγχου ταυτότητας ή κλειδί πρόσβασης.',
    'that_device_stops_being_able_to_sign_you_in__5e148d22' => 'Αυτή η συσκευή δεν θα μπορεί πλέον να σας συνδέσει. Μπορείτε να την προσθέσετε ξανά από αυτή τη σελίδα.',
    'that_request_is_no_longer_waiting_it_was_answered_used_80728be7' => 'Αυτό το αίτημα δεν είναι πλέον σε αναμονή: απαντήθηκε, χρησιμοποιήθηκε ή έληξε.',
    'the_agent_is_told_no_when_it_asks_again_and_has_to_star_c28d8870' => 'Στο επόμενο αίτημά του ο πράκτορας λαμβάνει απόρριψη και πρέπει να ξεκινήσει από την αρχή. Η απόρριψη καταγράφεται στο αρχείο ελέγχου.',
    'the_browser_tab_icon_on_your_sign_in_pages_a_square_png_04f6f405' => 'Το εικονίδιο καρτέλας του προγράμματος περιήγησης στις σελίδες σύνδεσης. Τετράγωνο PNG, ICO ή WebP, έως 256 KB.',
    'the_hosted_sign_in_s_look_logo_and_favicon_and_the_name_39304e21' => 'Η εμφάνιση, το λογότυπο και το favicon της φιλοξενούμενης σελίδας σύνδεσης, καθώς και το όνομα και ο αποστολέας που βλέπουν οι χρήστες.',
    'sent_when_someone_s_account_is_created_leave_it_empty_f_c7c58d7f' => 'Αποστέλλεται όταν δημιουργείται ο λογαριασμός κάποιου. Αφήστε το κενό για την προεπιλογή.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Μόνο για πάροχο που δεν δημοσιεύει τα κλειδιά υπογραφής (jwks_uri) στο έγγραφο ανακάλυψης. Διαφορετικά, τα κλειδιά διαβάζονται από εκεί, μαζί με τις ανανεώσεις τους. Εισαγάγετε δημόσιο κλειδί PEM. Αποθηκεύεται κρυπτογραφημένο και δεν εμφανίζεται ξανά· αφήστε κενό για να διατηρήσετε το τρέχον.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Ορισμένα ζεύγη ρόλων δεν πρέπει ποτέ να ανήκουν στο ίδιο άτομο: όποιος δημιουργεί μια πληρωμή δεν πρέπει και να την εγκρίνει. Δηλώστε αυτά τα ζεύγη εδώ. Το Cbox ID αποκλείει νέες αναθέσεις που παραβιάζουν τον κανόνα και εμφανίζει όσους έχουν ήδη ασύμβατο ζεύγος ρόλων.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'Κλειδιά API και token που χρειάζονται οι εφαρμογές και οι πράκτορές σας για άλλες υπηρεσίες, αποθηκευμένα κρυπτογραφημένα εδώ αντί στις ρυθμίσεις κάθε εφαρμογής. Εισάγετε το μυστικό μία φορά και εξουσιοδοτείτε συγκεκριμένες εφαρμογές να το χρησιμοποιούν. Δεν εμφανίζεται ξανά· αν το χάσετε, αντικαταστήστε το.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Διαθέτει τα endpoint ταυτότητας ενός περιβάλλοντος σε δικό σας τομέα, όπως login.example.com, αντί στον δικό μας. Αποδεικνύετε την κατοχή του τομέα με εγγραφή DNS TXT. Ρυθμίστε τον όταν τα άτομα πρέπει να βλέπουν μόνο τη δική σας διεύθυνση κατά τη σύνδεση.',
    'the_name_of_your_organization_which_your_projects_envir_fde906b5' => 'Το όνομα του οργανισμού που περιλαμβάνει τα έργα, τα περιβάλλοντα και την ομάδα σας και εμφανίζεται σε όλη την κονσόλα. Η διαγραφή του διακόπτει όλα τα περιβάλλοντα μέσω των οποίων συνδέονται τα άτομα. Γι’ αυτό γίνεται με αίτημα στην υποστήριξη και όχι με κουμπί.',
