    'the_claim_is_dropped_if_capture_was_on_people_on_this_d_17d5c40e' => 'Η διεκδίκηση του τομέα αφαιρείται. Αν ήταν ενεργό το υποχρεωτικό SSO, οι χρήστες αυτού του τομέα επιστρέφουν στη συνηθισμένη σύνδεση.',
    'this_domain_will_no_longer_route_its_users_through_this_281a9227' => 'Αυτός ο τομέας δεν θα κατευθύνει πλέον τους χρήστες του μέσω του SSO αυτού του οργανισμού. Η ενέργεια δεν μπορεί να αναιρεθεί.',
