    'this_endpoint_stops_receiving_events_and_its_delivery_h_b6a65cf3' => 'Αυτό το τελικό σημείο σταματά να λαμβάνει συμβάντα και το ιστορικό αποστολών του διαγράφεται. Η ενέργεια δεν μπορεί να αναιρεθεί.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_789a1199' => 'Οτιδήποτε έχει συνδέσει ο κάτοχος με αυτό το κλειδί σταματά αμέσως να λειτουργεί. Η ενέργεια δεν μπορεί να αναιρεθεί.',
    'the_name_of_the_organization_these_identity_providers_a_72767cbb' => 'Το όνομα του οργανισμού στον οποίο χρεώνονται και διαχειρίζονται αυτοί οι πάροχοι ταυτότητας.',
    'the_plan_allowance_on_their_first_product_billing_hangs_f5035935' => 'Τα όρια του προγράμματος για το πρώτο προϊόν. Η χρέωση συνδέεται με το προϊόν, όχι με τον οργανισμό.',
    'this_project_has_no_environments_yet_nothing_under_it_s_a2247eb5' => 'Αυτό το έργο δεν έχει ακόμη περιβάλλοντα. Κανένα στοιχείο του δεν παρέχει έλεγχο ταυτότητας.',
    'this_project_has_used_every_environment_its_plan_allows_b891ec0b' => 'Αυτό το έργο έχει χρησιμοποιήσει όλα τα περιβάλλοντα που επιτρέπει το πρόγραμμά του. Αναβαθμίστε το πρόγραμμα για να προσθέσετε περισσότερα.',
    'this_project_is_at_its_environment_limit_upgrade_its_pl_c7856d59' => 'Αυτό το έργο έχει φτάσει το όριο περιβαλλόντων. Αναβαθμίστε το πρόγραμμά του για να προσθέσετε περισσότερα.',
    'usage_counters_fill_as_your_team_signs_in_invites_membe_a589d0b9' => 'Οι μετρητές χρήσης ενημερώνονται καθώς η ομάδα σας συνδέεται, προσκαλεί μέλη και εκδίδει διακριτικά.',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Κάθε οργανισμός είναι εταιρεία ή ομάδα που χρησιμοποιεί το προϊόν σας, με δικά της μέλη, ρόλους, τομείς και ενιαία σύνδεση. Δημιουργήστε έναν για κάθε εταιρεία που εγγράφεται. Ανοίξτε τον για διαχείριση μελών, προσκλήσεων και επαληθευμένων τομέων ή για αναστολή.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Το Cbox ID στέλνει υπογεγραμμένο μήνυμα στο endpoint σας αφού συμβεί κάτι, όπως προσθήκη μέλους ή αλλαγή ρόλου, ώστε τα συστήματά σας να αντιδρούν χωρίς περιοδικά ερωτήματα. Οι αποτυχημένες παραδόσεις επαναλαμβάνονται. Το συμβάν έχει ήδη γίνει: το endpoint ενημερώνεται, δεν αποφασίζει το αποτέλεσμα.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Ένα σχήμα ορίζει τη δομή των συμβάντων μιας ενέργειας: ποιους τύπους στόχων αναφέρουν και τι περιέχουν τα μεταδεδομένα τους. Τα συμβάντα ενέργειας με σχήμα ελέγχονται κατά την παραλαβή. Χωρίς σχήμα γίνονται δεκτά όπως στάλθηκαν, εκτός αν είναι ενεργή η αυστηρή λειτουργία.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Όλοι όσοι διαχειρίζονται αυτόν τον οργανισμό, ο ενσωματωμένος ρόλος τους — Ιδιοκτήτης, Διαχειριστής, Προγραμματιστής, Μέλος ή Θεατής — και τα περιβάλλοντα στα οποία έχουν πρόσβαση. Προσκαλέστε άτομα μέσω email και δώστε σε καθένα μόνο τα περιβάλλοντα που χρειάζεται για τη δουλειά του.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Επιτρέψτε στους χρήστες των εφαρμογών σας να συνδέσουν τους δικούς τους λογαριασμούς GitHub, Google, Slack ή Salesforce, ώστε οι εφαρμογές να καλούν αυτά τα API εκ μέρους τους. Τα token αποθηκεύονται κρυπτογραφημένα και ανανεώνονται εδώ, ενώ παραχωρούνται προσωρινά μόνο στις εξουσιοδοτημένες εφαρμογές.',
    'the_invitee_accepts_by_email_nobody_is_added_to_an_orga_04408aaf' => 'Ο προσκεκλημένος αποδέχεται μέσω email. Κανείς δεν προστίθεται σε οργανισμό χωρίς τη συγκατάθεσή του.',
    'this_user_has_no_signed_in_sessions_right_now_they_appe_0ac73d09' => 'Αυτός ο χρήστης δεν έχει συνδεδεμένες συνεδρίες αυτή τη στιγμή. Θα εμφανιστούν εδώ μόλις συνδεθεί.',
    'this_user_is_held_at_a_password_change_they_cannot_reac_ce196382' => 'Αυτός ο χρήστης πρέπει να αλλάξει κωδικό πρόσβασης. Δεν μπορεί να αποκτήσει πρόσβαση σε τίποτα μέχρι να αντικαταστήσει αυτόν που του δώσατε.',
    'user_created_they_have_no_way_to_sign_in_until_you_send_a612f0b1' => 'Ο χρήστης δημιουργήθηκε. Δεν μπορεί να συνδεθεί μέχρι να του στείλετε έναν σύνδεσμο.',
    'user_erased_their_account_is_pseudonymised_and_the_eras_51e1f69a' => 'Τα δεδομένα του χρήστη διαγράφηκαν. Ο λογαριασμός ψευδωνυμοποιήθηκε και η διαγραφή καταγράφηκε ως user.erased στο αρχείο ελέγχου.',
    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Οι διαχειριστές της πλατφόρμας διαχειρίζονται όλους τους οργανισμούς και τα περιβάλλοντα αυτής της εγκατάστασης, σε επίπεδο πάνω από το καθένα. Προσθέστε διαχειριστή μόνο για άτομο που λειτουργεί την ίδια την εγκατάσταση και αναστείλετέ τον όταν πάψει να έχει αυτήν την ευθύνη.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Όλοι οι οργανισμοί του περιβάλλοντος που έχει επιλεγεί στην κονσόλα, σε δέντρο μεταπωλητών, οργανισμών που διαχειρίζονται και υπομονάδων τους. Δημιουργήστε οργανισμό εδώ, αναστείλετε κάποιον ή μετακινήστε τον κάτω από άλλον γονικό οργανισμό.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Συνδέσεις, εκδοθέντα token, νέοι χρήστες και εγγραφές ελέγχου ταυτότητας δύο παραγόντων, ανά ημέρα για τις τελευταίες 30 ημέρες, εκτός αν η εγκατάσταση ορίζει άλλο διάστημα. Η σελίδα μένει κενή μέχρι ο υπεύθυνος της εγκατάστασης να ρυθμίσει την αποθήκευση των αναλυτικών δεδομένων.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Ορίστε αυτήν την πολιτική εμπιστοσύνης για τον ρόλο (IAM › Roles › Trust relationships). Η πλατφόρμα μπορεί να αναλάβει τον ρόλο μόνο παρουσιάζοντας το εξωτερικό ID αυτής της ροής, ώστε κανείς άλλος στην πλατφόρμα να μην μπορεί να κατευθύνει ροή στον ρόλο σας.',
    'presets_colours_corners_type_edited_with_a_live_preview_ff61e898' => 'Προρυθμίσεις, χρώματα, γωνίες και τυπογραφία, με ζωντανή προεπισκόπηση κατά την επεξεργασία.',
    'where_a_copy_of_every_audit_entry_is_delivered_as_it_is_c6b9e401' => 'Πού αποστέλλεται ένα αντίγραφο κάθε εγγραφής ελέγχου τη στιγμή που δημιουργείται.',
    'where_sign_ins_go_for_people_who_have_not_moved_to_cbox_be5f68b3' => 'Πού κατευθύνονται οι συνδέσεις των ατόμων που δεν έχουν μεταφερθεί ακόμη στο Cbox ID.',
    'where_the_provider_posts_its_assertion_give_this_to_who_5b098f34' => 'Πού στέλνει ο πάροχος τη δήλωση ταυτοποίησής του. Δώστε αυτή τη διεύθυνση σε όποιον ρυθμίζει τον IdP.',
    'where_the_signed_assertion_is_posted_back_must_be_https_2dc6e396' => 'Πού αποστέλλεται πίσω η υπογεγραμμένη δήλωση ταυτοποίησης. Πρέπει να χρησιμοποιεί https.',
    'where_we_exchange_the_client_credentials_for_a_short_li_2afa7c75' => 'Πού ανταλλάσσουμε τα διαπιστευτήρια πελάτη με ένα διακριτικό μικρής διάρκειας πριν από κάθε παρτίδα.',
    'who_connected_an_account_through_this_pipe_tokens_are_n_ea456475' => 'Ποιος συνέδεσε λογαριασμό μέσω αυτής της σύνδεσης. Τα διακριτικά δεν εμφανίζονται ποτέ.',
    'this_connection_belongs_to_the_environment_itself_it_si_543963d3' => 'Αυτή η σύνδεση ανήκει στο ίδιο το περιβάλλον. Συνδέει τα άτομα χωρίς να τα εντάσσει σε κανέναν οργανισμό.',
