    'whose_people_sign_in_through_it_its_domains_and_admin_p_9c461a3e' => 'Τίνος οργανισμού τα άτομα συνδέονται μέσω αυτής της σύνδεσης. Οι τομείς και ο σύνδεσμος προς την πύλη διαχείρισης βρίσκονται στη σελίδα του οργανισμού.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Όλα τα προγράμματα περιήγησης και οι συσκευές που έχουν συνδεθεί στον λογαριασμό σας, οι εξουσιοδοτημένες εφαρμογές και οι πρόσφατες συνδέσεις και αλλαγές ασφάλειας. Αν δεν αναγνωρίζετε κάποια δραστηριότητα, αποσυνδέστε τη συνεδρία ή ανακαλέστε την εφαρμογή και μετά αλλάξτε κωδικό πρόσβασης.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Κάθε αλλαγή σε αυτόν τον οργανισμό: ποιος έκανε τι, σε ποιο αντικείμενο και πότε. Οι εγγραφές συνδέονται με αλυσίδα κατακερματισμού, οπότε η αφαίρεση ή επεξεργασία εγγραφής σπάει την αλυσίδα και ανιχνεύεται. Είναι σκόπιμα μόνο για ανάγνωση — αυτό είναι το αρχείο που παραδίδετε σε έναν ελεγκτή.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Αφήστε κενό για σχεδόν όλους τους παρόχους: τα ID token επαληθεύονται με τα κλειδιά υπογραφής που δημοσιεύονται στο έγγραφο ανακάλυψης (jwks_uri), μαζί με τις ανανεώσεις τους. Επικολλήστε το δημόσιο κλειδί PEM του παρόχου μόνο αν δεν δημοσιεύει κανένα.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Συνδέσεις και αιτήματα που το Cbox ID έκρινε αρκετά επικίνδυνα ώστε να επισημανθούν, με τα πιο πρόσφατα πρώτα, μαζί με τη βαθμολογία και τους λόγους. Ελέγξτε εδώ μετά από αύξηση αποτυχημένων συνδέσεων ή όταν κάποιος αναφέρει σύνδεση που δεν έκανε.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Αυτό το περιβάλλον διαθέτει διακομιστή MCP μαζί με το REST API. Συνδέστε έναν πράκτορα με κλειδί διαχείρισης και θα μπορεί να κάνει ακριβώς ό,τι επιτρέπουν τα πεδία πρόσβασης του κλειδιού, με τους ίδιους ελέγχους, εγκρίσεις και αρχείο καταγραφής ελέγχου όπως η κονσόλα.',
    'nothing_recorded_matches_these_filters_widen_the_range_804705cd' => 'Δεν υπάρχει καταγεγραμμένο στοιχείο που να αντιστοιχεί στα φίλτρα. Διευρύνετε το διάστημα ή αφαιρέστε ένα φίλτρο.',
