    'who_is_signed_in_as_them_right_now_why_a_sign_in_was_al_181f0520' => 'Ποιος είναι συνδεδεμένος ως αυτό το άτομο αυτή τη στιγμή. Το Radar δείχνει γιατί μια σύνδεση επιτράπηκε, απαίτησε πρόσθετη επαλήθευση ή αποκλείστηκε.',
