    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Ο πάροχος ενός οργανισμού αντικαθιστά τον πάροχο του περιβάλλοντος στη σελίδα σύνδεσής του. Εμφανίζονται επίσης οργανισμοί που απενεργοποίησαν τον πάροχο του περιβάλλοντος. Αυτό αφαιρεί μόνο το κουμπί από τη σελίδα· η υποχρεωτική χρήση SSO είναι αυτή που αποκλείει την πρόσβαση με αυτήν τη μέθοδο.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Οι εφαρμογές με δικό τους κατάλογο χρηστών χάνουν τον συγχρονισμό μόλις κάποιος προστεθεί ή αποχωρήσει. Μια σύνδεση SCIM τους στέλνει κάθε αλλαγή όταν συμβαίνει, μαζί με τις αποχωρήσεις, που είναι οι πιο εύκολες να ξεχαστούν.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Κατευθύνετε έναν πάροχο ταυτότητας στο endpoint SCIM μας, συνδέστε Google Workspace ή Microsoft Entra ή συνδέστε το σύστημα ανθρώπινου δυναμικού σας — Workday, BambooHR, Rippling, HiBob ή Personio. Θα ανακτούμε τα στοιχεία των ατόμων σε προγραμματισμένα διαστήματα.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'Το ιστορικό ελέγχου βρίσκεται εδώ και τα εργαλεία της ομάδας ασφάλειας αλλού. Μια ροή αντιγράφει κάθε εγγραφή σε αυτά τη στιγμή που γράφεται, ώστε η έρευνα να μην αρχίζει με αίτημα εξαγωγής CSV.',
    'the_authorization_and_token_endpoints_are_discovered_fr_f26237b1' => 'Τα τελικά σημεία εξουσιοδότησης και διακριτικών εντοπίζονται από τον εκδότη, οπότε δεν χρειάζεται να επικολλήσετε τίποτε άλλο.',
    'who_issued_it_the_name_you_would_search_for_in_their_da_22a5c245' => 'Ποιος το εξέδωσε — το όνομα που θα αναζητούσατε στον πίνακα ελέγχου του παρόχου.',
    'verify_that_authnrequests_really_come_from_this_applica_f3c58c70' => 'Επαληθεύστε ότι τα AuthnRequests προέρχονται πράγματι από αυτή την εφαρμογή, χρησιμοποιώντας το δικό της πιστοποιητικό υπογραφής.',
    'this_is_exactly_how_your_sign_in_renders_the_preview_sh_a4878600' => 'Έτσι ακριβώς εμφανίζεται η σελίδα σύνδεσής σας. Η προεπισκόπηση χρησιμοποιεί τον ίδιο μηχανισμό θεμάτων με τη ζωντανή σελίδα.',
    'this_is_your_environment_s_default_sign_in_an_organizat_d17d58dd' => 'Αυτή είναι η προεπιλεγμένη εμφάνιση σύνδεσης του περιβάλλοντός σας. Ένας οργανισμός μπορεί να την αντικαταστήσει με το δικό του θέμα.',
    'what_your_people_see_in_place_of_cbox_id_and_who_your_m_32cb946d' => 'Τι βλέπουν οι χρήστες αντί για το Cbox ID και ποιος εμφανίζεται ως αποστολέας των email σας.',
    'your_branding_changes_have_not_been_saved_leave_this_pa_1a8dbb2f' => 'Οι αλλαγές στην εταιρική εμφάνιση δεν έχουν αποθηκευτεί. Αν φύγετε από αυτή τη σελίδα, θα χαθούν.',
    'organization_suspended_its_members_can_no_longer_sign_i_35d8877a' => 'Ο οργανισμός ανεστάλη. Τα μέλη του δεν μπορούν πλέον να συνδεθούν και τα περιβάλλοντά του σταματούν να παρέχουν έλεγχο ταυτότητας.',
    'a_downstream_api_key_your_apps_and_agents_present_to_a_069a6a5e' => 'Κλειδί API εξωτερικής υπηρεσίας που οι εφαρμογές και οι πράκτορες παρουσιάζουν σε πάροχο. Αποθηκεύεται κρυπτογραφημένο και διατίθεται μόνο σε ρητά εξουσιοδοτημένους πελάτες.',
    'a_list_of_the_target_types_this_action_may_name_each_wi_26513896' => 'Λίστα τύπων στόχων που μπορεί να αναφέρει αυτή η ενέργεια, καθένας με προαιρετικό σχήμα μεταδεδομένων. Αφήστε κενή για να επιτρέπονται όλοι οι τύποι.',
    'a_separate_identity_provider_product_with_its_own_envir_97a4c57b' => 'Ξεχωριστό προϊόν παρόχου ταυτότητας με δικά του περιβάλλοντα και πρόγραμμα, που χρεώνεται ανεξάρτητα από τα υπόλοιπα έργα σας.',
    'add_an_endpoint_and_your_own_systems_hear_about_members_263677b5' => 'Προσθέστε endpoint ώστε τα συστήματά σας να ενημερώνονται αμέσως για νέα μέλη, αλλαγές ρόλων και αποτυχημένες συνδέσεις, χωρίς περιοδικά ερωτήματα ή νυχτερινές εξαγωγές.',
    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'Ένα περιβάλλον είναι πλήρως απομονωμένο, με δικούς του χρήστες, κλειδιά, σύνδεση και εκδότη. Δημιουργήστε το πρώτο παραπάνω και μετά προσθέστε οργανισμό και διαχειριστή.',
    'applications_you_approve_a_command_line_a_device_anothe_9ae677c4' => 'Εδώ εμφανίζονται οι εφαρμογές που εγκρίνετε — εργαλείο γραμμής εντολών, συσκευή ή άλλο προϊόν που σας συνδέει μέσω Cbox ID. Μπορείτε να ανακαλέσετε την πρόσβαση οποιασδήποτε.',
    'as_an_administrator_set_up_an_authenticator__17d31053' => 'Ως διαχειριστής, ρυθμίστε πρώτα εφαρμογή ελέγχου ταυτότητας ή κλειδί πρόσβασης. Έπειτα μπορείτε να προσθέσετε αριθμό τηλεφώνου ως εφεδρική μέθοδο.',
    'attempts_this_rule_decided_are_decided_by_the_next_matc_ebfc6722' => 'Από την επόμενη απόπειρα, οι περιπτώσεις που έκρινε αυτός ο κανόνας θα κρίνονται από τον επόμενο αντίστοιχο κανόνα ή τους ενσωματωμένους κανόνες.',
    'called_synchronously_while_somebody_waits_at_the_sign_i_cf697019' => 'Καλείται συγχρονισμένα ενώ το άτομο περιμένει στην οθόνη σύνδεσης. Επαληθεύετε την κεφαλίδα X-Cbox-Signature σε κάθε αίτημα.',
    'change_where_this_stream_delivers_or_the_credential_it_e8fc2e8f' => 'Αλλάξτε τον προορισμό της ροής ή το διαπιστευτήριο που χρησιμοποιεί. Η αποθήκευση ελέγχει ξανά τις ρυθμίσεις και επαναλαμβάνει την παράδοση στην επόμενη εκτέλεση.',
    'issue_a_fresh_token_the_one_your_identity_provider_hold_c37da34e' => 'Εκδώστε νέο token. Το token που χρησιμοποιεί τώρα ο πάροχος ταυτότητας σταματά αμέσως να λειτουργεί. Μετά την αντικατάσταση, αντιγράψτε αμέσως το νέο token στον πάροχο ταυτότητας.',
    'withdrawn_people_already_migrated_are_unaffected_anyone_228f7b22' => 'Αποσύρθηκε. Τα άτομα που έχουν ήδη μεταφερθεί δεν επηρεάζονται· όσοι παραμένουν στο παλιό σύστημα δεν μπορούν να συνδεθούν.',
    'your_existing_codes_stop_working_immediately_c2dbcb02' => 'Οι υπάρχοντες κωδικοί σας σταματούν αμέσως να λειτουργούν. Οι νέοι εμφανίζονται μία φορά.',
    'your_profile_how_you_sign_in_and_the_session_ab7a0592' => 'Το προφίλ σας, οι τρόποι σύνδεσης και οι συνεδρίες που είναι τώρα συνδεδεμένες στον λογαριασμό σας.',
    'you_sign_in_to_the_provider_and_it_is_linked_59410359' => 'Συνδέεστε στον πάροχο και ο λογαριασμός συνδέεται με εσάς όταν επιστρέψετε.',
    'this_app_signs_assertions_with_its_own_keys_and_has_no_7e457dd4' => 'Αυτή η εφαρμογή υπογράφει δηλώσεις με τα δικά της κλειδιά και δεν έχει μυστικό πελάτη. Αντικαταστήστε το κλειδί στο JWKS της.',
    'agent_preset_support_description' => 'Διαβάζει τα πάντα και βοηθά με χρήστες, συμμετοχές και προσκλήσεις. Κάθε καταστροφική ενέργεια περιμένει την έγκρισή σας.',
    'an_app_signs_people_in_only_to_the_urls_it_lists_charac_a7f88d2a' => 'Η εφαρμογή επιστρέφει τους χρήστες μετά τη σύνδεση μόνο στα URL που δηλώνει, με αντιστοιχία χαρακτήρα προς χαρακτήρα. Επισημαίνεται μόλις μία εφαρμογή σας αποκτήσει ένα.',
    'attach_this_to_the_role_it_may_write_objects_under_the_3d2c7384' => 'Συνδέστε αυτή την πολιτική με τον ρόλο: επιτρέπει μόνο εγγραφή αντικειμένων με το συγκεκριμένο πρόθεμα, χωρίς ανάγνωση, προβολή λίστας ή διαγραφή.',
    'commit_this_file_and_give_each_person_their_own_key_in_f23e11a2' => 'Προσθέστε αυτό το αρχείο στον έλεγχο εκδόσεων και δώστε σε κάθε άτομο δικό του κλειδί στη μεταβλητή περιβάλλοντος. Το ίδιο το αρχείο δεν περιέχει μυστικό.',
    'connect_entra_id_okta_or_google_workspace_and_your_peop_688a5abf' => 'Συνδέστε το Entra ID, το Okta ή το Google Workspace και οι χρήστες θα συνδέονται με τον εταιρικό λογαριασμό που ήδη διαθέτουν.',
    'every_change_made_here_who_did_what_to_what_and_when_ha_4f61494d' => 'Κάθε αλλαγή που γίνεται εδώ: ποιος έκανε τι, σε ποιο στοιχείο και πότε. Οι εγγραφές συνδέονται με κατακερματισμούς, ώστε να εντοπίζεται η αφαίρεσή τους.',
    'failed_sign_ins_on_one_address_within_an_hour_from_anyw_cdda8940' => 'Αποτυχημένες συνδέσεις σε μία διεύθυνση email μέσα σε μία ώρα, από οποιαδήποτε πηγή — εντοπίζει δοκιμές κωδικών κατανεμημένες σε πολλές διευθύνσεις IP.',
    'give_people_roles_instead_of_blanket_access_so_every_co_8788f6f3' => 'Δώστε ρόλους αντί για καθολική πρόσβαση, ώστε κάθε συνδεδεμένη εφαρμογή να γνωρίζει ποιος είναι συντάκτης και ποιος έχει μόνο δικαίωμα ανάγνωσης.',
    'image_uploads_are_not_available_on_this_install_the_whi_e33690d3' => 'Η μεταφόρτωση εικόνων δεν είναι διαθέσιμη σε αυτή την εγκατάσταση: η μονάδα προσαρμοσμένης επωνυμίας που τις αποθηκεύει δεν είναι ενεργή.',
    'it_decides_the_kind_of_app_and_its_localhost_redirect_t_0f18e4ab' => 'Καθορίζει τον τύπο εφαρμογής και την ανακατεύθυνση localhost, με τη θύρα που χρησιμοποιεί ο διακομιστής ανάπτυξης του framework σας.',
    'it_is_sealed_on_save_and_never_displayed_again_not_here_e9ace615' => 'Κρυπτογραφείται κατά την αποθήκευση και δεν εμφανίζεται ποτέ ξανά: ούτε εδώ, ούτε στη σελίδα του μυστικού, ούτε μετά από αντικατάσταση.',
    'let_this_app_call_the_decision_endpoint_for_a_person_s_1b1d78dd' => 'Επιτρέψτε σε αυτή την εφαρμογή να καλεί το τελικό σημείο αποφάσεων για τα δικαιώματα και τις παροχές ενός ατόμου σε έναν οργανισμό.',
    'matches_organization_name_slug_and_user_email_name_case_1c34d2a1' => 'Αναζητά στο όνομα ή slug οργανισμού και στο email ή όνομα χρήστη. Δεν διακρίνει πεζά και κεφαλαία· τα % και _ είναι κυριολεκτικοί χαρακτήρες, όχι μπαλαντέρ.',
    'no_browser_of_its_own_a_terminal_a_ci_job_a_tv_the_pers_3abb52d5' => 'Δεν διαθέτει δικό του πρόγραμμα περιήγησης — τερματικό, εργασία CI ή τηλεόραση. Το άτομο εγκρίνει από το κινητό ή τον φορητό υπολογιστή του.',
    'no_providers_for_the_environment_yet_people_sign_in_wit_c6bb86e5' => 'Δεν υπάρχουν ακόμη πάροχοι για το περιβάλλον — οι χρήστες συνδέονται με κωδικό πρόσβασης, σύνδεσμο σύνδεσης ή κλειδί πρόσβασης.',
    'no_secret_is_stored_the_role_trusts_this_platform_with_4b76cd90' => 'Δεν αποθηκεύεται μυστικό. Ο ρόλος εμπιστεύεται αυτή την πλατφόρμα μέσω εξωτερικού ID, το οποίο εμφανίζεται μετά τη δημιουργία του.',
    'off_for_this_environment_passkeys_people_already_added_035a80ca' => 'Απενεργοποιημένο σε αυτό το περιβάλλον. Τα κλειδιά πρόσβασης που έχουν ήδη προστεθεί διατηρούνται και λειτουργούν ξανά αν το ενεργοποιήσετε.',
    'offered_a_person_adds_one_from_their_own_account_face_i_8d7b4dc0' => 'Διαθέσιμο — κάθε άτομο προσθέτει ένα από τον λογαριασμό του. Face ID, Touch ID, Windows Hello ή κλειδί ασφαλείας.',
    'only_an_app_that_holds_a_secret_or_its_own_keys_can_exc_b8912c8c' => 'Μόνο εφαρμογή που διαθέτει μυστικό ή δικά της κλειδιά μπορεί να ανταλλάσσει διακριτικά. Μια δημόσια εφαρμογή δεν μπορεί να αποδείξει ποιος υποβάλλει το αίτημα.',
    'pipe_configured_the_client_secret_is_sealed_and_never_s_21a370a1' => 'Η σύνδεση ρυθμίστηκε. Το μυστικό του πελάτη αποθηκεύτηκε κρυπτογραφημένο και δεν εμφανίζεται ξανά. Δώστε πρόσβαση σε εφαρμογή για να αρχίσει η προσωρινή παραχώρηση token.',
    'provision_and_deprovision_their_people_over_scim_from_t_150caa32' => 'Δημιουργήστε και ανακαλέστε την πρόσβαση των χρηστών τους μέσω SCIM από τον κατάλογο ή το σύστημα ανθρώπινου δυναμικού τους.',
    'recorded_not_routed_the_environment_serves_its_own_issu_1e644612' => 'Καταγράφηκε, χωρίς δρομολόγηση: το περιβάλλον χρησιμοποιεί τον δικό του εκδότη μέχρι να επαληθευτεί ο τομέας μέσω DNS.',
    'replace_the_principal_with_this_platform_s_aws_user_arn_a5e64445' => 'Αντικαταστήστε το Principal με το ARN του χρήστη AWS αυτής της πλατφόρμας — ρωτήστε τον διαχειριστή της εγκατάστασης (SIEM_AWS_PRINCIPAL_ARN).',
    'reply_2xx_quickly_and_do_the_real_work_in_the_backgroun_90953132' => 'Απαντήστε γρήγορα με 2xx και εκτελέστε την εργασία στο παρασκήνιο — οι παραδόσεις επαναλαμβάνονται, γι’ αυτό χειριστείτε με ασφάλεια τις επαναλήψεις.',
    'segregation_of_duties_rules_are_checked_in_every_organi_8204cb95' => 'Οι κανόνες διαχωρισμού καθηκόντων ελέγχονται σε κάθε οργανισμό στον οποίο ανήκει το άτομο. Η άρνηση αναφέρει σε ποιον οργανισμό υπάρχει σύγκρουση.',
    'send_people_to_the_connect_page_lease_a_token_from_your_db119651' => 'Στείλτε τους χρήστες στη σελίδα σύνδεσης λογαριασμού. Σε κάθε κλήση προς τον πάροχο, αποκτήστε προσωρινή πρόσβαση σε διακριτικό από το backend.',
    'shorter_than_today_events_older_than_this_are_deleted_f_8cf235f8' => 'Μικρότερο από το σημερινό διάστημα: στην επόμενη καθημερινή εκκαθάριση θα διαγραφούν οριστικά τα παλαιότερα συμβάντα για κάθε οργανισμό.',
    'that_approval_was_already_used_or_was_given_for_a_diffe_86a561c7' => 'Αυτή η έγκριση έχει ήδη χρησιμοποιηθεί ή δόθηκε για διαφορετικό αίτημα. Επαναλάβετε το αίτημα χωρίς αυτήν, για να ζητήσετε νέα.',
    'that_favicon_cannot_be_used_svg_is_not_accepted_it_can_7a4eba69' => 'Αυτό το εικονίδιο ιστοτόπου δεν μπορεί να χρησιμοποιηθεί. Το SVG δεν γίνεται δεκτό, επειδή μπορεί να περιέχει κώδικα. Χρησιμοποιήστε PNG, ICO ή WebP.',
    'that_logo_cannot_be_used_svg_is_not_accepted_it_can_car_4affcd99' => 'Αυτό το λογότυπο δεν μπορεί να χρησιμοποιηθεί. Το SVG δεν γίνεται δεκτό, επειδή μπορεί να περιέχει κώδικα. Χρησιμοποιήστε PNG, JPEG ή WebP.',
    'the_acs_url_must_use_https_http_is_allowed_only_on_loca_c596bd8b' => 'Το ACS URL πρέπει να χρησιμοποιεί https (το http επιτρέπεται μόνο στο localhost), να είναι απόλυτο και να μην περιέχει τμήμα fragment.',
    'the_agent_will_act_as_you_with_your_access_and_no_key_t_dd9fa746' => 'Ο πράκτορας θα ενεργεί εκ μέρους σας, με τη δική σας πρόσβαση, χωρίς κλειδί για φύλαξη. Μέχρι τότε, η πρόσβαση γίνεται με κλειδί διαχείρισης.',
    'the_audit_events_the_app_records_about_this_organizatio_5a83961e' => 'Τα συμβάντα ελέγχου που καταγράφει η εφαρμογή για αυτόν τον οργανισμό, με τα πιο πρόσφατα πρώτα. Μόνο για ανάγνωση: τίποτα εδώ δεν αλλάζει.',
    'the_dns_txt_record_isn_t_visible_yet_dns_can_take_a_few_e4111709' => 'Η εγγραφή DNS TXT δεν είναι ακόμη ορατή. Η διάδοση DNS μπορεί να χρειαστεί λίγα λεπτά — δοκιμάστε ξανά σύντομα.',
    'the_environment_s_default_sign_in_theme_inherited_by_ev_aa90ec1d' => 'Η προεπιλεγμένη εμφάνιση σύνδεσης του περιβάλλοντος — κληρονομείται από κάθε οργανισμό που δεν έχει ορίσει δική του.',
    'the_teams_using_your_product_each_is_a_company_or_group_91579359' => 'Οι ομάδες που χρησιμοποιούν το προϊόν σας. Κάθε μία είναι εταιρεία ή ομάδα με δικούς της χρήστες, ρόλους και ενιαία σύνδεση.',
    'this_deployment_does_not_let_an_mcp_client_sign_you_in__2bbe3144' => 'Αυτή η εγκατάσταση δεν επιτρέπει σε πελάτη MCP να σας συνδέσει στο ανώτατο επίπεδο της πλατφόρμας. Χρησιμοποιήστε το CLI cbox ή ένα κλειδί οργανισμού παρακάτω.',
    'this_idempotency_key_was_already_used_for_a_different_r_0c304fb5' => 'Αυτό το Idempotency-Key έχει ήδη χρησιμοποιηθεί για διαφορετικό αίτημα. Χρησιμοποιήστε νέο κλειδί για νέο αίτημα.',
    'this_is_the_app_s_only_live_secret_rotate_it_to_replace_70716789' => 'Αυτό είναι το μόνο ενεργό μυστικό της εφαρμογής. Αντικαταστήστε το ή διαγράψτε την εφαρμογή για να την απενεργοποιήσετε.',
    'this_organization_owns_identity_provider_projects_on_th_f851615d' => 'Αυτός ο οργανισμός κατέχει έργα παρόχων ταυτότητας στην πλατφόρμα και δεν μπορεί να αρχειοθετηθεί εδώ.',
    'ticks_once_an_app_sends_people_back_to_a_real_https_add_248c1799' => 'Επισημαίνεται μόλις μια εφαρμογή επιστρέφει τους χρήστες σε πραγματική διεύθυνση https αντί για localhost.',
    'try_part_of_the_name_the_routing_slug_or_a_custom_domai_7c76fa0d' => 'Δοκιμάστε μέρος του ονόματος, το αναγνωριστικό δρομολόγησης ή έναν προσαρμοσμένο τομέα.',
