    'your_colours_and_logo_on_the_hosted_sign_in_page_checke_54995b02' => 'Τα χρώματα και το λογότυπό σας στη φιλοξενούμενη σελίδα σύνδεσης, με έλεγχο αντίθεσης σε ανοιχτό και σκούρο θέμα.',
