    'your_organization_its_projects_team_keys_and_billing_si_152a2f42' => 'Ο οργανισμός σας: έργα, ομάδα, κλειδιά και χρέωση. Η σύνδεση των εφαρμογών σας ρυθμίζεται στην κονσόλα κάθε περιβάλλοντος.',
    'organization_results_limited' => 'Εμφανίζονται οι πρώτες 500 αντιστοιχίες. Η ιεραρχία είναι μερική. Περιορίστε την αναζήτηση για να βρείτε περισσότερους οργανισμούς.',
    'totp_description' => 'Προσθέστε κάθε εφαρμογή ξεχωριστά. Καθεμία αποκτά δικό της κλειδί, ώστε να αφαιρείτε μία χωρίς να επηρεάζετε τις άλλες.',
