    'totp_remove_explanation' => 'Οι κωδικοί από αυτή την εφαρμογή θα σταματήσουν να λειτουργούν. Οι άλλες εφαρμογές και οι κωδικοί ανάκτησης παραμένουν ενεργοί.',
