    'a_pill_says_the_state_in_words_the_tone_only_10648ffe' => 'Η ετικέτα εκφράζει την κατάσταση με λέξεις· ο χρωματισμός απλώς την ενισχύει.',
    'an_organization_key_acts_with_its_built_in_r_5906ff85' => 'Το κλειδί οργανισμού ενεργεί με τον ενσωματωμένο ρόλο του σε όλον τον οργανισμό και η τιμή του εμφανίζεται μόνο μία φορά.',
