    'api_key_created_copy_it_now_it_will_not_be_s_37fc2c91' => 'Το κλειδί API δημιουργήθηκε — αντιγράψτε το τώρα, γιατί δεν θα εμφανιστεί ξανά.',
    'connecting_a_directory_issues_a_bearer_token_c946f8c1' => 'Η σύνδεση καταλόγου εκδίδει ένα διακριτικό πρόσβασης για τη διαχείριση των λογαριασμών σας, το οποίο εμφανίζεται μόνο μία φορά στην επόμενη οθόνη.',
    'copying_an_app_registers_it_in_another_envir_b6eb3523' => 'Η αντιγραφή εφαρμογής την καταχωρίζει σε άλλο περιβάλλον με νέο μυστικό πελάτη, το οποίο εμφανίζεται μόνο μία φορά στην επόμενη οθόνη.',
    'each_redirect_uri_must_use_https_http_is_all_5445c31e' => 'Κάθε URI ανακατεύθυνσης πρέπει να χρησιμοποιεί https (το http επιτρέπεται μόνο στο localhost) — για παράδειγμα https://app.example.com/callback.',
    'a_permission_key_is_two_words_joined_by_a_colon_a_featu_b830fc34' => 'Το κλειδί δικαιώματος αποτελείται από δύο λέξεις ενωμένες με άνω και κάτω τελεία — μια λειτουργία και μια ενέργεια, όπως invoices:create.',
    'add_the_people_who_will_administer_this_organization_wi_75edc5a6' => 'Προσθέστε τα άτομα που θα διαχειρίζονται αυτόν τον οργανισμό μαζί σας. Ρυθμίζουν μόνα τους τη σύνδεσή τους, ώστε να μη χειρίζεστε ποτέ τους κωδικούς πρόσβασής τους.',
    'an_iam_user_allowed_only_s3_putobject_on_the_bucket_its_5337441e' => 'Χρήστης IAM με άδεια μόνο για s3:PutObject στον κάδο. Το μυστικό κλειδί πρόσβασής του αποθηκεύεται κρυπτογραφημένο.',
    'an_organization_is_one_of_the_teams_that_use_your_produ_509fd742' => 'Ένας οργανισμός είναι μία από τις ομάδες που χρησιμοποιούν το προϊόν σας: τα μέλη, οι ρόλοι και η πολιτική ταυτοποίησής του παραμένουν χωριστά από όλους τους υπόλοιπους.',
    'anyone_who_has_not_migrated_yet_stops_being_able_to_sig_ed9f870a' => 'Όσοι δεν έχουν ακόμη μεταφερθεί δεν θα μπορούν να συνδεθούν μέχρι να εγκριθεί ξανά αυτό. Όσοι έχουν ήδη μεταφερθεί δεν επηρεάζονται.',
    'every_other_browser_and_device_holding_a_session_as_you_3d2d96e0' => 'Όλα τα άλλα προγράμματα περιήγησης και συσκευές με συνεδρία στον λογαριασμό σας χάνουν πρόσβαση στο επόμενο αίτημα. Αυτή η συνεδρία παραμένει ενεργή.',
    'every_way_you_can_sign_in_linking_is_always__bcef066d' => 'Όλοι οι τρόποι σύνδεσης. Η συσχέτιση είναι πάντα σκόπιμη: δεν ενώνουμε ποτέ δύο μεθόδους μόνο επειδή ταιριάζουν οι διευθύνσεις email.',
    'everyone_in_it_loses_access_immediately_and_it_disappea_6b76018d' => 'Όλα τα άτομα χάνουν αμέσως την πρόσβαση και ο οργανισμός εξαφανίζεται από όλες τις λίστες. Οι εγγραφές διατηρούνται για το ιστορικό ελέγχου.',
    'expires_at_must_be_in_the_future_a_key_that_has_already_80eeeed0' => 'Το expires_at πρέπει να βρίσκεται στο μέλλον — ένα κλειδί που έχει ήδη λήξει δεν μπορεί να εκτελέσει καμία ενέργεια.',
    'for_one_of_this_environment_s_own_people_an_organizatio_1c327ded' => 'Για άτομο αυτού του περιβάλλοντος που διαχειρίζεται οργανισμό. Ο πράκτορας ενεργεί εκ μέρους του, μέσα στον οργανισμό του.',
    'framework_eea732d53f46' => 'Δεν ήταν δυνατή η ανάγνωση της διαμόρφωσης OpenID του παρόχου — ελέγξτε τη διεύθυνση URL του εκδότη. (:details)',
    'create_a_key_for_claude_code_cursor_or_your_own_bot_giv_90d822be' => 'Δημιουργήστε κλειδί για Claude Code, Cursor ή δικό σας bot. Δώστε μόνο τα απαραίτητα πεδία πρόσβασης και αποφασίστε ποιες ενέργειες περιμένουν την έγκρισή σας.',
    'each_is_an_isolated_stage_production_or_sandbox_with_it_c8b3283a' => 'Κάθε περιβάλλον είναι απομονωμένο στάδιο — παραγωγή ή δοκιμές — με δικούς του χρήστες, κλειδιά και σύνδεση. Ονομάστε ένα «Staging» για το στάδιο προπαραγωγής.',
    'each_organization_is_a_company_or_team_using_your_produ_7719f059' => 'Κάθε οργανισμός είναι εταιρεία ή ομάδα που χρησιμοποιεί το προϊόν σας, με δικούς της χρήστες, ρόλους και ενιαία σύνδεση. Δημιουργήστε τον πρώτο για να ξεκινήσετε.',
