    'every_environment_on_this_install_and_who_owns_it_creat_78b48199' => 'Όλα τα περιβάλλοντα αυτής της εγκατάστασης και οι ιδιοκτήτες τους. Δημιουργήστε ένα, επιλέξτε το στην κονσόλα και προσθέστε τον πρώτο διαχειριστή.',
    'every_member_is_signed_out_of_it_and_refused_at_every_d_67c21f22' => 'Όλα τα μέλη αποσυνδέονται και χάνουν την πρόσβαση από κάθε οδό, ενώ οι εφαρμογές σταματούν να δέχονται τις συνδέσεις τους. Αυτό δεν αναιρείται από την κονσόλα.',
    'every_organization_in_the_target_environment_the_manage_9b4126ae' => 'Όλοι οι οργανισμοί στο περιβάλλον προορισμού: το δέντρο διαχείρισης μεταπωλητών, των οργανισμών που διαχειρίζονται και των υπομονάδων.',
    'every_organization_s_people_are_pushed_to_this_one_targ_27734b94' => 'Τα άτομα κάθε οργανισμού αποστέλλονται σε αυτόν τον μοναδικό προορισμό. Δεν είναι το ίδιο με την επιλογή οργανισμού παραπάνω: η σύνδεση καλύπτει ολόκληρο το περιβάλλον.',
    'from_the_next_attempt_nothing_is_refused_or_challenged_0dcf7713' => 'Από την επόμενη προσπάθεια, τίποτα δεν απορρίπτεται ούτε ζητείται πρόσθετη επαλήθευση — ακόμη και για μαζικές δοκιμές κλεμμένων διαπιστευτηρίων. Οι αποφάσεις εξακολουθούν να καταγράφονται.',
    'how_your_organization_s_own_team_signs_in_to_cbox_id_no_11ea0db7' => 'Πώς συνδέεται η ίδια η ομάδα του οργανισμού σας στο Cbox ID — όχι στις εφαρμογές σας: η σύνδεσή τους ρυθμίζεται στην κονσόλα κάθε περιβάλλοντος.',
    'it_disappears_from_every_list_and_its_people_are_refuse_49a9035c' => 'Ο οργανισμός εξαφανίζεται από όλες τις λίστες και τα άτομά του χάνουν πρόσβαση παντού, όπως ακριβώς στην αναστολή. Οι εγγραφές διατηρούνται.',
    'left_empty_a_signing_key_is_generated_for_you_and_shown_7cc3e0ba' => 'Αν αφήσετε κενό, δημιουργείται κλειδί υπογραφής και εμφανίζεται μία φορά. Αποθηκεύεται κρυπτογραφημένο και δεν μπορεί να ανακτηθεί ξανά.',
    'let_your_identity_provider_create_update_and_deactivate_1208087e' => 'Επιτρέψτε στον πάροχο ταυτότητας να δημιουργεί, να ενημερώνει και να απενεργοποιεί αυτόματα άτομα εδώ και να αντιστοιχίζει τις ομάδες του στους ρόλους σας.',
    'let_your_provider_create_and_deactivate_people_here_on_7db65233' => 'Επιτρέψτε στον πάροχό σας να δημιουργεί και να απενεργοποιεί αυτόματα λογαριασμούς χρηστών εδώ, ώστε όποιος αποχωρεί να χάνει την πρόσβαση παντού χωρίς αίτημα υποστήριξης.',
