    'paste_the_full_service_account_json_key_it_m_9ffc8f83' => 'Επικολλήστε ολόκληρο το κλειδί JSON του λογαριασμού υπηρεσίας — πρέπει να περιέχει client_email και private_key.',
    'pick_your_framework_and_get_an_app_with_a_localhost_red_70977d3d' => 'Επιλέξτε το πλαίσιο ανάπτυξης και αποκτήστε εφαρμογή με ανακατεύθυνση στο localhost, ενότητα .env και εντολή εγκατάστασης — σε περίπου ένα λεπτό.',
    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Κάθε σελίδα που ανοίγετε από τώρα — οργανισμοί, χρήση και στοιχεία οργανισμού — διαβάζει εκείνο το περιβάλλον αντί για το τρέχον. Κανένα από τα δύο δεν αλλάζει.',
    'everyone_in_this_organization_is_refused_at_every_door_40e035a5' => 'Όλα τα άτομα αυτού του οργανισμού χάνουν αμέσως πρόσβαση από κάθε οδό και ο οργανισμός εξαφανίζεται από όλες τις λίστες. Αυτό δεν αναιρείται από την κονσόλα.',
    'everything_on_this_page_is_also_a_rest_endpoint_an_mcp_28d51f03' => 'Όλα σε αυτήν τη σελίδα είναι επίσης διαθέσιμα ως REST endpoint, εργαλείο MCP και εντολή CLI, με τους ίδιους κανόνες και ιστορικό ελέγχου.',
    'give_it_a_name_you_will_recognise_later_like_3cdadec6' => 'Δώστε όνομα που θα αναγνωρίσετε αργότερα, όπως τη συσκευή ή τον διαχειριστή κωδικών όπου είναι αποθηκευμένο. Μπορείτε να το αλλάξετε οποτεδήποτε.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Παραχωρήστε ρόλο στα άτομα που υποστηρίζουν ή λειτουργούν τις εφαρμογές σας. Ο ρόλος συγκεκριμένης εφαρμογής περιλαμβάνεται μόνο στα token της· ο ρόλος για όλες τις εφαρμογές στα token καθεμιάς.',
    'groups_appear_here_after_the_first_sync_that_includes_t_d8006c0f' => 'Οι ομάδες εμφανίζονται εδώ μετά τον πρώτο συγχρονισμό που τις περιλαμβάνει. Αν ο πάροχος φιλτράρει ποιες ομάδες στέλνει, η λίστα αντανακλά αυτό το φίλτρο.',
    'recognise_your_devices_by_their_browser_ip_address_and_eb8587ae' => 'Αναγνωρίστε τις συσκευές σας από το πρόγραμμα περιήγησης, τη διεύθυνση IP και τη δραστηριότητα. Η χώρα είναι κατά προσέγγιση και βασίζεται στην καταγεγραμμένη IP.',
    'removes_every_connection_through_it_tokens_are_revoked_eec0a79e' => 'Αφαιρεί κάθε σύνδεση μέσω αυτού. Τα διακριτικά ανακαλούνται εδώ, όχι στον πάροχο — αποσυνδέστε πρώτα τα άτομα, αν αυτό έχει σημασία.',
