    'its_people_are_refused_at_every_door_sign_in_the_device_5c2c7648' => 'Τα άτομα χάνουν πρόσβαση από κάθε οδό — σύνδεση, ροή συσκευής και οθόνη συγκατάθεσης — μέχρι την επανενεργοποίηση. Δεν διαγράφεται τίποτα.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Κλειδιά που δημιούργησαν τα άτομα αυτού του οργανισμού για τις εφαρμογές του, με τα δικαιώματα καθενός. Κάθε άτομο δημιουργεί τα δικά του· ανακαλέστε όσα διέρρευσαν ή δεν χρησιμοποιούνται.',
    'keys_your_own_scripts_and_integrations_use_to_call_an_a_db6b0585' => 'Κλειδιά που τα script και οι ενσωματώσεις σας χρησιμοποιούν για να καλούν το API εφαρμογής εκ μέρους σας. Ένα κλειδί μπορεί να κάνει μόνο ό,τι επιτρέπεται σε εσάς στην εφαρμογή.',
    'nobody_is_on_this_organization_it_has_no_owner_so_nobod_0a51d66d' => 'Δεν υπάρχει κανείς σε αυτόν τον οργανισμό, ούτε ιδιοκτήτης, άρα κανείς δεν μπορεί να συνδεθεί για να τον διαχειριστεί. Πρόκειται για αποτυχία αρχικής δημιουργίας που χρειάζεται διερεύνηση, όχι απλώς για κενή λίστα.',
    'send_their_it_administrator_an_admin_portal_link_for_sa_59852a2e' => 'Στείλτε στον διαχειριστή IT σύνδεσμο της Πύλης διαχείρισης για ανανέωση πιστοποιητικού SAML ή προετοιμάστε το νέο πιστοποιητικό μέσω API.',
    'session_ceiling_with_idle' => 'Η εγκατάσταση επιτρέπει το πολύ :idle χωρίς δραστηριότητα και :absolute συνολικά (CBOX_ID_SESSION_IDLE_MINUTES, CBOX_ID_SESSION_TTL_MINUTES).',
    'session_with_idle' => 'Μια συνεδρία λήγει μετά από :idle χωρίς δραστηριότητα ή το αργότερο μετά από :absolute.',
    'showing_this_environment_s_own_secrets_an_organization_d072355c' => 'Εμφανίζονται τα μυστικά αυτού του περιβάλλοντος. Τα μυστικά ενός οργανισμού διατηρούνται χωριστά, στη σελίδα του. Επιλέξτε τον με το φίλτρο Οργανισμός.',
    'social_providers_owned' => ':providers — ιδιόκτητες ρυθμίσεις του οργανισμού :organization: :count· οι υπόλοιπες προέρχονται από το περιβάλλον.',
