    'that_favicon_cannot_be_used_keep_it_under_pixels_pixels_43e8b882' => 'Αυτό το εικονίδιο ιστοτόπου δεν μπορεί να χρησιμοποιηθεί. Η μεγαλύτερη πλευρά του πρέπει να είναι κάτω από :pixels εικονοστοιχεία.',
    'that_logo_cannot_be_used_keep_it_under_pixels_pixels_on_4e195f5d' => 'Αυτό το λογότυπο δεν μπορεί να χρησιμοποιηθεί. Η μεγαλύτερη πλευρά του πρέπει να είναι κάτω από :pixels εικονοστοιχεία.',
    'the_account_s_last_successful_sign_in_was_too_far_away_e6d46632' => 'Η τελευταία επιτυχής σύνδεση στον λογαριασμό ήταν πολύ μακριά και πολύ πρόσφατη για να είναι εφικτό το ταξίδι από εκεί. Απαιτούνται πληροφορίες IP.',
    'the_address_belongs_to_a_hosting_provider_or_data_centr_213f7032' => 'Η διεύθυνση ανήκει σε πάροχο φιλοξενίας ή κέντρο δεδομένων, από όπου οι άνθρωποι σπάνια συνδέονται. Απαιτείται υπηρεσία πληροφοριών IP που το αναφέρει.',
    'the_admin_console_s_own_palette_as_hex_0a2540_or_oklch_71ec4917' => 'Η παλέτα της κονσόλας διαχείρισης, σε δεκαεξαδική μορφή (#0a2540) ή oklch(…). Η σελίδα σύνδεσης χρησιμοποιεί τα χρώματα του παραπάνω θέματος.',
    'the_current_signing_secret_stops_verifying_immediately_54edeb63' => 'Το τρέχον μυστικό υπογραφής παύει αμέσως να επαληθεύει υπογραφές και δεν ανακτάται. Ο παραλήπτης απορρίπτει κάθε παράδοση μέχρι να ενημερωθεί.',
    'the_risk_score_reached_its_reject_threshold_ip_reputati_e04e768d' => 'Η βαθμολογία κινδύνου έφτασε το όριο απόρριψης (φήμη IP, honeypot, user agent, MX και τα υπόλοιπα βαθμολογούμενα σήματα).',
