    'nothing_is_always_refused_and_nothing_skips_the_rules_d_6699d9d9' => 'Καμία διεύθυνση δεν αποκλείεται πάντα και καμία δεν παρακάμπτει τους κανόνες. Αποκλείστε εύρος διευθύνσεων από το οποίο είδατε επιθέσεις ή επιτρέψτε στο δίκτυο του γραφείου να παρακάμπτει τους κανόνες συχνότητας.',
    'one_marked_event_siem_stream_test_sent_now_with_this_st_c0cf0c4a' => 'Ένα επισημασμένο συμβάν (siem.stream.test), αποστελλόμενο τώρα με τις ρυθμίσεις και το διαπιστευτήριο της ροής, χωρίς ουρά ή επαναλήψεις. Η επιτυχία καταργεί επίσης την κατάσταση «Απαιτείται ενέργεια».',
    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Μόνο ενεργά μέλη του επιλεγμένου οργανισμού μπορούν να συνδεθούν σε αυτήν την εφαρμογή. Όλοι οι άλλοι απορρίπτονται και η άρνηση καταγράφεται στο αρχείο ελέγχου.',
    'passkeys_are_turned_off_here_so_you_cannot_a_9b3b4401' => 'Τα κλειδιά πρόσβασης είναι απενεργοποιημένα εδώ, οπότε δεν μπορείτε να προσθέσετε ή να χρησιμοποιήσετε κάποιο για σύνδεση. Τα υπάρχοντα εμφανίζονται παρακάτω και μπορούν να αφαιρεθούν.',
    'people_who_sign_in_through_this_provider_stop_being_abl_a0fd1fd9' => 'Τα άτομα που συνδέονται μέσω αυτού του παρόχου χάνουν αυτήν τη δυνατότητα. Όποιος έχει κωδικό εδώ μπορεί ακόμη να συνδεθεί, εκτός αν απαιτείται ενιαία σύνδεση.',
    'point_cbox_id_at_the_identity_provider_your_company_alr_f4f844a5' => 'Συνδέστε το Cbox ID με τον πάροχο ταυτότητας που χρησιμοποιεί ήδη η εταιρεία σας. Η ρύθμιση ξεκινά ως προσχέδιο· τίποτα δεν αλλάζει μέχρι να την ενεργοποιήσετε.',
    'the_token_your_identity_provider_currently_holds_stops_5458b580' => 'Το token που χρησιμοποιεί τώρα ο πάροχος ταυτότητας σταματά αμέσως να λειτουργεί. Η αυτόματη διαχείριση λογαριασμών αποτυγχάνει μέχρι να επικολλήσετε εκεί το νέο token.',
    'this_connection_belongs_to_the_environment_not_to_one_o_5e9a5366' => 'Αυτή η σύνδεση ανήκει στο περιβάλλον, όχι σε έναν οργανισμό. Ορίστε την υποχρεωτική χρήση στην Πολιτική ελέγχου ταυτότητας.',
    'this_connection_can_t_be_changed_while_the_organization_d78c4f4e' => 'Αυτή η σύνδεση δεν αλλάζει όσο ο οργανισμός δεν έχει το πρόγραμμα Enterprise. Επικοινωνήστε με την ομάδα διαχείρισης του λογαριασμού σας για ενεργοποίηση.',
    'this_connection_s_settings_could_not_be_read_so_nothing_0ab248ca' => 'Δεν ήταν δυνατή η ανάγνωση των ρυθμίσεων αυτής της σύνδεσης, οπότε δεν άλλαξε τίποτα. Εισαγάγετε πρώτα ξανά τις ρυθμίσεις του παρόχου ταυτότητας.',
    'this_endpoint_belongs_to_the_environment_and_receives_e_f1dc8df9' => 'Αυτό το endpoint ανήκει στο περιβάλλον και λαμβάνει τα συμβάντα κάθε οργανισμού, μαζί με τα δικά σας. Το διαχειρίζεται ο υπεύθυνος λειτουργίας.',
    'this_organization_s_brand_it_overrides_the_environment_ffdddbcc' => 'Η οπτική ταυτότητα αυτού του οργανισμού αντικαθιστά την προεπιλογή του περιβάλλοντος. Οι αλλαγές εμφανίζονται ζωντανά στην προεπισκόπηση και εφαρμόζονται στη φιλοξενούμενη σελίδα σύνδεσης.',
    'this_provider_s_discovery_document_publishes_no_signing_07a38178' => 'Το έγγραφο ανακάλυψης αυτού του παρόχου δεν δημοσιεύει κλειδιά υπογραφής (jwks_uri). Επικολλήστε το κλειδί υπογραφής των διακριτικών ID του (δημόσιο κλειδί PEM).',
    'verify_the_domain_before_turning_capture_on_until_then_4ff9f310' => 'Επαληθεύστε τον τομέα πριν ενεργοποιήσετε την υποχρεωτική δρομολόγηση προς SSO. Μέχρι τότε, ο οργανισμός δεν έχει αποδείξει ότι του ανήκουν αυτές οι διευθύνσεις.',
    'verify_the_signature_on_every_call_and_answer_within_th_5219ed81' => 'Επαληθεύετε την υπογραφή σε κάθε κλήση και απαντάτε εντός του χρονικού ορίου — αυτό εκτελείται όσο κάποιος περιμένει στην οθόνη σύνδεσης.',
    'webhook_id_webhook_timestamp_and_webhook_signature_with_73e511b0' => 'webhook-id, webhook-timestamp και webhook-signature, με μυστικό whsec_, που επαληθεύονται από οποιαδήποτε βιβλιοθήκη Standard Webhooks.',
    'social_provider_enabled_environment' => 'Ο πάροχος :provider είναι πλέον διαθέσιμος σε κάθε σελίδα σύνδεσης αυτού του περιβάλλοντος.',
