    'they_lose_this_role_in_every_organization_at_once_apps_2750f7e3' => 'Το άτομο χάνει αυτόν τον ρόλο σε όλους τους οργανισμούς ταυτόχρονα. Οι έλεγχοι εξουσιοδότησης σε πραγματικό χρόνο εφαρμόζουν την αλλαγή στην επόμενη προστατευμένη ενέργεια· οι πληροφορίες των υπαρχόντων token αποτυπώνουν την κατάσταση κατά την έκδοση. Κανείς δεν αποσυνδέεται.',
    'they_lose_this_role_in_every_organization_at_once_apps_39477fda' => 'Το άτομο χάνει αυτόν τον ρόλο σε όλους τους οργανισμούς ταυτόχρονα. Οι έλεγχοι εξουσιοδότησης σε πραγματικό χρόνο εφαρμόζουν την αλλαγή στην επόμενη προστατευμένη ενέργεια· οι πληροφορίες των υπαρχόντων token αποτυπώνουν την κατάσταση κατά την έκδοση. Κανείς δεν αποσυνδέεται.',
    'whether_the_background_work_of_this_install_webhooks_si_0647da12' => 'Ελέγξτε αν οι εργασίες παρασκηνίου αυτής της εγκατάστασης — webhooks, ειδοποιήσεις αποσύνδεσης σε εφαρμογές και email στην ουρά — αποστέλλονται πράγματι.',
    'your_endpoints_get_a_signed_message_after_something_hap_04723db4' => 'Τα endpoint σας λαμβάνουν υπογεγραμμένο μήνυμα μετά από συμβάν, ώστε τα συστήματά σας να αντιδρούν χωρίς συνεχόμενα ερωτήματα.',
    'your_organization_s_name_domains_and_defaults_changes_h_8e3220c0' => 'Το όνομα, οι τομείς και οι προεπιλογές του οργανισμού σας. Οι αλλαγές ισχύουν για κάθε άτομο που συνδέεται μέσω αυτού του οργανισμού.',
