    'your_own_credentials_with_each_provider_offered_to_ever_d1715d1a' => 'Τα δικά σας διαπιστευτήρια σε κάθε πάροχο, διαθέσιμα σε όλους σε αυτό το περιβάλλον. Κάθε οργανισμός τα κληρονομεί.',
    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'Ο παραλήπτης διατηρεί το ίδιο μυστικό και το χρησιμοποιεί ακριβώς όπως γράφεται, μαζί με το πρόθεμα whsec_, ως κλειδί HMAC για το X-Cbox-Signature.',
