    'prove_which_email_domains_your_organization_owns_a_veri_a1717fad' => 'Επαληθεύστε ποιοι τομείς email ανήκουν στον οργανισμό σας. Ένας επαληθευμένος τομέας μπορεί να κατευθύνει όλα τα άτομα με διεύθυνση σε αυτόν απευθείας στην εταιρική σύνδεση SSO.',
    'push_your_people_into_the_apps_that_need_their_own_copy_249f03c2' => 'Στείλτε τα στοιχεία των ατόμων στις εφαρμογές που χρειάζονται δικό τους αντίγραφο. Ένα endpoint SCIM λαμβάνει κάθε προσθήκη, αλλαγή και αποχώρηση όταν συμβαίνει.',
    'send_this_single_use_link_to_whoever_configures_your_id_e8056999' => 'Στείλτε αυτόν τον σύνδεσμο μίας χρήσης στο άτομο που ρυθμίζει τον πάροχο ταυτότητας. Λήγει σύντομα και λειτουργεί χωρίς λογαριασμό. Αντιγράψτε τον τώρα: εμφανίζεται μόνο μία φορά.',
    'shown_above_the_sign_in_form_and_in_emails_png_jpeg_or_a92637fe' => 'Εμφανίζεται πάνω από τη φόρμα σύνδεσης και στα email. PNG, JPEG ή WebP, έως 1 MB. Μια πλατιά εικόνα ύψους περίπου 36 px αποδίδεται καλύτερα.',
    'signed_in_to_an_app_as_one_of_this_organization_s_peopl_d9c070c7' => 'Ενεργές συνεδρίες εφαρμογών εκ μέρους ατόμων αυτού του οργανισμού. Καθεμιά εμφανίζεται και στο αρχείο καταγραφής ελέγχου του οργανισμού, μαζί με τον λόγο.',
    'splunk_elastic_graylog_cef_and_generic_json_are_http_co_8d405816' => 'Τα Splunk, Elastic, Graylog, CEF και Generic JSON είναι συλλέκτες HTTP στους οποίους δίνετε URL. Τα Datadog, Amazon S3 και Google Cloud Storage χρησιμοποιούν δικές τους ρυθμίσεις.',
