    'the_environment_default_inherited_by_every_organization_19ddab20' => 'Η προεπιλεγμένη οπτική ταυτότητα του περιβάλλοντος, που κληρονομούν οι οργανισμοί χωρίς δική τους. Η ταυτότητα κάθε οργανισμού βρίσκεται στη σελίδα του, στην καρτέλα Οπτική ταυτότητα.',
    'the_site_your_account_lives_on_the_domain_of_the_datado_7f128cbf' => 'Η τοποθεσία που φιλοξενεί τον λογαριασμό σας: ο τομέας του URL Datadog όπου συνδέεστε. Ένα κλειδί API λειτουργεί μόνο στη δική του τοποθεσία.',
    'a_management_key_reads_and_writes_this_envir_aba5f345' => 'Ένα κλειδί διαχείρισης διαβάζει και τροποποιεί τους οργανισμούς και τα άτομα αυτού του περιβάλλοντος μέσω του API, και η τιμή του εμφανίζεται μία φορά.',
    'each_sign_out_uri_must_use_https_http_is_all_b9c71673' => 'Κάθε URI αποσύνδεσης πρέπει να χρησιμοποιεί https (το http επιτρέπεται μόνο στο localhost) — π.χ. https://app.example.com/signed-out.',
    'erasing_a_person_deletes_their_credentials_m_0c49a669' => 'Η διαγραφή ενός ατόμου αφαιρεί οριστικά τα διαπιστευτήρια, τις συμμετοχές και τα προσωπικά δεδομένα του. Τίποτα δεν τα επαναφέρει.',
    'everything_an_admin_can_do_and_the_only_one__170b2916' => 'Ό,τι μπορεί να κάνει ένας διαχειριστής, και είναι ο μόνος που μπορεί να διαγράψει τον οργανισμό ή να τον μεταβιβάσει.',
    'label_hint_and_error_are_wired_by_the_field__1b04abf6' => 'Η ετικέτα, η υπόδειξη και το σφάλμα συνδέονται από το Field, ποτέ από το σημείο κλήσης.',
    'marking_this_address_verified_lets_it_be_use_1e335bd1' => 'Ο χαρακτηρισμός αυτής της διεύθυνσης ως επαληθευμένης επιτρέπει τη χρήση της για ανάκτηση της σύνδεσης αυτού του χρήστη.',
    'no_project_so_no_organization_owns_it_and_no_36fcb1c6' => 'Δεν υπάρχει έργο, άρα δεν ανήκει σε κανέναν οργανισμό και τίποτα εδώ δεν είναι προϊόν κάποιου.',
    'only_an_environment_administrator_may_change_761a9768' => 'Μόνο ένας διαχειριστής περιβάλλοντος μπορεί να αλλάξει το προεπιλεγμένο θέμα του περιβάλλοντος, στη δική του σελίδα Εταιρικής ταυτότητας.',
    're_keying_this_endpoint_issues_a_new_signing_a32492f8' => 'Η αλλαγή κλειδιού αυτού του τελικού σημείου εκδίδει νέο μυστικό υπογραφής· οι παραδόσεις που έχουν υπογραφεί με το παλιό δεν επαληθεύονται πλέον.',
    'registering_a_hook_issues_a_signing_secret_a_28ea49a1' => 'Η καταχώριση ενός hook εκδίδει μυστικό υπογραφής και εντάσσει το τελικό σημείο σας στη διαδικασία σύνδεσης.',
    'registering_an_endpoint_issues_a_signing_sec_d3094c17' => 'Η καταχώριση ενός τελικού σημείου δημιουργεί μυστικό υπογραφής και ξεκινά την αποστολή συμβάντων σε αυτό σε πραγματικό χρόνο.',
    'removing_this_phone_number_may_leave_the_use_76d23e13' => 'Η αφαίρεση αυτού του αριθμού τηλεφώνου μπορεί να αφήσει τον χρήστη προστατευμένο μόνο από τον κωδικό πρόσβασής του.',
    'revoking_a_secret_stops_it_working_immediate_0f24d7b4' => 'Η ανάκληση ενός μυστικού το απενεργοποιεί αμέσως — οτιδήποτε εξακολουθεί να το χρησιμοποιεί αποτυγχάνει να συνδεθεί.',
    'not_in_the_cbox_cli_yet_this_is_the_command__48b39c79' => 'Δεν υπάρχει ακόμη στο cbox CLI — αυτή είναι η εντολή που θα έχει.',
