    'rotating_a_management_key_mints_its_successo_3bb1cc71' => 'Η αντικατάσταση ενός κλειδιού διαχείρισης δημιουργεί νέο κλειδί, του οποίου η τιμή εμφανίζεται μόνο μία φορά.',
    'rotating_this_app_s_secret_creates_a_new_one_c5772a3d' => 'Η αντικατάσταση του μυστικού αυτής της εφαρμογής δημιουργεί νέο μυστικό. Το τρέχον παύει να λειτουργεί αμέσως.',
    'rotating_this_directory_s_bearer_token_stops_5f1d734c' => 'Η αντικατάσταση του διακριτικού bearer αυτού του καταλόγου ακυρώνει εκείνο που έχει ο πάροχος ταυτότητάς σας, μέχρι να επικολλήσετε εκεί το νέο.',
    'setting_a_password_replaces_this_person_s_cr_d729ce98' => 'Ο ορισμός κωδικού πρόσβασης αντικαθιστά το διαπιστευτήριο αυτού του ατόμου· με την επιλογή «αποκάλυψη» εμφανίζεται.',
    'signing_in_to_an_app_as_this_person_lets_you_11b85bdb' => 'Η σύνδεση σε μια εφαρμογή ως αυτό το άτομο σας επιτρέπει να ενεργείτε εκ μέρους του εκεί.',
