    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Προσφέρονται μόνο οι ενέργειες που μπορείτε να κάνετε εσείς στην εφαρμογή :part1. Αν αργότερα χάσετε κάποιο δικαίωμα, το χάνει και το κλειδί.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'Το πεδίο πρόσβασης «:part1» αφαιρέθηκε. Οι εφαρμογές που το είχαν το διατηρούν ως χειροκίνητα καταχωρισμένο πεδίο, το οποίο δεν δίνει πλέον πρόσβαση σε αυτό το API.',
    'feature_flag_part1_deleted_apps_asking_for_it_now_get_o_bf0ceaac' => 'Η σημαία λειτουργίας «:part1» διαγράφηκε. Οι εφαρμογές που τη ζητούν λαμβάνουν πλέον ανενεργή κατάσταση.',
    'feature_flag_part1_created_it_is_off_for_everyone_until_32603be3' => 'Η σημαία λειτουργίας «:part1» δημιουργήθηκε. Είναι ανενεργή για όλους μέχρι να την ενεργοποιήσει κάποιος από τους παρακάτω κανόνες ή η προεπιλεγμένη τιμή της.',
    'this_browser_cannot_create_a_passkey_so_ther_2fac1ac0' => 'Αυτό το πρόγραμμα περιήγησης δεν μπορεί να δημιουργήσει κλειδί πρόσβασης, οπότε δεν μπορείτε να προσθέσετε νέο εδώ. Τα υπάρχοντα εμφανίζονται παρακάτω και μπορούν να αφαιρεθούν.',
    'this_destroys_the_user_s_enrolled_second_factor_and_the_288206be' => 'Αυτό διαγράφει τον καταχωρισμένο δεύτερο παράγοντα του χρήστη και τους κωδικούς ανάκτησης. Μέχρι να εγγραφεί ξανά, ο λογαριασμός προστατεύεται μόνο από τον κωδικό πρόσβασης.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Αυτό το endpoint ανήκει στο περιβάλλον και εκτελείται για κάθε οργανισμό του. Εμφανίζεται εδώ επειδή συμμετέχει στις συνδέσεις σας· το διαχειρίζεται ο υπεύθυνος λειτουργίας.',
    'valid_once_and_short_lived_turn_this_off_only_if_you_ar_521114e3' => 'Ισχύει μία φορά και για λίγο. Απενεργοποιήστε μόνο αν δημιουργείτε τον λογαριασμό εκ των προτέρων και θα στείλετε μόνοι σας τον σύνδεσμο.',
    'webhook_subscribed_events_count' => 'Συμβάντα για τα οποία λαμβάνονται ειδοποιήσεις: :count',
    'sms_enabled_country_count' => 'Οι κωδικοί μέσω SMS είναι ενεργοί. Επιτρεπόμενες χώρες: :count.',
    'that_code_did_not_match_or_it_has_expired_tr_b6366c59' => 'Αυτός ο κωδικός δεν ταιριάζει ή έχει λήξει. Δοκιμάστε ξανά ή στείλτε νέο.',
    'the_current_secret_stops_working_immediately_a6493eff' => 'Το τρέχον μυστικό παύει αμέσως να λειτουργεί. Οτιδήποτε εξακολουθεί να επαληθεύει με αυτό θα αρχίσει να απορρίπτει τις παραδόσεις.',
    'the_environment_this_deployment_itself_runs__4fdb5a7a' => 'Το περιβάλλον στο οποίο λειτουργεί η ίδια η εγκατάσταση — εδώ συνδέονται οι υπεύθυνοι λειτουργίας και οι ομάδες των οργανισμών. Δεν ανήκει σε κανέναν οργανισμό.',
    'the_export_disk_must_be_storage_every_web_an_2d6bfbff' => 'Ο δίσκος εξαγωγής πρέπει να είναι κοινόχρηστος αποθηκευτικός χώρος για όλες τις διεργασίες web και εργασιών· εκτελέστε `php artisan cbox-id:doctor`.',
