    'risk_score_part1_part2_recorded_under_part3_part4_ae0bca2b' => 'Βαθμολογία κινδύνου: :part1 (:part2) · λειτουργία κατά την καταγραφή: :part3 :part4',
    'what_a_person_may_do_in_an_organization_assi_3fc83055' => 'Τι επιτρέπεται να κάνει ένα άτομο σε έναν οργανισμό. Ανατίθεται ανά μέλος· η εφαρμογή σας ελέγχει τα τρέχοντα δικαιώματα πριν από προστατευμένες ενέργειες.',
    'what_an_organization_has_paid_for_set_by_bil_fc59c3a4' => 'Τι μπορεί να χρησιμοποιεί ένας οργανισμός βάσει του προγράμματός του ή ρητών παραχωρήσεων. Η διαχείριση γίνεται στο Billing· η εφαρμογή σας ελέγχει τα τρέχοντα δικαιώματα παροχών.',
    'use_2_to_16_lowercase_letters_or_digits_star_cda1343d' => 'Χρησιμοποιήστε 2 έως 16 πεζά γράμματα ή ψηφία, ξεκινώντας με γράμμα, και έπειτα _live ή _test — για παράδειγμα acme_live.',
    'use_an_absolute_url_with_a_host_and_no_fragm_134d4387' => 'Χρησιμοποιήστε απόλυτη διεύθυνση URL με όνομα κεντρικού υπολογιστή, χωρίς αναγνωριστικό τμήματος (fragment) και με έως 255 χαρακτήρες — για παράδειγμα https://api.example.com.',
    'we_could_not_send_the_text_message_check_the_ad67f38a' => 'Δεν ήταν δυνατή η αποστολή του SMS. Ελέγξτε τον αριθμό και δοκιμάστε ξανά.',
