    'whether_a_feature_is_switched_on_for_someone_631c0d5f' => 'Αν μια λειτουργία είναι ενεργοποιημένη για κάποιον. Σταδιακή διάθεση, όχι έλεγχος πρόσβασης — μην προστατεύετε ποτέ δεδομένα με αυτό.',
    'who_may_do_what_to_which_record_your_app_wri_ca6c6d61' => 'Ποιος μπορεί να κάνει τι σε ποια εγγραφή. Η εφαρμογή σας γράφει τις σχέσεις και ζητά έλεγχο σε κάθε αίτημα.',
    'organization_created_but_the_owner_could_not_21800822' => 'Ο οργανισμός δημιουργήθηκε, αλλά δεν ήταν δυνατή η αποστολή συνδέσμου στον ιδιοκτήτη. Ζητήστε του να χρησιμοποιήσει το «Ξέχασα τον κωδικό πρόσβασης».',
    'you_re_signed_in_you_don_t_belong_to_an_orga_67d0efb9' => 'Έχετε συνδεθεί. Δεν ανήκετε ακόμη σε οργανισμό εδώ — ο λογαριασμός και οι ρυθμίσεις ασφαλείας σας είναι αποκλειστικά δικά σας.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Χρειάζεστε διαπιστευτήρια από τον δικό σας λογαριασμό στον πάροχο, συνήθως ID και μυστικό πελάτη. Η Apple εκδίδει κλειδί υπογραφής αντί για μυστικό.',
