    'see_your_apps_83cc472a' => 'δείτε τις εφαρμογές σας',
    'the_full_quickstart_dd59dd4d' => 'τον πλήρη οδηγό γρήγορης εκκίνησης',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Ένα κλειδί διαχείρισης ενεργεί μόνο στο δικό του περιβάλλον. Εξαγάγετε το πρότυπο αυτής της εφαρμογής (GET /apps/{id}/blueprint) και καταχωρίστε το με το κλειδί του άλλου περιβάλλοντος (POST /apps με `blueprint`).',
    'add_the_domain_and_publish_the_txt_record_it_shows_or_s_ddb14174' => 'Προσθέστε τον τομέα και δημοσιεύστε την εγγραφή TXT που εμφανίζεται — ή στείλτε στον διαχειριστή IT του οργανισμού έναν σύνδεσμο προς την Πύλη Διαχείρισης για να το κάνει.',
    'asked_before_every_rule_a_deny_entry_blocks_an_allow_en_e80b3f61' => 'Ελέγχεται πριν από κάθε κανόνα. Μια εγγραφή άρνησης αποκλείει· μια εγγραφή άδειας παρακάμπτει όλους τους κανόνες, συμπεριλαμβανομένων των ενσωματωμένων. Αν ισχύουν και οι δύο στην ίδια προσπάθεια, υπερισχύει η άρνηση.',
    'attach_this_to_the_iam_user_whose_access_key_the_stream_7659ba28' => 'Επισυνάψτε το στον χρήστη IAM του οποίου το κλειδί πρόσβασης χρησιμοποιεί η ροή: μπορεί να γράφει αντικείμενα κάτω από το πρόθεμα και τίποτε άλλο — χωρίς ανάγνωση, απαρίθμηση ή διαγραφή.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Επιλέξτε SCIM αν ο πάροχός σας στέλνει δεδομένα σε εμάς, Google Workspace ή Entra αν πρέπει να τα ανακτούμε εμείς, ή το σύστημα ανθρώπινου δυναμικού σας — Workday, BambooHR, Rippling, HiBob ή Personio — ώστε τα άτομα να προστίθενται την ημερομηνία έναρξης.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Από την επόμενη προσπάθεια, οι αποκλεισμοί απορρίπτουν συνδέσεις και εγγραφές σε αυτό το περιβάλλον, ενώ οι πρόσθετοι έλεγχοι απαιτούν επαλήθευση. Αν ένας κανόνας είναι λανθασμένος, πραγματικά άτομα αποκλείονται.',
    'give_it_the_endpoint_or_bucket_and_the_credential_it_ex_4cf81bb7' => 'Δώστε το τελικό σημείο ή τον κάδο και το διαπιστευτήριο που αναμένει· για συλλέκτη HTTP, αφήστε το μυστικό κενό ώστε να δημιουργηθεί κλειδί HMAC.',
    'let_an_organization_sign_in_with_okta_entra_id_or_googl_cf114dfb' => 'Επιτρέψτε σε έναν οργανισμό να συνδέεται με Okta, Entra ID ή Google Workspace — ή στείλτε στον διαχειριστή του έναν σύνδεσμο προς την Πύλη Διαχείρισης για να το ρυθμίσει μόνος του.',
    'selected_permissions_count' => 'Επιλεγμένα δικαιώματα: :count',
    'sso_required_organization' => 'Το εταιρικό SSO είναι υποχρεωτικό για τον οργανισμό :organization. Όλοι οι άλλοι τρόποι σύνδεσης αποκλείονται μέχρι να αλλάξει αυτή η απαίτηση στην ενότητα «:policy».',
    'sso_required_environment' => 'Το εταιρικό SSO είναι υποχρεωτικό για αυτό το περιβάλλον. Όλοι οι άλλοι τρόποι σύνδεσης αποκλείονται μέχρι να αλλάξει αυτή η απαίτηση στην ενότητα «:policy».',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Για όποιον :part1, το αίτημα σύνδεσης δεν αποστέλλεται ποτέ στο παλιό σύστημα. Ισχύει ο κωδικός πρόσβασης του Cbox ID και το παλιό σύστημα δεν συμμετέχει στον έλεγχο ταυτότητας.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Αν αυτό το τελικό σημείο είναι :part1, τα άτομα που δεν έχουν μεταφερθεί δεν μπορούν να συνδεθούν. Όσοι έχουν ήδη μεταφερθεί δεν επηρεάζονται.',
    'every_session_in_this_organization_ends_part1_part2_b33262fc' => 'Όλες οι συνεδρίες σε αυτόν τον οργανισμό τερματίζονται — :part1 :part2.',
    'the_same_code_step_by_step_with_sign_out_part1_part2_4d2f071e' => 'Ο ίδιος κώδικας, βήμα προς βήμα, με αποσύνδεση — δείτε :part1 :part2.',
    'the_newest_entries_on_part1_s_trail_dac97d7d' => 'Οι πιο πρόσφατες εγγραφές στο αρχείο ελέγχου του οργανισμού :part1.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => 'Το :part1 αρνείται τη σύνδεση αν η τιμή δεν ταιριάζει ακριβώς. Έχει δεσμευτεί για αυτήν τη ρύθμιση, ώστε να την επικολλήσετε τώρα στο :part2 και να αποθηκεύσετε εδώ αργότερα.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 — οι συνεδρίες, τα κλειδιά πρόσβασης, οι δεύτεροι παράγοντες, τα προφίλ παρόχων ταυτότητας, τα δεδομένα καταλόγων, τα εκδοθέντα token, οι αναθέσεις ρόλων και το ιστορικό ελέγχου παραμένουν. Το άτομο μπορεί να επανενεργοποιηθεί.',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => 'Προτεινόμενα βήματα: :part1, περίπου με αυτήν τη σειρά. Κάθε βήμα σημειώνεται αυτόματα όταν έχει πραγματικά ολοκληρωθεί· δεν χρειάζεται χειροκίνητη επισήμανση.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Αυτές οι μέθοδοι δεν χρησιμοποιούνται για σύνδεση σε αυτήν την κονσόλα. Οι διαχειριστές συνδέονται μέσω Cbox ID στο :part2, με τις μεθόδους σύνδεσης εκείνου του συστήματος.',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Κλειδί διαχείρισης για έναν πράκτορα. Επιτρέπει μόνο όσα ορίζουν τα πεδία πρόσβασής του, ενώ οι ενέργειες που επιλέγετε περιμένουν την έγκρισή σας στο τηλέφωνο ή εδώ: :part1.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => 'Το :part1 είναι ο πάροχος ταυτότητας ενός προϊόντος, που χρεώνεται με δικό του πρόγραμμα. Περιλαμβάνει απομονωμένα :part2 :part3, παραγωγής και δοκιμών, καθένα με δικούς του χρήστες, κλειδιά και σύνδεση.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'Ένα κλειδί οργανισμού δίνει πρόσβαση στον ίδιο τον χώρο — έργα, περιβάλλοντα, ομάδα και κλειδιά — όχι στο εσωτερικό περιβάλλοντος. Δημιουργήστε το στο ανώτατο επίπεδο της πλατφόρμας, στο :part1 :part2 :part3.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Εφαρμογές που εμπιστεύονται αυτό το περιβάλλον ως πάροχο ταυτότητας SAML. Για σύνδεση με ήδη υπάρχοντες λογαριασμούς άλλων υπηρεσιών, χρησιμοποιήστε :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Οι εγκρίσεις καλύπτουν τις ενέργειες του API διαχείρισης. Αυτά τα πεδία πρόσβασης εξυπηρετούνται από endpoint που δεν είναι ακόμη ενέργειες, οπότε εκτελούνται χωρίς αίτημα έγκρισης: :part1 :part2.',
    'link_an_app_with_the_same_owner_as_the_api_tokens_for_t_0a546071' => 'Συνδέστε μια εφαρμογή με τον ίδιο ιδιοκτήτη με το API. Τα διακριτικά για αυτό το API περιέχουν τους ρόλους και τα δικαιώματα της συνδεδεμένης εφαρμογής, επομένως πρέπει να είναι εφαρμογή του ίδιου ιδιοκτήτη.',
    'not_configured_radar_can_still_block_but_cannot_ask_a_p_0a163809' => 'Δεν έχει διαμορφωθεί — το Radar μπορεί ακόμη να αποκλείει, αλλά δεν μπορεί να ζητήσει από κάποιον να αποδείξει ότι είναι άνθρωπος. Μια επισημασμένη εγγραφή επιβεβαιώνει αντ’ αυτού τη διεύθυνση email της.',
    'pick_where_the_trail_goes_splunk_elastic_graylog_cef_or_e69f3c8f' => 'Επιλέξτε πού θα πηγαίνει το ίχνος ελέγχου — Splunk, Elastic, Graylog, CEF ή οποιονδήποτε συλλέκτη JSON, Datadog, ή δικό σας κάδο Amazon S3 ή Google Cloud Storage.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Τοποθετεί τα κλειδιά των διακοπτών λειτουργιών που είναι ενεργοί για το άτομο στον οργανισμό στον οποίο συνδέθηκε, στο διακριτικό πρόσβασης, στο διακριτικό ID και στο UserInfo ως πεδίο `feature_flags`.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Τοποθετεί τους ΡΟΛΟΥΣ του ατόμου στο ID token με το όνομα `groups` — αυτό αναζητούν Kubernetes, Grafana, Vault και τα περισσότερα παλαιότερα SaaS. Δεν υπάρχει κάτι που λέγεται ομάδα σε αυτήν την κονσόλα: δημιουργήστε έναν Ρόλο με το όνομα που αναμένει η εφαρμογή και θα εμφανιστεί εδώ.',
    'register_an_app_so_your_people_can_sign_in_to_it_with_t_9fcc62a6' => 'Καταχωρίστε μια εφαρμογή ώστε οι χρήστες σας να συνδέονται σε αυτήν με τον λογαριασμό που έχουν εδώ. Με αυτό το βήμα αρχίζουν να χρησιμοποιούν το Cbox ID.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Αυτό το εικονίδιο ιστοτόπου δεν μπορεί να χρησιμοποιηθεί. Στείλτε την ίδια την εικόνα ως base64 data: URI (data:image/png;base64,…). Δεν γίνονται δεκτές απομακρυσμένες διευθύνσεις URL εικόνων: κάθε επισκέπτης φορτώνει την εικόνα της σελίδας σύνδεσης και μια εξωτερική διεύθυνση θα αποκάλυπτε στον πάροχό της ποιοι είναι οι επισκέπτες.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Αυτό το λογότυπο δεν μπορεί να χρησιμοποιηθεί. Στείλτε την ίδια την εικόνα ως base64 data: URI (data:image/png;base64,…). Δεν γίνονται δεκτές απομακρυσμένες διευθύνσεις URL εικόνων: κάθε επισκέπτης φορτώνει την εικόνα της σελίδας σύνδεσης και μια εξωτερική διεύθυνση θα αποκάλυπτε στον πάροχό της ποιοι είναι οι επισκέπτες.',
    'the_address_is_a_tor_exit_node_a_vpn_or_an_open_proxy_t_f7fc0d8a' => 'Η διεύθυνση είναι κόμβος εξόδου Tor, VPN ή ανοικτός διαμεσολαβητής. Το Tor αναγνωρίζεται από την τοπική λίστα εξόδου· το VPN και ο διαμεσολαβητής απαιτούν υπηρεσία πληροφοριών IP που τα αναφέρει.',
    'the_button_disappears_from_every_sign_in_page_in_this_e_c817a046' => 'Το κουμπί εξαφανίζεται από κάθε σελίδα σύνδεσης αυτού του περιβάλλοντος που το κληρονομεί. Τα διαπιστευτήριά του διατηρούνται, ώστε να μπορείτε να το ενεργοποιήσετε ξανά.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Το κουμπί εξαφανίζεται από τη σελίδα σύνδεσης αυτού του οργανισμού — εκείνο του περιβάλλοντος δεν το αντικαθιστά. Τα διαπιστευτήριά του διατηρούνται, ώστε να μπορείτε να το ενεργοποιήσετε ξανά.',
    'the_console_is_pointed_at_this_environment_and_every_pa_4d2a0145' => 'Η κονσόλα στρέφεται σε αυτό το περιβάλλον και κάθε σελίδα που ανοίγετε από εδώ και πέρα διαβάζει αυτό αντί για το τρέχον. Δεν αλλάζει τίποτα σε κανένα από τα δύο.',
    'the_sign_in_page_your_people_see_is_yours_not_ours_logo_7573e3bf' => 'Η σελίδα σύνδεσης χρησιμοποιεί τη δική σας οπτική ταυτότητα: λογότυπο, χρώματα και κείμενα. Οι αλλαγές προβάλλονται ζωντανά και εφαρμόζονται στη φιλοξενούμενη σελίδα σύνδεσης αυτού του οργανισμού.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Αυτό το διαπιστευτήριο απαιτεί έγκριση ατόμου για αυτήν την ενέργεια, αλλά δεν υπάρχει καταγεγραμμένο άτομο για να τη δώσει. Εκτελέστε την από την κονσόλα ή εκδώστε κλειδί από την κονσόλα ώστε ο ιδιοκτήτης του να μπορεί να εγκρίνει.',
    'this_environment_falls_back_to_its_default_domain_every_201d6a2d' => 'Αυτό το περιβάλλον επιστρέφει στον προεπιλεγμένο τομέα του. Κάθε πελάτης συνδεδεμένος με τον τρέχοντα εκδότη, τη διεύθυνση ανακάλυψης ή τη διεύθυνση JWKS παύει να λειτουργεί μέχρι να επαναρυθμιστεί.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'Δεν ήταν δυνατή η αποστολή του email τώρα — αυτή η εγκατάσταση δεν μπορεί να επικοινωνήσει με τον διακομιστή αλληλογραφίας της. Δοκιμάστε αργότερα· ένας διαχειριστής μπορεί επίσης να επιβεβαιώσει τη διεύθυνσή σας με `php artisan cbox-id:users:confirm-email`.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Η σελίδα σύνδεσής σας φέρει το λογότυπο και τα χρώματά σας. Οι άνθρωποι πληκτρολογούν κωδικό πρόσβασης εκεί — πρέπει να μοιάζει δική σας, όχι δική μας.',
    'creating_an_app_issues_a_client_secret_shown_2840959a' => 'Η δημιουργία εφαρμογής εκδίδει μυστικό πελάτη, που εμφανίζεται μία φορά στην επόμενη οθόνη — χρησιμοποιείται για σύνδεση ως αυτή η εφαρμογή μέχρι να αντικατασταθεί.',
    'registering_an_app_issues_a_client_secret_sh_631bb9f1' => 'Η καταχώριση εφαρμογής εκδίδει μυστικό πελάτη, που εμφανίζεται μία φορά στην επόμενη οθόνη — χρησιμοποιείται για σύνδεση ως αυτή η εφαρμογή μέχρι να αντικατασταθεί.',
    'there_is_no_other_environment_in_this_projec_bfd62f34' => 'Δεν υπάρχει άλλο περιβάλλον σε αυτό το έργο που να διαχειρίζεστε. Προσθέστε ένα στο έργο ή ζητήστε πρόσβαση σε αυτό και θα εμφανιστεί εδώ.',
    'this_app_belongs_to_an_organization_and_an_o_5487ac51' => 'Αυτή η εφαρμογή ανήκει σε οργανισμό και ένας οργανισμός υπάρχει μόνο σε ένα περιβάλλον. Κατεβάστε το πρότυπό της και καταχωρίστε την εφαρμογή στο άλλο περιβάλλον, στον οργανισμό στον οποίο ανήκει εκεί.',
    'this_app_registered_itself_so_it_is_not_one__ec7cea33' => 'Αυτή η εφαρμογή καταχωρίστηκε μόνη της, επομένως δεν ανήκει στις ιδιόκτητες εφαρμογές αυτού του περιβάλλοντος. Μπορεί να καταχωριστεί με τον ίδιο τρόπο στο άλλο περιβάλλον.',
    'this_app_signs_in_with_its_own_keys_and_each_a40a0c9b' => 'Αυτή η εφαρμογή συνδέεται με δικά της κλειδιά και κάθε περιβάλλον πρέπει να έχει τα δικά του. Κατεβάστε το πρότυπό της και καταχωρίστε την εφαρμογή στο άλλο περιβάλλον με το σύνολο κλειδιών εκείνου του περιβάλλοντος.',
    'app_keys_unavailable_organization_switch' => 'Η εφαρμογή που σας έστειλε εδώ δεν προσφέρει κλειδιά API για τον οργανισμό :organization. Δοκιμάστε άλλον οργανισμό ή επικοινωνήστε με την υποστήριξη της εφαρμογής.',
    'app_keys_unavailable_organization' => 'Η εφαρμογή που σας έστειλε εδώ δεν προσφέρει κλειδιά API για τον οργανισμό :organization. Επικοινωνήστε με την υποστήριξη της εφαρμογής.',
    'app_keys_unavailable_switch' => 'Η εφαρμογή που σας έστειλε εδώ δεν προσφέρει κλειδιά API. Δοκιμάστε άλλον οργανισμό ή επικοινωνήστε με την υποστήριξη της εφαρμογής.',
    'app_keys_unavailable' => 'Η εφαρμογή που σας έστειλε εδώ δεν προσφέρει κλειδιά API. Επικοινωνήστε με την υποστήριξη της εφαρμογής.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Συνδεθείτε μία φορά στο ανώτατο επίπεδο της πλατφόρμας αντί ξεχωριστά ανά περιβάλλον. Ο πράκτορας, συνδεδεμένος εκ μέρους σας, έχει πρόσβαση στον οργανισμό, σε όλα τα περιβάλλοντά του που διαχειρίζεστε και στον λογαριασμό σας. Ένα εργαλείο περιβάλλοντος δέχεται όρισμα :part1 :part2 και το REST API κεφαλίδα :part3 που ορίζουν πού θα εκτελεστεί η ενέργεια. Μπορεί να κάνει όσα μπορείτε εσείς, μέσα στα όρια που επιτρέπετε, και κάθε κρίσιμη ενέργεια περιμένει έγκριση στη συσκευή σας.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Κάθε οργανισμός δίνει στο άτομο έναν ρόλο τύπου :part1, που ορίζει τι μπορεί να διαχειρίζεται, και οποιονδήποτε αριθμό ρόλων τύπου :part2, που ορίζουν τι μπορεί να κάνει στις εφαρμογές.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Το περιβάλλον «:part1» δημιουργήθηκε. Προσθέστε το :part2 από τις ρυθμίσεις τομέων του περιβάλλοντος για επαλήθευση μέσω DNS. Μη επαληθευμένος τομέας δεν μπορεί να είναι εκδότης του περιβάλλοντος.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'Τα περιβάλλοντα ανήκουν σε έργο και τα έργα σε :part1 :part2 :part3. Ξεκινήστε εκεί για να δείτε όλους τους πόρους του οργανισμού. Δύο τύποι εγγραφών δεν έχουν ποτέ οργανισμό: το :part4 είναι το περιβάλλον της ίδιας της εγκατάστασης, όπου βρίσκονται οι διαχειριστές της και τα άτομα των οργανισμών· ένα περιβάλλον με ένδειξη :part5 :part6 δεν έχει έργο, δεν χρεώνεται και δεν είναι προσβάσιμο από οργανισμό. Κανένα δεν είναι σφάλμα προς διόρθωση εδώ και αυτή η οθόνη δεν αλλάζει την αντιστοίχισή τους.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Όλοι οι τρόποι σύνδεσης στο :part1, η κατάστασή τους και το σημείο αλλαγής τους. Οι οργανισμοί μπορούν να κάνουν τους κανόνες αυστηρότερους: :part2 :part3.',
    'enter_it_to_turn_on_text_message_codes_1d7162aa' => 'Εισαγάγετέ τον για να ενεργοποιήσετε τους κωδικούς μέσω SMS.',
