    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'Κανείς σε αυτόν τον οργανισμό δεν έχει δημιουργήσει κλειδί για τις εφαρμογές του. Τα άτομα δημιουργούν δικά τους στην ενότητα Ο λογαριασμός μου, για εφαρμογή που ενεργοποιεί κλειδιά API μελών στις Ρυθμίσεις: :part1.',
