    'suspension_is_the_only_lever_here_and_it_is_reversible__9f87c506' => 'Η αναστολή είναι η μόνη διαθέσιμη ενέργεια εδώ και είναι αναστρέψιμη. Αυτή η οθόνη δεν διαγράφει οργανισμούς ούτε εκκαθαρίζει οριστικά τα δεδομένα τους. Η εγκατάσταση περιέχει και περιβάλλοντα χωρίς οργανισμό: το ριζικό περιβάλλον της πλατφόρμας και μη αντιστοιχισμένα περιβάλλοντα. Και τα δύο προσδιορίζονται στο :part1 :part2.',
