    'these_are_the_buttons_on_part1_how_every_organization_o_ca549807' => 'Αυτά είναι τα κουμπιά στο :part1. Μέσω αυτών, οι ιδιοκτήτες και οι διαχειριστές οργανισμών συνδέονται στο Cbox ID και επομένως στην κονσόλα κάθε περιβάλλοντος, οι διαχειριστές της οποίας έχουν λογαριασμούς Cbox ID. Καταχωρίστε σε κάθε πάροχο το URI ανακατεύθυνσης που εμφανίζεται· χρησιμοποιεί τον κεντρικό υπολογιστή :part2 :part3.',
    'these_buttons_are_for_the_people_who_sign_in_to_your_ap_580f5efd' => 'Αυτά τα κουμπιά προορίζονται για όσους συνδέονται στις εφαρμογές σας, στις σελίδες σύνδεσης του :part1 :part2. :part3',
    'this_console_is_your_organization_its_projects_team_key_15ebbd0f' => 'Αυτή η κονσόλα διαχειρίζεται τον οργανισμό σας: έργα, ομάδα, κλειδιά και χρέωση. Ο τρόπος σύνδεσης στις εφαρμογές σας, συμπεριλαμβανομένης της επιλογής :part1, ρυθμίζεται ξεχωριστά στην κονσόλα κάθε περιβάλλοντος.',
    'this_environment_s_issuer_discovery_and_jwks_are_served_06e9c844' => 'Ο εκδότης, τα μεταδεδομένα ανακάλυψης και το JWKS αυτού του περιβάλλοντος παρέχονται στο :part1 :part2. Κατευθύνετε τον κεντρικό υπολογιστή στο δικό σας ingress και τερματίστε εκεί το TLS.',
    'we_sent_a_link_to_part1_your_first_environment_your_liv_9786541d' => 'Στείλαμε έναν σύνδεσμο στο :part1. Το πρώτο σας περιβάλλον — ο πάροχος ταυτότητας παραγωγής σας, με δική του σύνδεση, χρήστες και κλειδιά υπογραφής — δημιουργείται μόλις ανοίξετε τον σύνδεσμο και επιστρέφετε κατευθείαν εδώ. Ο σύνδεσμος ισχύει για 24 ώρες.',
    'what_you_are_administering_and_the_details_your_apps_ne_23bc71ef' => 'Τι διαχειρίζεστε και ποιες πληροφορίες χρειάζονται οι εφαρμογές σας για ενσωμάτωση. :part1',
    'which_of_its_actions_wait_for_a_person_the_agent_gets_a_e72df5dd' => 'Επιλέξτε ποιες ενέργειες περιμένουν έγκριση από άνθρωπο. Ο πράκτορας λαμβάνει απόκριση 202 με έναν σύντομο κωδικό. Εγκρίνετε στο τηλέφωνο ή στη :part1 :part2 και ο πράκτορας επαναλαμβάνει το αίτημα μία μόνο φορά.',
    'you_are_signed_in_part1_but_your_account_does_not_admin_1a2cb08a' => 'Έχετε συνδεθεί :part1, αλλά ο λογαριασμός σας δεν έχει δικαιώματα διαχείρισης για το περιβάλλον: :part2. Την κονσόλα ενός περιβάλλοντος μπορούν να ανοίξουν οι ιδιοκτήτες, οι διαχειριστές και οι προγραμματιστές του οργανισμού στον οποίο ανήκει.',
    'you_can_turn_it_off_again_on_part1_part2_sessions_that_89d71a9d' => 'Μπορείτε να το απενεργοποιήσετε ξανά στην ενότητα: :part1 :part2. Οι συνεδρίες που τερματίστηκαν δεν επαναφέρονται.',
    'you_have_no_environment_to_open_yet_part1_part2_part3_t_3a10832d' => 'Δεν έχετε ακόμη περιβάλλον για άνοιγμα.:part1 Επιλέξτε :part2 :part3 για να δημιουργήσετε ένα ή ζητήστε πρόσβαση από έναν ιδιοκτήτη οργανισμού.',
