    '_part1_already_belongs_to_another_api_in_this_environme_bab95da8' => 'Το «:part1» ανήκει ήδη σε άλλο API αυτού του περιβάλλοντος. Ένα αίτημα διακριτικού ονομάζει πεδίο πρόσβασης μόνο με το κλειδί του, επομένως κάθε κλειδί μπορεί να ανήκει σε ένα API.',
    'only_the_console_can_give_an_app_part1_not_a_management_e9037160' => 'Μόνο η κονσόλα μπορεί να παραχωρήσει σε εφαρμογή το :part1 — όχι κλειδί διαχείρισης ούτε πράκτορας που ενεργεί εκ μέρους σας. Παραχωρήστε το στην κονσόλα, στη σελίδα Πεδίων πρόσβασης της εφαρμογής.',
    'point_claude_code_cursor_or_your_own_bot_at_this_enviro_7beb8319' => 'Κατευθύνετε το Claude Code, το Cursor ή το δικό σας bot στον διακομιστή MCP αυτού του περιβάλλοντος. Επισημαίνεται όταν ένας πράκτορας κάνει την πρώτη του κλήση.',
    'the_role_part1_cannot_be_held_in_this_organization_it_b_6fdeacd4' => 'Ο ρόλος [:part1] δεν μπορεί να κατέχεται σε αυτόν τον οργανισμό — ανήκει σε άλλον οργανισμό ή σε εφαρμογή που αυτός ο οργανισμός δεν μπορεί να χρησιμοποιήσει.',
    'every_primitive_the_console_is_built_from_sw_f2daecc0' => 'Όλα τα βασικά στοιχεία από τα οποία αποτελείται η κονσόλα. Αλλάξτε θέμα και στενέψτε το παράθυρο — η σουίτα δοκιμών δεν μπορεί να δει κανένα από τα δύο.',
