    'confirmation_link_resent_status' => 'Ένας νέος σύνδεσμος επιβεβαίωσης αποστέλλεται στη διεύθυνση :email. Ισχύει για 24 ώρες και αντικαθιστά κάθε προηγούμενο σύνδεσμο.',
    'its_members_are_signed_out_and_all_part1_it_owns_stop_s_80b419eb' => 'Τα μέλη του αποσυνδέονται και η παροχή ελέγχου ταυτότητας στα περιβάλλοντα που κατέχει (:part1) σταματά από το επόμενο αίτημα. Μπορείτε να ενεργοποιήσετε ξανά τον οργανισμό εδώ.',
    'the_platform_s_own_environment_on_part1_how_every_organ_acd123ad' => 'Το περιβάλλον της ίδιας της πλατφόρμας στο :part1: ο τρόπος σύνδεσης κάθε ιδιοκτήτη οργανισμού και κάθε χειριστή στο Cbox ID, καθώς και σε κάθε κονσόλα περιβάλλοντος. Μια αλλαγή εδώ ισχύει για όλους.',
    'what_part1_s_sign_in_page_offers_providers_from_the_env_efc01f8e' => 'Τι προσφέρει η σελίδα σύνδεσης του οργανισμού «:part1». Οι πάροχοι κληρονομούνται από το περιβάλλον· αυτός ο οργανισμός μπορεί να απενεργοποιήσει έναν ή να ορίσει δικό του στη θέση του.',
