    'pick_a_type_in_the_catalog_single_sign_on_di_9a947bbb' => 'Επιλέξτε τύπο στον κατάλογο — ενιαία σύνδεση, συγχρονισμό καταλόγου, σύστημα ανθρώπινου δυναμικού, webhook, ροή αρχείων καταγραφής.',
