    'setting_up_the_authenticator_app_for_this_en_90ff9348' => 'Η ρύθμιση της εφαρμογής ταυτοποίησης για αυτό το περιβάλλον απέτυχε. Το σφάλμα καταγράφηκε — φορτώστε ξανά τη σελίδα για να δοκιμάσετε πάλι.',
