    'the_most_recent_push_notifications_sent_to_t_cf468f18' => 'Οι πιο πρόσφατες ειδοποιήσεις push που στάλθηκαν σε αυτές τις συσκευές και οι λόγοι τυχόν αποτυχίας τους',
    'the_same_append_only_hash_chained_trail_as_t_36aa80ca' => 'Το ίδιο ίχνος με το αρχείο ελέγχου, μόνο με προσθήκες και συνδεδεμένο με αλυσίδα κατακερματισμού, με την αλυσίδα επαληθευμένη από άκρη σε άκρη.',
    'a_signed_message_to_your_endpoint_after_some_a8f5805d' => 'Ένα υπογεγραμμένο μήνυμα προς το τελικό σημείο σας αφού συμβεί κάτι — προστέθηκε μέλος, άλλαξε ρόλος — ώστε τα συστήματά σας να αντιδρούν χωρίς περιοδικές ερωτήσεις.',
    'an_app_that_accepts_this_environment_as_its__fe815b51' => 'Μια εφαρμογή που δέχεται αυτό το περιβάλλον ως πάροχο ταυτότητας SAML, ώστε οι χρήστες σας να συνδέονται με τον λογαριασμό που έχουν εδώ.',
    'an_organization_s_own_saml_or_oidc_identity__277b4568' => 'Ο δικός του πάροχος ταυτότητας SAML ή OIDC ενός οργανισμού — Okta, Entra ID, Google Workspace — ώστε τα άτομά του να συνδέονται με τον εργασιακό λογαριασμό τους.',
    'every_kind_of_integration_this_platform_has__4b2a3ee2' => 'Κάθε είδος ενσωμάτωσης που διαθέτει αυτή η πλατφόρμα. Ρυθμίστε μία από την κάρτα της ή διαχειριστείτε όσες έχετε — κάθε κάρτα οδηγεί στη σελίδα της αντίστοιχης ενσωμάτωσης.',
    'look_up_a_subject_s_audit_trail_actions_they_71f49e12' => 'Αναζητήστε το ίχνος ελέγχου ενός υποκειμένου — τις ενέργειες που πραγματοποίησε — για αίτημα πρόσβασης σε φορητή μορφή. Δεν προσφέρεται διαγραφή: η απόκρυψη στοιχείων μιας εγγραφής σε αλυσίδα κατακερματισμού θα κατέστρεφε την ένδειξη παραβίασης — δείτε την τεκμηρίωση.',
    'no_analytics_data_source_is_configured_or_re_1db9abb5' => 'Δεν έχει διαμορφωθεί ή δεν είναι προσβάσιμη πηγή αναλυτικών δεδομένων. Μόλις η πλατφόρμα καταγράφει χρήση — ή οριστεί ClickHouse DSN — η δραστηριότητα θα εμφανίζεται εδώ.',
    'people_connect_their_own_github_google_or_sl_261cd163' => 'Τα άτομα συνδέουν τον δικό τους λογαριασμό GitHub, Google ή Slack και οι εφαρμογές στις οποίες παραχωρείτε πρόσβαση καλούν αυτά τα API εκ μέρους τους με διακριτικό που ανανεώνεται εδώ.',
    'this_link_expires_after_two_minutes_and_only_2009db22' => 'Αυτός ο σύνδεσμος λήγει μετά από δύο λεπτά και λειτουργεί μόνο μία φορά, για τον λογαριασμό σας. Ανανεώνεται μόνος του όσο η σελίδα είναι ανοιχτή — μην κοινοποιείτε στιγμιότυπό του.',
